input.content:
{
  "version": 1,
  "note": "Discovery web for milestone 1. Each tile is a family of stages; each stage has its own needs, effects, and optional accident situation. Refs point at stage ids (tile.stage). 'any': true means any one ref is enough.",
  "tiles": [
    {
      "id": "fire", "name": "Fire", "col": 0, "kind": "Known at start",
      "sum": "Modern humans arrive able to make and keep fire. Mastery grows from there.",
      "stages": [
        { "id": "fire.make", "name": "Making and keeping fire", "known": true,
          "does": "Warmth, light, cooking, keeps predators back." },
        { "id": "fire.hearth", "name": "Built hearths",
          "needs": [
            { "t": "Knowledge", "text": "making fire", "refs": ["fire.make"] },
            { "t": "Way of life", "text": "staying two weeks or more in one spot" },
            { "t": "Material", "text": "flat stones to ring the fire" }
          ],
          "does": "Steady cooking heat; a place people gather and talk." },
        { "id": "fire.hot", "name": "High-heat fires",
          "needs": [
            { "t": "Knowledge", "text": "built hearths", "refs": ["fire.hearth"] },
            { "t": "Material", "text": "dense hardwood or plenty of fuel" },
            { "t": "Pressure", "text": "a job that needs real heat: hardening wood, treating flint" },
            { "t": "Person", "text": "interested in fire, practiced at tending it" }
          ],
          "does": "Hot enough to fire clay and heat-treat flint.",
          "accident": "A hearth dug into a sheltered pit runs far hotter than usual." },
        { "id": "fire.land", "name": "Burning the land",
          "needs": [
            { "t": "Knowledge", "text": "making fire", "refs": ["fire.make"] },
            { "t": "Material", "text": "dry grassland" },
            { "t": "Pressure", "text": "grazing herds that come back for fresh shoots" },
            { "t": "Person", "text": "bold" }
          ],
          "does": "Burned clearings draw game and help wild grain grow.",
          "accident": "After a wildfire (natural, or your lightning), herds return to the green shoots." }
      ]
    },
    {
      "id": "knap", "name": "Knapping", "col": 0, "kind": "Known at start",
      "sum": "Shaping stone into edges. Skill level matters for everything downstream.",
      "stages": [
        { "id": "knap.flake", "name": "Flakes and scrapers", "known": true,
          "does": "Cutting, scraping hides, carving wood." },
        { "id": "knap.blade", "name": "Long blades", "known": true,
          "does": "Better knives; blanks for points and awls." },
        { "id": "knap.haft", "name": "Hafted points",
          "needs": [
            { "t": "Knowledge", "text": "long blades", "refs": ["knap.blade"] },
            { "t": "Binding", "text": "sinew thread, plant twine, or tree resin", "refs": ["cord.sinew", "cord.twine"], "any": true },
            { "t": "Person", "text": "skilled knapper" }
          ],
          "does": "Stone points fixed to shafts: spears, later arrows." },
        { "id": "knap.heat", "name": "Heat-treated flint",
          "needs": [
            { "t": "Knowledge", "text": "high-heat fires", "refs": ["fire.hot"] },
            { "t": "Material", "text": "flint" },
            { "t": "Person", "text": "curious knapper" }
          ],
          "does": "Flint flakes cleaner; finer, sharper points.",
          "accident": "Flint left in the hearth overnight flakes far better the next day." }
      ]
    },
    {
      "id": "spear", "name": "Spear", "col": 0, "kind": "Known at start",
      "sum": "Hunting and defense. Armed adults also keep wolves at a distance.",
      "stages": [
        { "id": "spear.wood", "name": "Fire-hardened wooden spear", "known": true,
          "does": "Thrusting and short throws; counts toward band strength." },
        { "id": "spear.stone", "name": "Stone-tipped spear",
          "needs": [ { "t": "Knowledge", "text": "hafted points", "refs": ["knap.haft"] } ],
          "does": "Bigger game; more band strength." },
        { "id": "spear.light", "name": "Light throwing spears",
          "needs": [
            { "t": "Knowledge", "text": "wooden spear", "refs": ["spear.wood"] },
            { "t": "Material", "text": "straight saplings" },
            { "t": "Pressure", "text": "fast prey that won't let hunters close" },
            { "t": "Person", "text": "skilled hunter" }
          ],
          "does": "Longer throws; the base for the spear-thrower." }
      ]
    },
    {
      "id": "forage", "name": "Foraging", "col": 0, "kind": "Known at start",
      "sum": "Knowing which plants feed you, where and when.",
      "stages": [
        { "id": "forage.rounds", "name": "Patches and seasonal rounds", "known": true,
          "does": "The band moves through the year to where food is." },
        { "id": "forage.lore", "name": "Plant lore",
          "needs": [
            { "t": "Knowledge", "text": "shared stories, so lore outlives one person", "refs": ["lang.story"] },
            { "t": "Person", "text": "interested in plants; elders still alive to teach" }
          ],
          "does": "Medicines (fewer deaths), poisons, knowing which plants make good fiber." },
        { "id": "forage.nuts", "name": "Leaching nuts and acorns",
          "needs": [
            { "t": "Knowledge", "text": "seasonal rounds", "refs": ["forage.rounds"] },
            { "t": "Material", "text": "oaks or nut trees, running water" },
            { "t": "Pressure", "text": "a hungry autumn" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Bitter nuts become a big, storable food.",
          "accident": "Acorns dropped in a stream lose their bitterness." }
      ]
    },
    {
      "id": "lang", "name": "Language", "col": 0, "kind": "Known at start",
      "sum": "Full spoken language from day one. Its stages decide how far and how faithfully knowledge and beliefs travel.",
      "stages": [
        { "id": "lang.speech", "name": "Everyday speech and teaching", "known": true,
          "does": "Skills taught by showing plus words; every discovery adds new words." },
        { "id": "lang.story", "name": "Shared stories",
          "needs": [
            { "t": "Event", "text": "a remembered event retold by several people: a great hunt, a disaster, an omen" },
            { "t": "Pressure", "text": "long evenings together, such as winters around the fire" },
            { "t": "Person", "text": "sociable storyteller or elder" }
          ],
          "does": "Beliefs and lessons outlive the people who lived them; less drift between generations. Myths about you start here." },
        { "id": "lang.ritual", "name": "Ritual speech and song",
          "needs": [
            { "t": "Knowledge", "text": "shared stories", "refs": ["lang.story"] },
            { "t": "Belief", "text": "rites for the dead, or a belief built on omens", "refs": ["burial.rites"] },
            { "t": "Person", "text": "interested in spirits" }
          ],
          "does": "Rituals hit harder; belief strength and group cohesion rise." },
        { "id": "lang.count", "name": "Counting and tally marks",
          "needs": [
            { "t": "Pressure", "text": "keeping track of stores or of moons until a season", "refs": ["store.pit", "store.basket"], "any": true },
            { "t": "Material", "text": "bone or wood to notch" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Tracking seasons and stores; helps grain timing; groundwork for trade later." }
      ]
    },
    {
      "id": "cord", "name": "Cordage", "col": 1, "kind": "Technology",
      "sum": "Two routes in. Sinew cultures sew and string bows; plant cultures fish, build and net. Both opens everything.",
      "stages": [
        { "id": "cord.sinew", "name": "Sinew thread", "variant": "hunter route",
          "needs": [
            { "t": "Material", "text": "sinew from butchered game", "refs": ["spear.wood"] },
            { "t": "Pressure", "text": "things that need binding: hafting, mending" },
            { "t": "Person", "text": "dexterous, interested in animals" }
          ],
          "does": "Sewing, strong bowstrings, tight lashings.",
          "accident": "Wet sinew wrapped around a cracked handle dries rock-hard." },
        { "id": "cord.twine", "name": "Plant twine", "variant": "gatherer route",
          "needs": [
            { "t": "Material", "text": "fibrous plants: nettle, reeds, bark" },
            { "t": "Pressure", "text": "big foraging hauls to carry and tie" },
            { "t": "Person", "text": "dexterous, interested in plants" }
          ],
          "does": "Basket lashing, fishing lines, long cords.",
          "accident": "Stems absently twisted during a rest hold together under pull." },
        { "id": "cord.ply", "name": "Two-ply string",
          "needs": [
            { "t": "Knowledge", "text": "either kind of thread", "refs": ["cord.sinew", "cord.twine"], "any": true },
            { "t": "Person", "text": "practiced cord-maker" }
          ],
          "does": "Stronger everything: bowstrings, hafting, lines." },
        { "id": "cord.rope", "name": "Rope",
          "needs": [
            { "t": "Knowledge", "text": "two-ply string made from plants (sinew is too short)", "refs": ["cord.ply", "cord.twine"] },
            { "t": "Pressure", "text": "hauling or building" }
          ],
          "does": "Lashing shelters, hauling, rafts later." },
        { "id": "cord.net", "name": "Knotted nets",
          "needs": [
            { "t": "Knowledge", "text": "rope", "refs": ["cord.rope"] },
            { "t": "Pressure", "text": "water to fish, or loads to carry" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Fishing nets and carrying nets." }
      ]
    },
    {
      "id": "dry", "name": "Drying & smoking", "col": 1, "kind": "Technology",
      "sum": "Making food last into the lean season. Usually starts by accident.",
      "stages": [
        { "id": "dry.keep", "name": "Food that keeps",
          "needs": [
            { "t": "Knowledge", "text": "fire", "refs": ["fire.make"] },
            { "t": "Material", "text": "more meat, fish or berries than can be eaten" }
          ],
          "does": "Food lasts days instead of hours.",
          "accident": "Meat left hanging in the smoke is still good a week later. The main way in." },
        { "id": "dry.rack", "name": "Drying racks",
          "needs": [
            { "t": "Knowledge", "text": "food that keeps, and a built hearth or steady sun", "refs": ["dry.keep", "fire.hearth"] },
            { "t": "Material", "text": "poles" },
            { "t": "Pressure", "text": "a hard winter after a good autumn" }
          ],
          "does": "Preserve a whole kill or harvest; real stores become possible." },
        { "id": "dry.smoke", "name": "Smoking",
          "needs": [
            { "t": "Knowledge", "text": "drying racks", "refs": ["dry.rack"] },
            { "t": "Material", "text": "a surplus of fish or meat" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Food lasts months. A fish run can now feed a winter." }
      ]
    },
    {
      "id": "atl", "name": "Spear-thrower", "col": 1, "kind": "Technology",
      "sum": "A hooked stick that throws a spear much farther. One road to the bow.",
      "stages": [
        { "id": "atl.hook", "name": "Hooked throwing stick",
          "needs": [
            { "t": "Knowledge", "text": "light throwing spears", "refs": ["spear.light"] },
            { "t": "Material", "text": "hardwood" },
            { "t": "Pressure", "text": "wary prey that bolts early" },
            { "t": "Person", "text": "skilled hunter" }
          ],
          "does": "Kills at range; more band strength." },
        { "id": "atl.dart", "name": "Fletched darts",
          "needs": [
            { "t": "Knowledge", "text": "hooked throwing stick plus any thread for binding", "refs": ["atl.hook", "cord.ply"] },
            { "t": "Material", "text": "feathers" }
          ],
          "does": "Accurate darts. The idea of fletching carries over to arrows." }
      ]
    },
    {
      "id": "grind", "name": "Grinding stones", "col": 1, "kind": "Technology",
      "sum": "Turning hard seeds and nuts into food. The heavier stages need a band that stays put.",
      "stages": [
        { "id": "grind.pound", "name": "Pounding",
          "needs": [
            { "t": "Knowledge", "text": "flakes, foraging", "refs": ["knap.flake", "forage.rounds"] },
            { "t": "Material", "text": "a hammerstone plus nuts or seeds" },
            { "t": "Pressure", "text": "plenty of starchy food that's hard to eat whole" }
          ],
          "does": "Nuts and seeds become food.",
          "accident": "Nuts cracked on the same rock for weeks leave a smooth hollow." },
        { "id": "grind.mortar", "name": "Mortar and pestle",
          "needs": [
            { "t": "Knowledge", "text": "pounding", "refs": ["grind.pound"] },
            { "t": "Material", "text": "a hollowed stone or log" },
            { "t": "Way of life", "text": "returning to the same place", "refs": ["camp.return"] }
          ],
          "does": "Faster, finer meal." },
        { "id": "grind.slab", "name": "Grinding slab",
          "needs": [
            { "t": "Knowledge", "text": "mortar and pestle", "refs": ["grind.mortar"] },
            { "t": "Material", "text": "a big flat stone (too heavy to carry) and wild grain" },
            { "t": "Way of life", "text": "long stays", "refs": ["camp.long"] }
          ],
          "does": "Flour. Wild grain becomes worth the effort." }
      ]
    },
    {
      "id": "dog", "name": "Dog companions", "col": 1, "kind": "Domestication",
      "sum": "Wolves become dogs over generations, but only if the band is strong enough that wolves lurk instead of attack.",
      "stages": [
        { "id": "dog.lurk", "name": "Wolves at the edge of camp",
          "needs": [
            { "t": "Material", "text": "a wolf pack in range" },
            { "t": "Pressure", "text": "meat scraps left at camp", "refs": ["spear.wood"] },
            { "t": "Deterrence", "text": "band strength high enough that wolves stay back: armed adults, fire", "refs": ["fire.make"] }
          ],
          "does": "Not a discovery, a situation. Wolves scavenge and their howls warn of other predators." },
        { "id": "dog.pup", "name": "A pup raised in camp",
          "needs": [
            { "t": "Situation", "text": "wolves at the edge of camp", "refs": ["dog.lurk"] },
            { "t": "Culture", "text": "no taboo against wolves" },
            { "t": "Person", "text": "calm, interested in animals" }
          ],
          "does": "One tame wolf. Its pups are tamer.",
          "accident": "An orphaned pup is found after its mother is killed. The main way in." },
        { "id": "dog.camp", "name": "Camp dogs",
          "needs": [
            { "t": "Knowledge", "text": "pups raised in camp", "refs": ["dog.pup"] },
            { "t": "Time", "text": "several generations of the tamest pups kept" }
          ],
          "does": "Guarding (more band strength), cleaning scraps, warmth." },
        { "id": "dog.hunt", "name": "Hunting dogs",
          "needs": [
            { "t": "Knowledge", "text": "camp dogs", "refs": ["dog.camp"] },
            { "t": "Person", "text": "skilled hunter who works with them" }
          ],
          "does": "Tracking and cornering prey. Hunts succeed far more often." }
      ]
    },
    {
      "id": "burial", "name": "Burial & rites", "col": 1, "kind": "Belief", "belief": true,
      "sum": "The first culture tile. Ties people to a place and creates the ritual specialist.",
      "stages": [
        { "id": "burial.cover", "name": "Covering the dead",
          "needs": [
            { "t": "Event", "text": "the death of someone loved or respected" },
            { "t": "Person", "text": "grieving deeply" }
          ],
          "does": "Graves become places that matter." },
        { "id": "burial.goods", "name": "Grave goods",
          "needs": [
            { "t": "Knowledge", "text": "covering the dead", "refs": ["burial.cover"] },
            { "t": "Belief", "text": "the dead go on somewhere, or are linked to the sky one" }
          ],
          "does": "Objects take on meaning beyond use." },
        { "id": "burial.rites", "name": "Ancestor rites",
          "needs": [
            { "t": "Knowledge", "text": "grave goods and shared stories", "refs": ["burial.goods", "lang.story"] },
            { "t": "Person", "text": "interested in spirits" }
          ],
          "does": "A ritual specialist emerges. Strong attachment to place." }
      ]
    },
    {
      "id": "ochre", "name": "Ochre & art", "col": 2, "kind": "Belief", "belief": true,
      "sum": "Art as belief made visible. Cave walls come from the Synty Alpine caves.",
      "stages": [
        { "id": "ochre.body", "name": "Body paint",
          "needs": [
            { "t": "Material", "text": "ochre" },
            { "t": "Pressure", "text": "a ritual, a status, or a need to mark who 'we' are" },
            { "t": "Person", "text": "interested in spirits, sky or people" }
          ],
          "does": "Group identity; ritual looks the part.",
          "accident": "Someone notices the red stain ochre leaves on their hands." },
        { "id": "ochre.hand", "name": "Handprints and marks",
          "needs": [
            { "t": "Knowledge", "text": "body paint", "refs": ["ochre.body"] },
            { "t": "Material", "text": "a cave or sheltered rock wall" }
          ],
          "does": "Places get claimed and remembered." },
        { "id": "ochre.paint", "name": "Cave paintings",
          "needs": [
            { "t": "Knowledge", "text": "handprints, and stories worth showing", "refs": ["ochre.hand", "lang.story"] },
            { "t": "Person", "text": "interested in spirits or animals, skilled hands" }
          ],
          "does": "Beliefs become very stable. Hunting magic beliefs form." },
        { "id": "ochre.figure", "name": "Carved and fired figures",
          "needs": [
            { "t": "Knowledge", "text": "cave paintings or grave goods", "refs": ["ochre.paint", "burial.goods"], "any": true },
            { "t": "Material", "text": "soft stone, bone or ivory; or clay that has been fired", "refs": ["pot.fired"] }
          ],
          "does": "Portable sacred objects. The fired-clay version is real: figurines came 10,000 years before pots." }
      ]
    },
    {
      "id": "bask", "name": "Basketry", "col": 2, "kind": "Technology",
      "sum": "Carrying and holding more than hands can.",
      "stages": [
        { "id": "bask.bundle", "name": "Bundled reed carriers",
          "needs": [
            { "t": "Material", "text": "reeds, grass or willow" },
            { "t": "Pressure", "text": "gathering more than hands can carry" }
          ],
          "does": "Bigger foraging hauls." },
        { "id": "bask.woven", "name": "Woven baskets",
          "needs": [
            { "t": "Knowledge", "text": "bundled carriers plus plant twine", "refs": ["bask.bundle", "cord.twine"] },
            { "t": "Person", "text": "patient, interested in plants" }
          ],
          "does": "Durable carriers; fish traps become possible." },
        { "id": "bask.tight", "name": "Tight baskets that hold seed",
          "needs": [
            { "t": "Knowledge", "text": "woven baskets", "refs": ["bask.woven"] },
            { "t": "Pressure", "text": "small seeds worth collecting" }
          ],
          "does": "Seed harvests and basket stores." },
        { "id": "bask.sealed", "name": "Pitch-sealed baskets",
          "needs": [
            { "t": "Knowledge", "text": "tight baskets and a hearth", "refs": ["bask.tight", "fire.hearth"] },
            { "t": "Material", "text": "tree resin" }
          ],
          "does": "Carry water; boil food with hot stones." }
      ]
    },
    {
      "id": "hide", "name": "Hide & sewing", "col": 2, "kind": "Technology",
      "sum": "From wrapped skins to fitted clothes. Fitted clothing opens colder ground.",
      "stages": [
        { "id": "hide.wrap", "name": "Wrapped hides",
          "needs": [
            { "t": "Material", "text": "hides from hunting", "refs": ["spear.wood"] },
            { "t": "Pressure", "text": "a cold season" }
          ],
          "does": "Basic warmth." },
        { "id": "hide.scrape", "name": "Scraped and dried hides",
          "needs": [
            { "t": "Knowledge", "text": "wrapped hides and scrapers", "refs": ["hide.wrap", "knap.flake"] },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Hides last; covers for shelters." },
        { "id": "hide.awl", "name": "Stitched with an awl",
          "needs": [
            { "t": "Knowledge", "text": "scraped hides plus any thread", "refs": ["hide.scrape", "cord.sinew"] },
            { "t": "Material", "text": "bone for awls" }
          ],
          "does": "Bags, simple garments, joined shelter covers." },
        { "id": "hide.tent", "name": "Hide tents",
          "needs": [
            { "t": "Knowledge", "text": "stitched hides and cord", "refs": ["hide.awl", "cord.ply"] },
            { "t": "Material", "text": "long poles" }
          ],
          "does": "Real shelter; long stays get easier." },
        { "id": "hide.needle", "name": "Fitted clothing",
          "needs": [
            { "t": "Knowledge", "text": "awl stitching and long blades", "refs": ["hide.awl", "knap.blade"] },
            { "t": "Material", "text": "bone for eyed needles" },
            { "t": "Pressure", "text": "severe cold" },
            { "t": "Person", "text": "dexterous" }
          ],
          "does": "Big cold tolerance. Harsh lands become livable." }
      ]
    },
    {
      "id": "fish", "name": "Fishing", "col": 2, "kind": "Technology",
      "sum": "Turning a river into a reliable larder. Two or more methods make it dependable enough to settle on.",
      "stages": [
        { "id": "fish.spear", "name": "Spearing and hand catching",
          "needs": [
            { "t": "Knowledge", "text": "spear", "refs": ["spear.wood"] },
            { "t": "Material", "text": "a river or lake with fish" },
            { "t": "Pressure", "text": "food short, water close" },
            { "t": "Person", "text": "interested in water" }
          ],
          "does": "Some fish, unreliably.",
          "accident": "Fish trapped in a shrinking pool are caught by hand." },
        { "id": "fish.weir", "name": "Stake weirs",
          "needs": [
            { "t": "Knowledge", "text": "spearing fish", "refs": ["fish.spear"] },
            { "t": "Material", "text": "stakes and a seasonal fish run" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Big catches during runs." },
        { "id": "fish.trap", "name": "Basket traps",
          "needs": [ { "t": "Knowledge", "text": "woven baskets and spearing fish", "refs": ["bask.woven", "fish.spear"] } ],
          "does": "Steady catch with little work." },
        { "id": "fish.line", "name": "Hook and line",
          "needs": [
            { "t": "Knowledge", "text": "any thread plus long blades", "refs": ["cord.ply", "knap.blade"] },
            { "t": "Material", "text": "bone for hooks" }
          ],
          "does": "Fishing deep water." },
        { "id": "fish.net", "name": "Nets",
          "needs": [ { "t": "Knowledge", "text": "knotted nets", "refs": ["cord.net"] } ],
          "does": "The biggest, most reliable catches." }
      ]
    },
    {
      "id": "bow", "name": "Bow & arrow", "col": 3, "kind": "Technology",
      "sum": "Killing at range without being seen.",
      "stages": [
        { "id": "bow.simple", "name": "Simple bow",
          "needs": [
            { "t": "Material", "text": "springy wood (yew, ash) or bamboo" },
            { "t": "Knowledge", "text": "two-ply string for the bowstring", "refs": ["cord.ply"] },
            { "t": "Knowledge", "text": "spear-thrower, or long practice throwing", "refs": ["atl.hook"] },
            { "t": "Pressure", "text": "fast prey, or conflict with neighbors" },
            { "t": "Person", "text": "skilled hunter or woodworker, curious" }
          ],
          "does": "Range and stealth; more band strength.",
          "accident": "A bent sapling tied for a snare whips a stick across camp." },
        { "id": "bow.fletch", "name": "Fletched arrows",
          "needs": [
            { "t": "Knowledge", "text": "simple bow (fletched darts help a lot)", "refs": ["bow.simple"] },
            { "t": "Material", "text": "feathers" }
          ],
          "does": "Accuracy." },
        { "id": "bow.stone", "name": "Stone-tipped arrows",
          "needs": [ { "t": "Knowledge", "text": "simple bow and hafted points", "refs": ["bow.simple", "knap.haft"] } ],
          "does": "Lethal against big game." },
        { "id": "bow.backed", "name": "Sinew-backed bow", "variant": "needs both cordage routes",
          "needs": [ { "t": "Knowledge", "text": "simple bow, sinew thread and plant twine", "refs": ["bow.simple", "cord.sinew", "cord.twine"] } ],
          "does": "Much stronger bows." }
      ]
    },
    {
      "id": "store", "name": "Storage", "col": 3, "kind": "Technology",
      "sum": "Changes how a band thinks about the future. Things worth guarding appear.",
      "stages": [
        { "id": "store.cache", "name": "Caches under stones",
          "needs": [
            { "t": "Pressure", "text": "seasonal glut followed by scarcity" },
            { "t": "Person", "text": "cautious planner" }
          ],
          "does": "A small buffer against hunger.",
          "accident": "Food hidden from wolves is found intact weeks later." },
        { "id": "store.pit", "name": "Lined pits",
          "needs": [
            { "t": "Knowledge", "text": "caches, plus food that keeps", "refs": ["store.cache", "dry.keep"] },
            { "t": "Material", "text": "dry, diggable ground" },
            { "t": "Way of life", "text": "returning to the same place", "refs": ["camp.return"] }
          ],
          "does": "Winter stores." },
        { "id": "store.basket", "name": "Basket stores",
          "needs": [ { "t": "Knowledge", "text": "caches and tight baskets", "refs": ["store.cache", "bask.tight"] } ],
          "does": "Seed and nut stores." },
        { "id": "store.raised", "name": "Raised caches",
          "needs": [
            { "t": "Knowledge", "text": "pits or basket stores, plus rope", "refs": ["store.pit", "store.basket", "cord.rope"] },
            { "t": "Pressure", "text": "animals raiding stores" }
          ],
          "does": "Stores safe from animals. Big enough to be worth stealing." }
      ]
    },
    {
      "id": "camp", "name": "Base camp", "col": 4, "kind": "Way of life", "belief": true,
      "sum": "Not a tool: a band choosing to mostly stay put. Unlocks heavy, fragile things, and new problems like disease.",
      "stages": [
        { "id": "camp.return", "name": "Seasonal return",
          "needs": [
            { "t": "Knowledge", "text": "seasonal rounds", "refs": ["forage.rounds"] },
            { "t": "Material", "text": "a place with dependable seasonal food" },
            { "t": "Culture", "text": "attachment to place; graves nearby help", "refs": ["burial.cover"] }
          ],
          "does": "The same camp every year; things can be left behind." },
        { "id": "camp.long", "name": "Long stays",
          "needs": [
            { "t": "Way of life", "text": "seasonal return", "refs": ["camp.return"] },
            { "t": "Knowledge", "text": "any storage", "refs": ["store.cache"] },
            { "t": "Food", "text": "one reliable local food: weirs, nuts, or wild grain", "refs": ["fish.weir", "forage.nuts", "grain.harvest"], "any": true },
            { "t": "Pressure", "text": "moving costs more than staying: many children or elders, heavy stores" }
          ],
          "does": "Most of the year in one place. Heavy tools make sense." },
        { "id": "camp.year", "name": "Year-round base",
          "needs": [
            { "t": "Way of life", "text": "long stays", "refs": ["camp.long"] },
            { "t": "Knowledge", "text": "pits or raised stores", "refs": ["store.pit", "store.raised"], "any": true },
            { "t": "Food", "text": "two reliable food sources" },
            { "t": "Shelter", "text": "hide tents or sturdier", "refs": ["hide.tent"] }
          ],
          "does": "Population grows; disease risk grows; the next milestone's villages start here." }
      ]
    },
    {
      "id": "pot", "name": "Pottery", "col": 5, "kind": "Technology",
      "sum": "The showcase of this milestone. Fired clay can happen early by accident, but pots need everything else to line up.",
      "stages": [
        { "id": "pot.fired", "name": "Fired clay",
          "needs": [
            { "t": "Material", "text": "clay" },
            { "t": "Knowledge", "text": "a built hearth", "refs": ["fire.hearth"] }
          ],
          "does": "The insight that fire hardens clay. Figurines possible.",
          "accident": "Clay pressed or dropped near a hearth comes out hard. The main way in." },
        { "id": "pot.pinch", "name": "Pinch pots",
          "needs": [
            { "t": "Knowledge", "text": "fired clay and high-heat fires", "refs": ["pot.fired", "fire.hot"] },
            { "t": "Way of life", "text": "long stays (pots are too heavy for nomads)", "refs": ["camp.long"] },
            { "t": "Pressure", "text": "a need to cook or hold liquids" },
            { "t": "Person", "text": "curious, interested in fire or stone" }
          ],
          "does": "Small vessels." },
        { "id": "pot.coil", "name": "Coiled pots",
          "needs": [
            { "t": "Knowledge", "text": "pinch pots", "refs": ["pot.pinch"] },
            { "t": "Person", "text": "patient, practiced potter" }
          ],
          "does": "Real cooking pots: stews and porridge (grain becomes much more useful); sealed storage." },
        { "id": "pot.pit", "name": "Pit firing",
          "needs": [ { "t": "Knowledge", "text": "coiled pots and high-heat fires", "refs": ["pot.coil", "fire.hot"] } ],
          "does": "Reliable, sturdy pots. Kilns are next milestone." }
      ]
    },
    {
      "id": "grain", "name": "Tending wild grain", "col": 5, "kind": "Technology",
      "sum": "The doorway to farming, which is the next milestone.",
      "stages": [
        { "id": "grain.harvest", "name": "Harvesting wild stands",
          "needs": [
            { "t": "Material", "text": "wild grasses with heavy seed" },
            { "t": "Knowledge", "text": "something to hold seed: tight baskets", "refs": ["bask.tight"] },
            { "t": "Pressure", "text": "food running short" }
          ],
          "does": "A seasonal grain haul." },
        { "id": "grain.clear", "name": "Clearing competitors",
          "needs": [
            { "t": "Knowledge", "text": "harvesting, plus seasonal return or burning the land", "refs": ["grain.harvest", "camp.return", "fire.land"] }
          ],
          "does": "Bigger wild stands near camp." },
        { "id": "grain.scatter", "name": "Scattering seed nearby",
          "needs": [
            { "t": "Knowledge", "text": "clearing competitors", "refs": ["grain.clear"] },
            { "t": "Way of life", "text": "long stays", "refs": ["camp.long"] }
          ],
          "does": "Grain grows where you want it.",
          "accident": "Seed spilled on the camp's rubbish heap sprouts the next spring." },
        { "id": "grain.select", "name": "Keeping the best seed",
          "needs": [
            { "t": "Knowledge", "text": "scattering seed and grinding slabs", "refs": ["grain.scatter", "grind.slab"] },
            { "t": "Knowledge", "text": "storage; tally marks for timing help", "refs": ["store.basket", "lang.count"] },
            { "t": "Person", "text": "patient, interested in plants" }
          ],
          "does": "Seeds get bigger each generation. Farming begins next milestone." }
      ]
    }
  ]
}

toolu_01MTgsVr1oguvYUXocqRNCnM.content:
{
  "version": 1,
  "note": "Discovery web for milestone 1. Each tile is a family of stages; each stage has its own needs, effects, and optional accident situation. Refs point at stage ids (tile.stage). 'any': true means any one ref is enough.",
  "tiles": [
    {
      "id": "fire", "name": "Fire", "col": 0, "kind": "Known at start",
      "sum": "Modern humans arrive able to make and keep fire. Mastery grows from there.",
      "stages": [
        { "id": "fire.make", "name": "Making and keeping fire", "known": true,
          "does": "Warmth, light, cooking, keeps predators back." },
        { "id": "fire.hearth", "name": "Built hearths",
          "needs": [
            { "t": "Knowledge", "text": "making fire", "refs": ["fire.make"] },
            { "t": "Way of life", "text": "staying two weeks or more in one spot" },
            { "t": "Material", "text": "flat stones to ring the fire" }
          ],
          "does": "Steady cooking heat; a place people gather and talk." },
        { "id": "fire.hot", "name": "High-heat fires",
          "needs": [
            { "t": "Knowledge", "text": "built hearths", "refs": ["fire.hearth"] },
            { "t": "Material", "text": "dense hardwood or plenty of fuel" },
            { "t": "Pressure", "text": "a job that needs real heat: hardening wood, treating flint" },
            { "t": "Person", "text": "interested in fire, practiced at tending it" }
          ],
          "does": "Hot enough to fire clay and heat-treat flint.",
          "accident": "A hearth dug into a sheltered pit runs far hotter than usual." },
        { "id": "fire.land", "name": "Burning the land",
          "needs": [
            { "t": "Knowledge", "text": "making fire", "refs": ["fire.make"] },
            { "t": "Material", "text": "dry grassland" },
            { "t": "Pressure", "text": "grazing herds that come back for fresh shoots" },
            { "t": "Person", "text": "bold" }
          ],
          "does": "Burned clearings draw game and help wild grain grow.",
          "accident": "After a wildfire (natural, or your lightning), herds return to the green shoots." }
      ]
    },
    {
      "id": "knap", "name": "Knapping", "col": 0, "kind": "Known at start",
      "sum": "Shaping stone into edges. Skill level matters for everything downstream.",
      "stages": [
        { "id": "knap.flake", "name": "Flakes and scrapers", "known": true,
          "does": "Cutting, scraping hides, carving wood." },
        { "id": "knap.blade", "name": "Long blades", "known": true,
          "does": "Better knives; blanks for points and awls." },
        { "id": "knap.haft", "name": "Hafted points",
          "needs": [
            { "t": "Knowledge", "text": "long blades", "refs": ["knap.blade"] },
            { "t": "Binding", "text": "sinew thread, plant twine, or tree resin", "refs": ["cord.sinew", "cord.twine"], "any": true },
            { "t": "Person", "text": "skilled knapper" }
          ],
          "does": "Stone points fixed to shafts: spears, later arrows." },
        { "id": "knap.heat", "name": "Heat-treated flint",
          "needs": [
            { "t": "Knowledge", "text": "high-heat fires", "refs": ["fire.hot"] },
            { "t": "Material", "text": "flint" },
            { "t": "Person", "text": "curious knapper" }
          ],
          "does": "Flint flakes cleaner; finer, sharper points.",
          "accident": "Flint left in the hearth overnight flakes far better the next day." }
      ]
    },
    {
      "id": "spear", "name": "Spear", "col": 0, "kind": "Known at start",
      "sum": "Hunting and defense. Armed adults also keep wolves at a distance.",
      "stages": [
        { "id": "spear.wood", "name": "Fire-hardened wooden spear", "known": true,
          "does": "Thrusting and short throws; counts toward band strength." },
        { "id": "spear.stone", "name": "Stone-tipped spear",
          "needs": [ { "t": "Knowledge", "text": "hafted points", "refs": ["knap.haft"] } ],
          "does": "Bigger game; more band strength." },
        { "id": "spear.light", "name": "Light throwing spears",
          "needs": [
            { "t": "Knowledge", "text": "wooden spear", "refs": ["spear.wood"] },
            { "t": "Material", "text": "straight saplings" },
            { "t": "Pressure", "text": "fast prey that won't let hunters close" },
            { "t": "Person", "text": "skilled hunter" }
          ],
          "does": "Longer throws; the base for the spear-thrower." }
      ]
    },
    {
      "id": "forage", "name": "Foraging", "col": 0, "kind": "Known at start",
      "sum": "Knowing which plants feed you, where and when.",
      "stages": [
        { "id": "forage.rounds", "name": "Patches and seasonal rounds", "known": true,
          "does": "The band moves through the year to where food is." },
        { "id": "forage.lore", "name": "Plant lore",
          "needs": [
            { "t": "Knowledge", "text": "shared stories, so lore outlives one person", "refs": ["lang.story"] },
            { "t": "Person", "text": "interested in plants; elders still alive to teach" }
          ],
          "does": "Medicines (fewer deaths), poisons, knowing which plants make good fiber." },
        { "id": "forage.nuts", "name": "Leaching nuts and acorns",
          "needs": [
            { "t": "Knowledge", "text": "seasonal rounds", "refs": ["forage.rounds"] },
            { "t": "Material", "text": "oaks or nut trees, running water" },
            { "t": "Pressure", "text": "a hungry autumn" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Bitter nuts become a big, storable food.",
          "accident": "Acorns dropped in a stream lose their bitterness." }
      ]
    },
    {
      "id": "lang", "name": "Language", "col": 0, "kind": "Known at start",
      "sum": "Full spoken language from day one. Its stages decide how far and how faithfully knowledge and beliefs travel.",
      "stages": [
        { "id": "lang.speech", "name": "Everyday speech and teaching", "known": true,
          "does": "Skills taught by showing plus words; every discovery adds new words." },
        { "id": "lang.story", "name": "Shared stories",
          "needs": [
            { "t": "Event", "text": "a remembered event retold by several people: a great hunt, a disaster, an omen" },
            { "t": "Pressure", "text": "long evenings together, such as winters around the fire" },
            { "t": "Person", "text": "sociable storyteller or elder" }
          ],
          "does": "Beliefs and lessons outlive the people who lived them; less drift between generations. Myths about you start here." },
        { "id": "lang.ritual", "name": "Ritual speech and song",
          "needs": [
            { "t": "Knowledge", "text": "shared stories", "refs": ["lang.story"] },
            { "t": "Belief", "text": "rites for the dead, or a belief built on omens", "refs": ["burial.rites"] },
            { "t": "Person", "text": "interested in spirits" }
          ],
          "does": "Rituals hit harder; belief strength and group cohesion rise." },
        { "id": "lang.count", "name": "Counting and tally marks",
          "needs": [
            { "t": "Pressure", "text": "keeping track of stores or of moons until a season", "refs": ["store.pit", "store.basket"], "any": true },
            { "t": "Material", "text": "bone or wood to notch" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Tracking seasons and stores; helps grain timing; groundwork for trade later." }
      ]
    },
    {
      "id": "cord", "name": "Cordage", "col": 1, "kind": "Technology",
      "sum": "Two routes in. Sinew cultures sew and string bows; plant cultures fish, build and net. Both opens everything.",
      "stages": [
        { "id": "cord.sinew", "name": "Sinew thread", "variant": "hunter route",
          "needs": [
            { "t": "Material", "text": "sinew from butchered game", "refs": ["spear.wood"] },
            { "t": "Pressure", "text": "things that need binding: hafting, mending" },
            { "t": "Person", "text": "dexterous, interested in animals" }
          ],
          "does": "Sewing, strong bowstrings, tight lashings.",
          "accident": "Wet sinew wrapped around a cracked handle dries rock-hard." },
        { "id": "cord.twine", "name": "Plant twine", "variant": "gatherer route",
          "needs": [
            { "t": "Material", "text": "fibrous plants: nettle, reeds, bark" },
            { "t": "Pressure", "text": "big foraging hauls to carry and tie" },
            { "t": "Person", "text": "dexterous, interested in plants" }
          ],
          "does": "Basket lashing, fishing lines, long cords.",
          "accident": "Stems absently twisted during a rest hold together under pull." },
        { "id": "cord.ply", "name": "Two-ply string",
          "needs": [
            { "t": "Knowledge", "text": "either kind of thread", "refs": ["cord.sinew", "cord.twine"], "any": true },
            { "t": "Person", "text": "practiced cord-maker" }
          ],
          "does": "Stronger everything: bowstrings, hafting, lines." },
        { "id": "cord.rope", "name": "Rope",
          "needs": [
            { "t": "Knowledge", "text": "two-ply string made from plants (sinew is too short)", "refs": ["cord.ply", "cord.twine"] },
            { "t": "Pressure", "text": "hauling or building" }
          ],
          "does": "Lashing shelters, hauling, rafts later." },
        { "id": "cord.net", "name": "Knotted nets",
          "needs": [
            { "t": "Knowledge", "text": "rope", "refs": ["cord.rope"] },
            { "t": "Pressure", "text": "water to fish, or loads to carry" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Fishing nets and carrying nets." }
      ]
    },
    {
      "id": "dry", "name": "Drying & smoking", "col": 1, "kind": "Technology",
      "sum": "Making food last into the lean season. Usually starts by accident.",
      "stages": [
        { "id": "dry.keep", "name": "Food that keeps",
          "needs": [
            { "t": "Knowledge", "text": "fire", "refs": ["fire.make"] },
            { "t": "Material", "text": "more meat, fish or berries than can be eaten" }
          ],
          "does": "Food lasts days instead of hours.",
          "accident": "Meat left hanging in the smoke is still good a week later. The main way in." },
        { "id": "dry.rack", "name": "Drying racks",
          "needs": [
            { "t": "Knowledge", "text": "food that keeps, and a built hearth or steady sun", "refs": ["dry.keep", "fire.hearth"] },
            { "t": "Material", "text": "poles" },
            { "t": "Pressure", "text": "a hard winter after a good autumn" }
          ],
          "does": "Preserve a whole kill or harvest; real stores become possible." },
        { "id": "dry.smoke", "name": "Smoking",
          "needs": [
            { "t": "Knowledge", "text": "drying racks", "refs": ["dry.rack"] },
            { "t": "Material", "text": "a surplus of fish or meat" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Food lasts months. A fish run can now feed a winter." }
      ]
    },
    {
      "id": "atl", "name": "Spear-thrower", "col": 1, "kind": "Technology",
      "sum": "A hooked stick that throws a spear much farther. One road to the bow.",
      "stages": [
        { "id": "atl.hook", "name": "Hooked throwing stick",
          "needs": [
            { "t": "Knowledge", "text": "light throwing spears", "refs": ["spear.light"] },
            { "t": "Material", "text": "hardwood" },
            { "t": "Pressure", "text": "wary prey that bolts early" },
            { "t": "Person", "text": "skilled hunter" }
          ],
          "does": "Kills at range; more band strength." },
        { "id": "atl.dart", "name": "Fletched darts",
          "needs": [
            { "t": "Knowledge", "text": "hooked throwing stick plus any thread for binding", "refs": ["atl.hook", "cord.ply"] },
            { "t": "Material", "text": "feathers" }
          ],
          "does": "Accurate darts. The idea of fletching carries over to arrows." }
      ]
    },
    {
      "id": "grind", "name": "Grinding stones", "col": 1, "kind": "Technology",
      "sum": "Turning hard seeds and nuts into food. The heavier stages need a band that stays put.",
      "stages": [
        { "id": "grind.pound", "name": "Pounding",
          "needs": [
            { "t": "Knowledge", "text": "flakes, foraging", "refs": ["knap.flake", "forage.rounds"] },
            { "t": "Material", "text": "a hammerstone plus nuts or seeds" },
            { "t": "Pressure", "text": "plenty of starchy food that's hard to eat whole" }
          ],
          "does": "Nuts and seeds become food.",
          "accident": "Nuts cracked on the same rock for weeks leave a smooth hollow." },
        { "id": "grind.mortar", "name": "Mortar and pestle",
          "needs": [
            { "t": "Knowledge", "text": "pounding", "refs": ["grind.pound"] },
            { "t": "Material", "text": "a hollowed stone or log" },
            { "t": "Way of life", "text": "returning to the same place", "refs": ["camp.return"] }
          ],
          "does": "Faster, finer meal." },
        { "id": "grind.slab", "name": "Grinding slab",
          "needs": [
            { "t": "Knowledge", "text": "mortar and pestle", "refs": ["grind.mortar"] },
            { "t": "Material", "text": "a big flat stone (too heavy to carry) and wild grain" },
            { "t": "Way of life", "text": "long stays", "refs": ["camp.long"] }
          ],
          "does": "Flour. Wild grain becomes worth the effort." }
      ]
    },
    {
      "id": "dog", "name": "Dog companions", "col": 1, "kind": "Domestication",
      "sum": "Wolves become dogs over generations, but only if the band is strong enough that wolves lurk instead of attack.",
      "stages": [
        { "id": "dog.lurk", "name": "Wolves at the edge of camp",
          "needs": [
            { "t": "Material", "text": "a wolf pack in range" },
            { "t": "Pressure", "text": "meat scraps left at camp", "refs": ["spear.wood"] },
            { "t": "Deterrence", "text": "band strength high enough that wolves stay back: armed adults, fire", "refs": ["fire.make"] }
          ],
          "does": "Not a discovery, a situation. Wolves scavenge and their howls warn of other predators." },
        { "id": "dog.pup", "name": "A pup raised in camp",
          "needs": [
            { "t": "Situation", "text": "wolves at the edge of camp", "refs": ["dog.lurk"] },
            { "t": "Culture", "text": "no taboo against wolves" },
            { "t": "Person", "text": "calm, interested in animals" }
          ],
          "does": "One tame wolf. Its pups are tamer.",
          "accident": "An orphaned pup is found after its mother is killed. The main way in." },
        { "id": "dog.camp", "name": "Camp dogs",
          "needs": [
            { "t": "Knowledge", "text": "pups raised in camp", "refs": ["dog.pup"] },
            { "t": "Time", "text": "several generations of the tamest pups kept" }
          ],
          "does": "Guarding (more band strength), cleaning scraps, warmth." },
        { "id": "dog.hunt", "name": "Hunting dogs",
          "needs": [
            { "t": "Knowledge", "text": "camp dogs", "refs": ["dog.camp"] },
            { "t": "Person", "text": "skilled hunter who works with them" }
          ],
          "does": "Tracking and cornering prey. Hunts succeed far more often." }
      ]
    },
    {
      "id": "burial", "name": "Burial & rites", "col": 1, "kind": "Belief", "belief": true,
      "sum": "The first culture tile. Ties people to a place and creates the ritual specialist.",
      "stages": [
        { "id": "burial.cover", "name": "Covering the dead",
          "needs": [
            { "t": "Event", "text": "the death of someone loved or respected" },
            { "t": "Person", "text": "grieving deeply" }
          ],
          "does": "Graves become places that matter." },
        { "id": "burial.goods", "name": "Grave goods",
          "needs": [
            { "t": "Knowledge", "text": "covering the dead", "refs": ["burial.cover"] },
            { "t": "Belief", "text": "the dead go on somewhere, or are linked to the sky one" }
          ],
          "does": "Objects take on meaning beyond use." },
        { "id": "burial.rites", "name": "Ancestor rites",
          "needs": [
            { "t": "Knowledge", "text": "grave goods and shared stories", "refs": ["burial.goods", "lang.story"] },
            { "t": "Person", "text": "interested in spirits" }
          ],
          "does": "A ritual specialist emerges. Strong attachment to place." }
      ]
    },
    {
      "id": "ochre", "name": "Ochre & art", "col": 2, "kind": "Belief", "belief": true,
      "sum": "Art as belief made visible. Cave walls come from the Synty Alpine caves.",
      "stages": [
        { "id": "ochre.body", "name": "Body paint",
          "needs": [
            { "t": "Material", "text": "ochre" },
            { "t": "Pressure", "text": "a ritual, a status, or a need to mark who 'we' are" },
            { "t": "Person", "text": "interested in spirits, sky or people" }
          ],
          "does": "Group identity; ritual looks the part.",
          "accident": "Someone notices the red stain ochre leaves on their hands." },
        { "id": "ochre.hand", "name": "Handprints and marks",
          "needs": [
            { "t": "Knowledge", "text": "body paint", "refs": ["ochre.body"] },
            { "t": "Material", "text": "a cave or sheltered rock wall" }
          ],
          "does": "Places get claimed and remembered." },
        { "id": "ochre.paint", "name": "Cave paintings",
          "needs": [
            { "t": "Knowledge", "text": "handprints, and stories worth showing", "refs": ["ochre.hand", "lang.story"] },
            { "t": "Person", "text": "interested in spirits or animals, skilled hands" }
          ],
          "does": "Beliefs become very stable. Hunting magic beliefs form." },
        { "id": "ochre.figure", "name": "Carved and fired figures",
          "needs": [
            { "t": "Knowledge", "text": "cave paintings or grave goods", "refs": ["ochre.paint", "burial.goods"], "any": true },
            { "t": "Material", "text": "soft stone, bone or ivory; or clay that has been fired", "refs": ["pot.fired"] }
          ],
          "does": "Portable sacred objects. The fired-clay version is real: figurines came 10,000 years before pots." }
      ]
    },
    {
      "id": "bask", "name": "Basketry", "col": 2, "kind": "Technology",
      "sum": "Carrying and holding more than hands can.",
      "stages": [
        { "id": "bask.bundle", "name": "Bundled reed carriers",
          "needs": [
            { "t": "Material", "text": "reeds, grass or willow" },
            { "t": "Pressure", "text": "gathering more than hands can carry" }
          ],
          "does": "Bigger foraging hauls." },
        { "id": "bask.woven", "name": "Woven baskets",
          "needs": [
            { "t": "Knowledge", "text": "bundled carriers plus plant twine", "refs": ["bask.bundle", "cord.twine"] },
            { "t": "Person", "text": "patient, interested in plants" }
          ],
          "does": "Durable carriers; fish traps become possible." },
        { "id": "bask.tight", "name": "Tight baskets that hold seed",
          "needs": [
            { "t": "Knowledge", "text": "woven baskets", "refs": ["bask.woven"] },
            { "t": "Pressure", "text": "small seeds worth collecting" }
          ],
          "does": "Seed harvests and basket stores." },
        { "id": "bask.sealed", "name": "Pitch-sealed baskets",
          "needs": [
            { "t": "Knowledge", "text": "tight baskets and a hearth", "refs": ["bask.tight", "fire.hearth"] },
            { "t": "Material", "text": "tree resin" }
          ],
          "does": "Carry water; boil food with hot stones." }
      ]
    },
    {
      "id": "hide", "name": "Hide & sewing", "col": 2, "kind": "Technology",
      "sum": "From wrapped skins to fitted clothes. Fitted clothing opens colder ground.",
      "stages": [
        { "id": "hide.wrap", "name": "Wrapped hides",
          "needs": [
            { "t": "Material", "text": "hides from hunting", "refs": ["spear.wood"] },
            { "t": "Pressure", "text": "a cold season" }
          ],
          "does": "Basic warmth." },
        { "id": "hide.scrape", "name": "Scraped and dried hides",
          "needs": [
            { "t": "Knowledge", "text": "wrapped hides and scrapers", "refs": ["hide.wrap", "knap.flake"] },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Hides last; covers for shelters." },
        { "id": "hide.awl", "name": "Stitched with an awl",
          "needs": [
            { "t": "Knowledge", "text": "scraped hides plus any thread", "refs": ["hide.scrape", "cord.sinew"] },
            { "t": "Material", "text": "bone for awls" }
          ],
          "does": "Bags, simple garments, joined shelter covers." },
        { "id": "hide.tent", "name": "Hide tents",
          "needs": [
            { "t": "Knowledge", "text": "stitched hides and cord", "refs": ["hide.awl", "cord.ply"] },
            { "t": "Material", "text": "long poles" }
          ],
          "does": "Real shelter; long stays get easier." },
        { "id": "hide.needle", "name": "Fitted clothing",
          "needs": [
            { "t": "Knowledge", "text": "awl stitching and long blades", "refs": ["hide.awl", "knap.blade"] },
            { "t": "Material", "text": "bone for eyed needles" },
            { "t": "Pressure", "text": "severe cold" },
            { "t": "Person", "text": "dexterous" }
          ],
          "does": "Big cold tolerance. Harsh lands become livable." }
      ]
    },
    {
      "id": "fish", "name": "Fishing", "col": 2, "kind": "Technology",
      "sum": "Turning a river into a reliable larder. Two or more methods make it dependable enough to settle on.",
      "stages": [
        { "id": "fish.spear", "name": "Spearing and hand catching",
          "needs": [
            { "t": "Knowledge", "text": "spear", "refs": ["spear.wood"] },
            { "t": "Material", "text": "a river or lake with fish" },
            { "t": "Pressure", "text": "food short, water close" },
            { "t": "Person", "text": "interested in water" }
          ],
          "does": "Some fish, unreliably.",
          "accident": "Fish trapped in a shrinking pool are caught by hand." },
        { "id": "fish.weir", "name": "Stake weirs",
          "needs": [
            { "t": "Knowledge", "text": "spearing fish", "refs": ["fish.spear"] },
            { "t": "Material", "text": "stakes and a seasonal fish run" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Big catches during runs." },
        { "id": "fish.trap", "name": "Basket traps",
          "needs": [ { "t": "Knowledge", "text": "woven baskets and spearing fish", "refs": ["bask.woven", "fish.spear"] } ],
          "does": "Steady catch with little work." },
        { "id": "fish.line", "name": "Hook and line",
          "needs": [
            { "t": "Knowledge", "text": "any thread plus long blades", "refs": ["cord.ply", "knap.blade"] },
            { "t": "Material", "text": "bone for hooks" }
          ],
          "does": "Fishing deep water." },
        { "id": "fish.net", "name": "Nets",
          "needs": [ { "t": "Knowledge", "text": "knotted nets", "refs": ["cord.net"] } ],
          "does": "The biggest, most reliable catches." }
      ]
    },
    {
      "id": "bow", "name": "Bow & arrow", "col": 3, "kind": "Technology",
      "sum": "Killing at range without being seen.",
      "stages": [
        { "id": "bow.simple", "name": "Simple bow",
          "needs": [
            { "t": "Material", "text": "springy wood (yew, ash) or bamboo" },
            { "t": "Knowledge", "text": "two-ply string for the bowstring", "refs": ["cord.ply"] },
            { "t": "Knowledge", "text": "spear-thrower, or long practice throwing", "refs": ["atl.hook"] },
            { "t": "Pressure", "text": "fast prey, or conflict with neighbors" },
            { "t": "Person", "text": "skilled hunter or woodworker, curious" }
          ],
          "does": "Range and stealth; more band strength.",
          "accident": "A bent sapling tied for a snare whips a stick across camp." },
        { "id": "bow.fletch", "name": "Fletched arrows",
          "needs": [
            { "t": "Knowledge", "text": "simple bow (fletched darts help a lot)", "refs": ["bow.simple"] },
            { "t": "Material", "text": "feathers" }
          ],
          "does": "Accuracy." },
        { "id": "bow.stone", "name": "Stone-tipped arrows",
          "needs": [ { "t": "Knowledge", "text": "simple bow and hafted points", "refs": ["bow.simple", "knap.haft"] } ],
          "does": "Lethal against big game." },
        { "id": "bow.backed", "name": "Sinew-backed bow", "variant": "needs both cordage routes",
          "needs": [ { "t": "Knowledge", "text": "simple bow, sinew thread and plant twine", "refs": ["bow.simple", "cord.sinew", "cord.twine"] } ],
          "does": "Much stronger bows." }
      ]
    },
    {
      "id": "store", "name": "Storage", "col": 3, "kind": "Technology",
      "sum": "Changes how a band thinks about the future. Things worth guarding appear.",
      "stages": [
        { "id": "store.cache", "name": "Caches under stones",
          "needs": [
            { "t": "Pressure", "text": "seasonal glut followed by scarcity" },
            { "t": "Person", "text": "cautious planner" }
          ],
          "does": "A small buffer against hunger.",
          "accident": "Food hidden from wolves is found intact weeks later." },
        { "id": "store.pit", "name": "Lined pits",
          "needs": [
            { "t": "Knowledge", "text": "caches, plus food that keeps", "refs": ["store.cache", "dry.keep"] },
            { "t": "Material", "text": "dry, diggable ground" },
            { "t": "Way of life", "text": "returning to the same place", "refs": ["camp.return"] }
          ],
          "does": "Winter stores." },
        { "id": "store.basket", "name": "Basket stores",
          "needs": [ { "t": "Knowledge", "text": "caches and tight baskets", "refs": ["store.cache", "bask.tight"] } ],
          "does": "Seed and nut stores." },
        { "id": "store.raised", "name": "Raised caches",
          "needs": [
            { "t": "Knowledge", "text": "pits or basket stores, plus rope", "refs": ["store.pit", "store.basket", "cord.rope"] },
            { "t": "Pressure", "text": "animals raiding stores" }
          ],
          "does": "Stores safe from animals. Big enough to be worth stealing." }
      ]
    },
    {
      "id": "camp", "name": "Base camp", "col": 4, "kind": "Way of life", "belief": true,
      "sum": "Not a tool: a band choosing to mostly stay put. Unlocks heavy, fragile things, and new problems like disease.",
      "stages": [
        { "id": "camp.return", "name": "Seasonal return",
          "needs": [
            { "t": "Knowledge", "text": "seasonal rounds", "refs": ["forage.rounds"] },
            { "t": "Material", "text": "a place with dependable seasonal food" },
            { "t": "Culture", "text": "attachment to place; graves nearby help", "refs": ["burial.cover"] }
          ],
          "does": "The same camp every year; things can be left behind." },
        { "id": "camp.long", "name": "Long stays",
          "needs": [
            { "t": "Way of life", "text": "seasonal return", "refs": ["camp.return"] },
            { "t": "Knowledge", "text": "any storage", "refs": ["store.cache"] },
            { "t": "Food", "text": "one reliable local food: weirs, nuts, or wild grain", "refs": ["fish.weir", "forage.nuts", "grain.harvest"], "any": true },
            { "t": "Pressure", "text": "moving costs more than staying: many children or elders, heavy stores" }
          ],
          "does": "Most of the year in one place. Heavy tools make sense." },
        { "id": "camp.year", "name": "Year-round base",
          "needs": [
            { "t": "Way of life", "text": "long stays", "refs": ["camp.long"] },
            { "t": "Knowledge", "text": "pits or raised stores", "refs": ["store.pit", "store.raised"], "any": true },
            { "t": "Food", "text": "two reliable food sources" },
            { "t": "Shelter", "text": "hide tents or sturdier", "refs": ["hide.tent"] }
          ],
          "does": "Population grows; disease risk grows; the next milestone's villages start here." }
      ]
    },
    {
      "id": "pot", "name": "Pottery", "col": 5, "kind": "Technology",
      "sum": "The showcase of this milestone. Fired clay can happen early by accident, but pots need everything else to line up.",
      "stages": [
        { "id": "pot.fired", "name": "Fired clay",
          "needs": [
            { "t": "Material", "text": "clay" },
            { "t": "Knowledge", "text": "a built hearth", "refs": ["fire.hearth"] }
          ],
          "does": "The insight that fire hardens clay. Figurines possible.",
          "accident": "Clay pressed or dropped near a hearth comes out hard. The main way in." },
        { "id": "pot.pinch", "name": "Pinch pots",
          "needs": [
            { "t": "Knowledge", "text": "fired clay and high-heat fires", "refs": ["pot.fired", "fire.hot"] },
            { "t": "Way of life", "text": "long stays (pots are too heavy for nomads)", "refs": ["camp.long"] },
            { "t": "Pressure", "text": "a need to cook or hold liquids" },
            { "t": "Person", "text": "curious, interested in fire or stone" }
          ],
          "does": "Small vessels." },
        { "id": "pot.coil", "name": "Coiled pots",
          "needs": [
            { "t": "Knowledge", "text": "pinch pots", "refs": ["pot.pinch"] },
            { "t": "Person", "text": "patient, practiced potter" }
          ],
          "does": "Real cooking pots: stews and porridge (grain becomes much more useful); sealed storage." },
        { "id": "pot.pit", "name": "Pit firing",
          "needs": [ { "t": "Knowledge", "text": "coiled pots and high-heat fires", "refs": ["pot.coil", "fire.hot"] } ],
          "does": "Reliable, sturdy pots. Kilns are next milestone." }
      ]
    },
    {
      "id": "grain", "name": "Tending wild grain", "col": 5, "kind": "Technology",
      "sum": "The doorway to farming, which is the next milestone.",
      "stages": [
        { "id": "grain.harvest", "name": "Harvesting wild stands",
          "needs": [
            { "t": "Material", "text": "wild grasses with heavy seed" },
            { "t": "Knowledge", "text": "something to hold seed: tight baskets", "refs": ["bask.tight"] },
            { "t": "Pressure", "text": "food running short" }
          ],
          "does": "A seasonal grain haul." },
        { "id": "grain.clear", "name": "Clearing competitors",
          "needs": [
            { "t": "Knowledge", "text": "harvesting, plus seasonal return or burning the land", "refs": ["grain.harvest", "camp.return", "fire.land"] }
          ],
          "does": "Bigger wild stands near camp." },
        { "id": "grain.scatter", "name": "Scattering seed nearby",
          "needs": [
            { "t": "Knowledge", "text": "clearing competitors", "refs": ["grain.clear"] },
            { "t": "Way of life", "text": "long stays", "refs": ["camp.long"] }
          ],
          "does": "Grain grows where you want it.",
          "accident": "Seed spilled on the camp's rubbish heap sprouts the next spring." },
        { "id": "grain.select", "name": "Keeping the best seed",
          "needs": [
            { "t": "Knowledge", "text": "scattering seed and grinding slabs", "refs": ["grain.scatter", "grind.slab"] },
            { "t": "Knowledge", "text": "storage; tally marks for timing help", "refs": ["store.basket", "lang.count"] },
            { "t": "Person", "text": "patient, interested in plants" }
          ],
          "does": "Seeds get bigger each generation. Farming begins next milestone." }
      ]
    }
  ]
}

toolUseResult.content:
{
  "version": 1,
  "note": "Discovery web for milestone 1. Each tile is a family of stages; each stage has its own needs, effects, and optional accident situation. Refs point at stage ids (tile.stage). 'any': true means any one ref is enough.",
  "tiles": [
    {
      "id": "fire", "name": "Fire", "col": 0, "kind": "Known at start",
      "sum": "Modern humans arrive able to make and keep fire. Mastery grows from there.",
      "stages": [
        { "id": "fire.make", "name": "Making and keeping fire", "known": true,
          "does": "Warmth, light, cooking, keeps predators back." },
        { "id": "fire.hearth", "name": "Built hearths",
          "needs": [
            { "t": "Knowledge", "text": "making fire", "refs": ["fire.make"] },
            { "t": "Way of life", "text": "staying two weeks or more in one spot" },
            { "t": "Material", "text": "flat stones to ring the fire" }
          ],
          "does": "Steady cooking heat; a place people gather and talk." },
        { "id": "fire.hot", "name": "High-heat fires",
          "needs": [
            { "t": "Knowledge", "text": "built hearths", "refs": ["fire.hearth"] },
            { "t": "Material", "text": "dense hardwood or plenty of fuel" },
            { "t": "Pressure", "text": "a job that needs real heat: hardening wood, treating flint" },
            { "t": "Person", "text": "interested in fire, practiced at tending it" }
          ],
          "does": "Hot enough to fire clay and heat-treat flint.",
          "accident": "A hearth dug into a sheltered pit runs far hotter than usual." },
        { "id": "fire.land", "name": "Burning the land",
          "needs": [
            { "t": "Knowledge", "text": "making fire", "refs": ["fire.make"] },
            { "t": "Material", "text": "dry grassland" },
            { "t": "Pressure", "text": "grazing herds that come back for fresh shoots" },
            { "t": "Person", "text": "bold" }
          ],
          "does": "Burned clearings draw game and help wild grain grow.",
          "accident": "After a wildfire (natural, or your lightning), herds return to the green shoots." }
      ]
    },
    {
      "id": "knap", "name": "Knapping", "col": 0, "kind": "Known at start",
      "sum": "Shaping stone into edges. Skill level matters for everything downstream.",
      "stages": [
        { "id": "knap.flake", "name": "Flakes and scrapers", "known": true,
          "does": "Cutting, scraping hides, carving wood." },
        { "id": "knap.blade", "name": "Long blades", "known": true,
          "does": "Better knives; blanks for points and awls." },
        { "id": "knap.haft", "name": "Hafted points",
          "needs": [
            { "t": "Knowledge", "text": "long blades", "refs": ["knap.blade"] },
            { "t": "Binding", "text": "sinew thread, plant twine, or tree resin", "refs": ["cord.sinew", "cord.twine"], "any": true },
            { "t": "Person", "text": "skilled knapper" }
          ],
          "does": "Stone points fixed to shafts: spears, later arrows." },
        { "id": "knap.heat", "name": "Heat-treated flint",
          "needs": [
            { "t": "Knowledge", "text": "high-heat fires", "refs": ["fire.hot"] },
            { "t": "Material", "text": "flint" },
            { "t": "Person", "text": "curious knapper" }
          ],
          "does": "Flint flakes cleaner; finer, sharper points.",
          "accident": "Flint left in the hearth overnight flakes far better the next day." }
      ]
    },
    {
      "id": "spear", "name": "Spear", "col": 0, "kind": "Known at start",
      "sum": "Hunting and defense. Armed adults also keep wolves at a distance.",
      "stages": [
        { "id": "spear.wood", "name": "Fire-hardened wooden spear", "known": true,
          "does": "Thrusting and short throws; counts toward band strength." },
        { "id": "spear.stone", "name": "Stone-tipped spear",
          "needs": [ { "t": "Knowledge", "text": "hafted points", "refs": ["knap.haft"] } ],
          "does": "Bigger game; more band strength." },
        { "id": "spear.light", "name": "Light throwing spears",
          "needs": [
            { "t": "Knowledge", "text": "wooden spear", "refs": ["spear.wood"] },
            { "t": "Material", "text": "straight saplings" },
            { "t": "Pressure", "text": "fast prey that won't let hunters close" },
            { "t": "Person", "text": "skilled hunter" }
          ],
          "does": "Longer throws; the base for the spear-thrower." }
      ]
    },
    {
      "id": "forage", "name": "Foraging", "col": 0, "kind": "Known at start",
      "sum": "Knowing which plants feed you, where and when.",
      "stages": [
        { "id": "forage.rounds", "name": "Patches and seasonal rounds", "known": true,
          "does": "The band moves through the year to where food is." },
        { "id": "forage.lore", "name": "Plant lore",
          "needs": [
            { "t": "Knowledge", "text": "shared stories, so lore outlives one person", "refs": ["lang.story"] },
            { "t": "Person", "text": "interested in plants; elders still alive to teach" }
          ],
          "does": "Medicines (fewer deaths), poisons, knowing which plants make good fiber." },
        { "id": "forage.nuts", "name": "Leaching nuts and acorns",
          "needs": [
            { "t": "Knowledge", "text": "seasonal rounds", "refs": ["forage.rounds"] },
            { "t": "Material", "text": "oaks or nut trees, running water" },
            { "t": "Pressure", "text": "a hungry autumn" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Bitter nuts become a big, storable food.",
          "accident": "Acorns dropped in a stream lose their bitterness." }
      ]
    },
    {
      "id": "lang", "name": "Language", "col": 0, "kind": "Known at start",
      "sum": "Full spoken language from day one. Its stages decide how far and how faithfully knowledge and beliefs travel.",
      "stages": [
        { "id": "lang.speech", "name": "Everyday speech and teaching", "known": true,
          "does": "Skills taught by showing plus words; every discovery adds new words." },
        { "id": "lang.story", "name": "Shared stories",
          "needs": [
            { "t": "Event", "text": "a remembered event retold by several people: a great hunt, a disaster, an omen" },
            { "t": "Pressure", "text": "long evenings together, such as winters around the fire" },
            { "t": "Person", "text": "sociable storyteller or elder" }
          ],
          "does": "Beliefs and lessons outlive the people who lived them; less drift between generations. Myths about you start here." },
        { "id": "lang.ritual", "name": "Ritual speech and song",
          "needs": [
            { "t": "Knowledge", "text": "shared stories", "refs": ["lang.story"] },
            { "t": "Belief", "text": "rites for the dead, or a belief built on omens", "refs": ["burial.rites"] },
            { "t": "Person", "text": "interested in spirits" }
          ],
          "does": "Rituals hit harder; belief strength and group cohesion rise." },
        { "id": "lang.count", "name": "Counting and tally marks",
          "needs": [
            { "t": "Pressure", "text": "keeping track of stores or of moons until a season", "refs": ["store.pit", "store.basket"], "any": true },
            { "t": "Material", "text": "bone or wood to notch" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Tracking seasons and stores; helps grain timing; groundwork for trade later." }
      ]
    },
    {
      "id": "cord", "name": "Cordage", "col": 1, "kind": "Technology",
      "sum": "Two routes in. Sinew cultures sew and string bows; plant cultures fish, build and net. Both opens everything.",
      "stages": [
        { "id": "cord.sinew", "name": "Sinew thread", "variant": "hunter route",
          "needs": [
            { "t": "Material", "text": "sinew from butchered game", "refs": ["spear.wood"] },
            { "t": "Pressure", "text": "things that need binding: hafting, mending" },
            { "t": "Person", "text": "dexterous, interested in animals" }
          ],
          "does": "Sewing, strong bowstrings, tight lashings.",
          "accident": "Wet sinew wrapped around a cracked handle dries rock-hard." },
        { "id": "cord.twine", "name": "Plant twine", "variant": "gatherer route",
          "needs": [
            { "t": "Material", "text": "fibrous plants: nettle, reeds, bark" },
            { "t": "Pressure", "text": "big foraging hauls to carry and tie" },
            { "t": "Person", "text": "dexterous, interested in plants" }
          ],
          "does": "Basket lashing, fishing lines, long cords.",
          "accident": "Stems absently twisted during a rest hold together under pull." },
        { "id": "cord.ply", "name": "Two-ply string",
          "needs": [
            { "t": "Knowledge", "text": "either kind of thread", "refs": ["cord.sinew", "cord.twine"], "any": true },
            { "t": "Person", "text": "practiced cord-maker" }
          ],
          "does": "Stronger everything: bowstrings, hafting, lines." },
        { "id": "cord.rope", "name": "Rope",
          "needs": [
            { "t": "Knowledge", "text": "two-ply string made from plants (sinew is too short)", "refs": ["cord.ply", "cord.twine"] },
            { "t": "Pressure", "text": "hauling or building" }
          ],
          "does": "Lashing shelters, hauling, rafts later." },
        { "id": "cord.net", "name": "Knotted nets",
          "needs": [
            { "t": "Knowledge", "text": "rope", "refs": ["cord.rope"] },
            { "t": "Pressure", "text": "water to fish, or loads to carry" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Fishing nets and carrying nets." }
      ]
    },
    {
      "id": "dry", "name": "Drying & smoking", "col": 1, "kind": "Technology",
      "sum": "Making food last into the lean season. Usually starts by accident.",
      "stages": [
        { "id": "dry.keep", "name": "Food that keeps",
          "needs": [
            { "t": "Knowledge", "text": "fire", "refs": ["fire.make"] },
            { "t": "Material", "text": "more meat, fish or berries than can be eaten" }
          ],
          "does": "Food lasts days instead of hours.",
          "accident": "Meat left hanging in the smoke is still good a week later. The main way in." },
        { "id": "dry.rack", "name": "Drying racks",
          "needs": [
            { "t": "Knowledge", "text": "food that keeps, and a built hearth or steady sun", "refs": ["dry.keep", "fire.hearth"] },
            { "t": "Material", "text": "poles" },
            { "t": "Pressure", "text": "a hard winter after a good autumn" }
          ],
          "does": "Preserve a whole kill or harvest; real stores become possible." },
        { "id": "dry.smoke", "name": "Smoking",
          "needs": [
            { "t": "Knowledge", "text": "drying racks", "refs": ["dry.rack"] },
            { "t": "Material", "text": "a surplus of fish or meat" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Food lasts months. A fish run can now feed a winter." }
      ]
    },
    {
      "id": "atl", "name": "Spear-thrower", "col": 1, "kind": "Technology",
      "sum": "A hooked stick that throws a spear much farther. One road to the bow.",
      "stages": [
        { "id": "atl.hook", "name": "Hooked throwing stick",
          "needs": [
            { "t": "Knowledge", "text": "light throwing spears", "refs": ["spear.light"] },
            { "t": "Material", "text": "hardwood" },
            { "t": "Pressure", "text": "wary prey that bolts early" },
            { "t": "Person", "text": "skilled hunter" }
          ],
          "does": "Kills at range; more band strength." },
        { "id": "atl.dart", "name": "Fletched darts",
          "needs": [
            { "t": "Knowledge", "text": "hooked throwing stick plus any thread for binding", "refs": ["atl.hook", "cord.ply"] },
            { "t": "Material", "text": "feathers" }
          ],
          "does": "Accurate darts. The idea of fletching carries over to arrows." }
      ]
    },
    {
      "id": "grind", "name": "Grinding stones", "col": 1, "kind": "Technology",
      "sum": "Turning hard seeds and nuts into food. The heavier stages need a band that stays put.",
      "stages": [
        { "id": "grind.pound", "name": "Pounding",
          "needs": [
            { "t": "Knowledge", "text": "flakes, foraging", "refs": ["knap.flake", "forage.rounds"] },
            { "t": "Material", "text": "a hammerstone plus nuts or seeds" },
            { "t": "Pressure", "text": "plenty of starchy food that's hard to eat whole" }
          ],
          "does": "Nuts and seeds become food.",
          "accident": "Nuts cracked on the same rock for weeks leave a smooth hollow." },
        { "id": "grind.mortar", "name": "Mortar and pestle",
          "needs": [
            { "t": "Knowledge", "text": "pounding", "refs": ["grind.pound"] },
            { "t": "Material", "text": "a hollowed stone or log" },
            { "t": "Way of life", "text": "returning to the same place", "refs": ["camp.return"] }
          ],
          "does": "Faster, finer meal." },
        { "id": "grind.slab", "name": "Grinding slab",
          "needs": [
            { "t": "Knowledge", "text": "mortar and pestle", "refs": ["grind.mortar"] },
            { "t": "Material", "text": "a big flat stone (too heavy to carry) and wild grain" },
            { "t": "Way of life", "text": "long stays", "refs": ["camp.long"] }
          ],
          "does": "Flour. Wild grain becomes worth the effort." }
      ]
    },
    {
      "id": "dog", "name": "Dog companions", "col": 1, "kind": "Domestication",
      "sum": "Wolves become dogs over generations, but only if the band is strong enough that wolves lurk instead of attack.",
      "stages": [
        { "id": "dog.lurk", "name": "Wolves at the edge of camp",
          "needs": [
            { "t": "Material", "text": "a wolf pack in range" },
            { "t": "Pressure", "text": "meat scraps left at camp", "refs": ["spear.wood"] },
            { "t": "Deterrence", "text": "band strength high enough that wolves stay back: armed adults, fire", "refs": ["fire.make"] }
          ],
          "does": "Not a discovery, a situation. Wolves scavenge and their howls warn of other predators." },
        { "id": "dog.pup", "name": "A pup raised in camp",
          "needs": [
            { "t": "Situation", "text": "wolves at the edge of camp", "refs": ["dog.lurk"] },
            { "t": "Culture", "text": "no taboo against wolves" },
            { "t": "Person", "text": "calm, interested in animals" }
          ],
          "does": "One tame wolf. Its pups are tamer.",
          "accident": "An orphaned pup is found after its mother is killed. The main way in." },
        { "id": "dog.camp", "name": "Camp dogs",
          "needs": [
            { "t": "Knowledge", "text": "pups raised in camp", "refs": ["dog.pup"] },
            { "t": "Time", "text": "several generations of the tamest pups kept" }
          ],
          "does": "Guarding (more band strength), cleaning scraps, warmth." },
        { "id": "dog.hunt", "name": "Hunting dogs",
          "needs": [
            { "t": "Knowledge", "text": "camp dogs", "refs": ["dog.camp"] },
            { "t": "Person", "text": "skilled hunter who works with them" }
          ],
          "does": "Tracking and cornering prey. Hunts succeed far more often." }
      ]
    },
    {
      "id": "burial", "name": "Burial & rites", "col": 1, "kind": "Belief", "belief": true,
      "sum": "The first culture tile. Ties people to a place and creates the ritual specialist.",
      "stages": [
        { "id": "burial.cover", "name": "Covering the dead",
          "needs": [
            { "t": "Event", "text": "the death of someone loved or respected" },
            { "t": "Person", "text": "grieving deeply" }
          ],
          "does": "Graves become places that matter." },
        { "id": "burial.goods", "name": "Grave goods",
          "needs": [
            { "t": "Knowledge", "text": "covering the dead", "refs": ["burial.cover"] },
            { "t": "Belief", "text": "the dead go on somewhere, or are linked to the sky one" }
          ],
          "does": "Objects take on meaning beyond use." },
        { "id": "burial.rites", "name": "Ancestor rites",
          "needs": [
            { "t": "Knowledge", "text": "grave goods and shared stories", "refs": ["burial.goods", "lang.story"] },
            { "t": "Person", "text": "interested in spirits" }
          ],
          "does": "A ritual specialist emerges. Strong attachment to place." }
      ]
    },
    {
      "id": "ochre", "name": "Ochre & art", "col": 2, "kind": "Belief", "belief": true,
      "sum": "Art as belief made visible. Cave walls come from the Synty Alpine caves.",
      "stages": [
        { "id": "ochre.body", "name": "Body paint",
          "needs": [
            { "t": "Material", "text": "ochre" },
            { "t": "Pressure", "text": "a ritual, a status, or a need to mark who 'we' are" },
            { "t": "Person", "text": "interested in spirits, sky or people" }
          ],
          "does": "Group identity; ritual looks the part.",
          "accident": "Someone notices the red stain ochre leaves on their hands." },
        { "id": "ochre.hand", "name": "Handprints and marks",
          "needs": [
            { "t": "Knowledge", "text": "body paint", "refs": ["ochre.body"] },
            { "t": "Material", "text": "a cave or sheltered rock wall" }
          ],
          "does": "Places get claimed and remembered." },
        { "id": "ochre.paint", "name": "Cave paintings",
          "needs": [
            { "t": "Knowledge", "text": "handprints, and stories worth showing", "refs": ["ochre.hand", "lang.story"] },
            { "t": "Person", "text": "interested in spirits or animals, skilled hands" }
          ],
          "does": "Beliefs become very stable. Hunting magic beliefs form." },
        { "id": "ochre.figure", "name": "Carved and fired figures",
          "needs": [
            { "t": "Knowledge", "text": "cave paintings or grave goods", "refs": ["ochre.paint", "burial.goods"], "any": true },
            { "t": "Material", "text": "soft stone, bone or ivory; or clay that has been fired", "refs": ["pot.fired"] }
          ],
          "does": "Portable sacred objects. The fired-clay version is real: figurines came 10,000 years before pots." }
      ]
    },
    {
      "id": "bask", "name": "Basketry", "col": 2, "kind": "Technology",
      "sum": "Carrying and holding more than hands can.",
      "stages": [
        { "id": "bask.bundle", "name": "Bundled reed carriers",
          "needs": [
            { "t": "Material", "text": "reeds, grass or willow" },
            { "t": "Pressure", "text": "gathering more than hands can carry" }
          ],
          "does": "Bigger foraging hauls." },
        { "id": "bask.woven", "name": "Woven baskets",
          "needs": [
            { "t": "Knowledge", "text": "bundled carriers plus plant twine", "refs": ["bask.bundle", "cord.twine"] },
            { "t": "Person", "text": "patient, interested in plants" }
          ],
          "does": "Durable carriers; fish traps become possible." },
        { "id": "bask.tight", "name": "Tight baskets that hold seed",
          "needs": [
            { "t": "Knowledge", "text": "woven baskets", "refs": ["bask.woven"] },
            { "t": "Pressure", "text": "small seeds worth collecting" }
          ],
          "does": "Seed harvests and basket stores." },
        { "id": "bask.sealed", "name": "Pitch-sealed baskets",
          "needs": [
            { "t": "Knowledge", "text": "tight baskets and a hearth", "refs": ["bask.tight", "fire.hearth"] },
            { "t": "Material", "text": "tree resin" }
          ],
          "does": "Carry water; boil food with hot stones." }
      ]
    },
    {
      "id": "hide", "name": "Hide & sewing", "col": 2, "kind": "Technology",
      "sum": "From wrapped skins to fitted clothes. Fitted clothing opens colder ground.",
      "stages": [
        { "id": "hide.wrap", "name": "Wrapped hides",
          "needs": [
            { "t": "Material", "text": "hides from hunting", "refs": ["spear.wood"] },
            { "t": "Pressure", "text": "a cold season" }
          ],
          "does": "Basic warmth." },
        { "id": "hide.scrape", "name": "Scraped and dried hides",
          "needs": [
            { "t": "Knowledge", "text": "wrapped hides and scrapers", "refs": ["hide.wrap", "knap.flake"] },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Hides last; covers for shelters." },
        { "id": "hide.awl", "name": "Stitched with an awl",
          "needs": [
            { "t": "Knowledge", "text": "scraped hides plus any thread", "refs": ["hide.scrape", "cord.sinew"] },
            { "t": "Material", "text": "bone for awls" }
          ],
          "does": "Bags, simple garments, joined shelter covers." },
        { "id": "hide.tent", "name": "Hide tents",
          "needs": [
            { "t": "Knowledge", "text": "stitched hides and cord", "refs": ["hide.awl", "cord.ply"] },
            { "t": "Material", "text": "long poles" }
          ],
          "does": "Real shelter; long stays get easier." },
        { "id": "hide.needle", "name": "Fitted clothing",
          "needs": [
            { "t": "Knowledge", "text": "awl stitching and long blades", "refs": ["hide.awl", "knap.blade"] },
            { "t": "Material", "text": "bone for eyed needles" },
            { "t": "Pressure", "text": "severe cold" },
            { "t": "Person", "text": "dexterous" }
          ],
          "does": "Big cold tolerance. Harsh lands become livable." }
      ]
    },
    {
      "id": "fish", "name": "Fishing", "col": 2, "kind": "Technology",
      "sum": "Turning a river into a reliable larder. Two or more methods make it dependable enough to settle on.",
      "stages": [
        { "id": "fish.spear", "name": "Spearing and hand catching",
          "needs": [
            { "t": "Knowledge", "text": "spear", "refs": ["spear.wood"] },
            { "t": "Material", "text": "a river or lake with fish" },
            { "t": "Pressure", "text": "food short, water close" },
            { "t": "Person", "text": "interested in water" }
          ],
          "does": "Some fish, unreliably.",
          "accident": "Fish trapped in a shrinking pool are caught by hand." },
        { "id": "fish.weir", "name": "Stake weirs",
          "needs": [
            { "t": "Knowledge", "text": "spearing fish", "refs": ["fish.spear"] },
            { "t": "Material", "text": "stakes and a seasonal fish run" },
            { "t": "Person", "text": "patient" }
          ],
          "does": "Big catches during runs." },
        { "id": "fish.trap", "name": "Basket traps",
          "needs": [ { "t": "Knowledge", "text": "woven baskets and spearing fish", "refs": ["bask.woven", "fish.spear"] } ],
          "does": "Steady catch with little work." },
        { "id": "fish.line", "name": "Hook and line",
          "needs": [
            { "t": "Knowledge", "text": "any thread plus long blades", "refs": ["cord.ply", "knap.blade"] },
            { "t": "Material", "text": "bone for hooks" }
          ],
          "does": "Fishing deep water." },
        { "id": "fish.net", "name": "Nets",
          "needs": [ { "t": "Knowledge", "text": "knotted nets", "refs": ["cord.net"] } ],
          "does": "The biggest, most reliable catches." }
      ]
    },
    {
      "id": "bow", "name": "Bow & arrow", "col": 3, "kind": "Technology",
      "sum": "Killing at range without being seen.",
      "stages": [
        { "id": "bow.simple", "name": "Simple bow",
          "needs": [
            { "t": "Material", "text": "springy wood (yew, ash) or bamboo" },
            { "t": "Knowledge", "text": "two-ply string for the bowstring", "refs": ["cord.ply"] },
            { "t": "Knowledge", "text": "spear-thrower, or long practice throwing", "refs": ["atl.hook"] },
            { "t": "Pressure", "text": "fast prey, or conflict with neighbors" },
            { "t": "Person", "text": "skilled hunter or woodworker, curious" }
          ],
          "does": "Range and stealth; more band strength.",
          "accident": "A bent sapling tied for a snare whips a stick across camp." },
        { "id": "bow.fletch", "name": "Fletched arrows",
          "needs": [
            { "t": "Knowledge", "text": "simple bow (fletched darts help a lot)", "refs": ["bow.simple"] },
            { "t": "Material", "text": "feathers" }
          ],
          "does": "Accuracy." },
        { "id": "bow.stone", "name": "Stone-tipped arrows",
          "needs": [ { "t": "Knowledge", "text": "simple bow and hafted points", "refs": ["bow.simple", "knap.haft"] } ],
          "does": "Lethal against big game." },
        { "id": "bow.backed", "name": "Sinew-backed bow", "variant": "needs both cordage routes",
          "needs": [ { "t": "Knowledge", "text": "simple bow, sinew thread and plant twine", "refs": ["bow.simple", "cord.sinew", "cord.twine"] } ],
          "does": "Much stronger bows." }
      ]
    },
    {
      "id": "store", "name": "Storage", "col": 3, "kind": "Technology",
      "sum": "Changes how a band thinks about the future. Things worth guarding appear.",
      "stages": [
        { "id": "store.cache", "name": "Caches under stones",
          "needs": [
            { "t": "Pressure", "text": "seasonal glut followed by scarcity" },
            { "t": "Person", "text": "cautious planner" }
          ],
          "does": "A small buffer against hunger.",
          "accident": "Food hidden from wolves is found intact weeks later." },
        { "id": "store.pit", "name": "Lined pits",
          "needs": [
            { "t": "Knowledge", "text": "caches, plus food that keeps", "refs": ["store.cache", "dry.keep"] },
            { "t": "Material", "text": "dry, diggable ground" },
            { "t": "Way of life", "text": "returning to the same place", "refs": ["camp.return"] }
          ],
          "does": "Winter stores." },
        { "id": "store.basket", "name": "Basket stores",
          "needs": [ { "t": "Knowledge", "text": "caches and tight baskets", "refs": ["store.cache", "bask.tight"] } ],
          "does": "Seed and nut stores." },
        { "id": "store.raised", "name": "Raised caches",
          "needs": [
            { "t": "Knowledge", "text": "pits or basket stores, plus rope", "refs": ["store.pit", "store.basket", "cord.rope"] },
            { "t": "Pressure", "text": "animals raiding stores" }
          ],
          "does": "Stores safe from animals. Big enough to be worth stealing." }
      ]
    },
    {
      "id": "camp", "name": "Base camp", "col": 4, "kind": "Way of life", "belief": true,
      "sum": "Not a tool: a band choosing to mostly stay put. Unlocks heavy, fragile things, and new problems like disease.",
      "stages": [
        { "id": "camp.return", "name": "Seasonal return",
          "needs": [
            { "t": "Knowledge", "text": "seasonal rounds", "refs": ["forage.rounds"] },
            { "t": "Material", "text": "a place with dependable seasonal food" },
            { "t": "Culture", "text": "attachment to place; graves nearby help", "refs": ["burial.cover"] }
          ],
          "does": "The same camp every year; things can be left behind." },
        { "id": "camp.long", "name": "Long stays",
          "needs": [
            { "t": "Way of life", "text": "seasonal return", "refs": ["camp.return"] },
            { "t": "Knowledge", "text": "any storage", "refs": ["store.cache"] },
            { "t": "Food", "text": "one reliable local food: weirs, nuts, or wild grain", "refs": ["fish.weir", "forage.nuts", "grain.harvest"], "any": true },
            { "t": "Pressure", "text": "moving costs more than staying: many children or elders, heavy stores" }
          ],
          "does": "Most of the year in one place. Heavy tools make sense." },
        { "id": "camp.year", "name": "Year-round base",
          "needs": [
            { "t": "Way of life", "text": "long stays", "refs": ["camp.long"] },
            { "t": "Knowledge", "text": "pits or raised stores", "refs": ["store.pit", "store.raised"], "any": true },
            { "t": "Food", "text": "two reliable food sources" },
            { "t": "Shelter", "text": "hide tents or sturdier", "refs": ["hide.tent"] }
          ],
          "does": "Population grows; disease risk grows; the next milestone's villages start here." }
      ]
    },
    {
      "id": "pot", "name": "Pottery", "col": 5, "kind": "Technology",
      "sum": "The showcase of this milestone. Fired clay can happen early by accident, but pots need everything else to line up.",
      "stages": [
        { "id": "pot.fired", "name": "Fired clay",
          "needs": [
            { "t": "Material", "text": "clay" },
            { "t": "Knowledge", "text": "a built hearth", "refs": ["fire.hearth"] }
          ],
          "does": "The insight that fire hardens clay. Figurines possible.",
          "accident": "Clay pressed or dropped near a hearth comes out hard. The main way in." },
        { "id": "pot.pinch", "name": "Pinch pots",
          "needs": [
            { "t": "Knowledge", "text": "fired clay and high-heat fires", "refs": ["pot.fired", "fire.hot"] },
            { "t": "Way of life", "text": "long stays (pots are too heavy for nomads)", "refs": ["camp.long"] },
            { "t": "Pressure", "text": "a need to cook or hold liquids" },
            { "t": "Person", "text": "curious, interested in fire or stone" }
          ],
          "does": "Small vessels." },
        { "id": "pot.coil", "name": "Coiled pots",
          "needs": [
            { "t": "Knowledge", "text": "pinch pots", "refs": ["pot.pinch"] },
            { "t": "Person", "text": "patient, practiced potter" }
          ],
          "does": "Real cooking pots: stews and porridge (grain becomes much more useful); sealed storage." },
        { "id": "pot.pit", "name": "Pit firing",
          "needs": [ { "t": "Knowledge", "text": "coiled pots and high-heat fires", "refs": ["pot.coil", "fire.hot"] } ],
          "does": "Reliable, sturdy pots. Kilns are next milestone." }
      ]
    },
    {
      "id": "grain", "name": "Tending wild grain", "col": 5, "kind": "Technology",
      "sum": "The doorway to farming, which is the next milestone.",
      "stages": [
        { "id": "grain.harvest", "name": "Harvesting wild stands",
          "needs": [
            { "t": "Material", "text": "wild grasses with heavy seed" },
            { "t": "Knowledge", "text": "something to hold seed: tight baskets", "refs": ["bask.tight"] },
            { "t": "Pressure", "text": "food running short" }
          ],
          "does": "A seasonal grain haul." },
        { "id": "grain.clear", "name": "Clearing competitors",
          "needs": [
            { "t": "Knowledge", "text": "harvesting, plus seasonal return or burning the land", "refs": ["grain.harvest", "camp.return", "fire.land"] }
          ],
          "does": "Bigger wild stands near camp." },
        { "id": "grain.scatter", "name": "Scattering seed nearby",
          "needs": [
            { "t": "Knowledge", "text": "clearing competitors", "refs": ["grain.clear"] },
            { "t": "Way of life", "text": "long stays", "refs": ["camp.long"] }
          ],
          "does": "Grain grows where you want it.",
          "accident": "Seed spilled on the camp's rubbish heap sprouts the next spring." },
        { "id": "grain.select", "name": "Keeping the best seed",
          "needs": [
            { "t": "Knowledge", "text": "scattering seed and grinding slabs", "refs": ["grain.scatter", "grind.slab"] },
            { "t": "Knowledge", "text": "storage; tally marks for timing help", "refs": ["store.basket", "lang.count"] },
            { "t": "Person", "text": "patient, interested in plants" }
          ],
          "does": "Seeds get bigger each generation. Farming begins next milestone." }
      ]
    }
  ]
}

