                var c = rng.Pick(bank);
                c.Features |= Feature.Clay;
                bank.Remove(c);
            }
        }

        static bool NextToRiver(WorldMap map, Cell c)
        {
            for (int dx = -1; dx <= 1; dx++)
                for (int dy = -1; dy <= 1; dy++)
