            return false;
        }

        // Value noise: smooth, seeded, no dependencies.
        static double Fractal(int seed, double x, double y)
        {
            double sum = 0, amp = 1, norm = 0;
            for (int o = 0; o < 4; o++)
            {
                sum += Value(seed + o * 101, x, y) * amp;
                norm += amp;
                amp *= 0.5; x *= 2; y *= 2;
            }
            return sum / norm;
        }

        static double Value(int seed, double x, double y)
