using System;
using System.Collections.Generic;
using System.Linq;
using Anthro.Sim.Core;
using Anthro.Sim.World;

namespace Anthro.Sim.Ecology
{
    /// <summary>
    /// Animal populations: seasonal movement, spring births toward a carrying capacity,
    /// and wolves hunting deer. Overhunt a species and it stays gone.
    /// </summary>
    public sealed class EcologySystem
    {
        readonly List<AnimalGroup> _groups = new List<AnimalGroup>();
        readonly HashSet<Species> _extinct = new HashSet<Species>();
        int _nextId;

        public IReadOnlyList<AnimalGroup> Groups => _groups;

        public void Populate(WorldMap map, Rng rng)
        {
            foreach (var sp in Species.All)
                for (int i = 0; i < sp.StartGroups; i++)
                {
                    var spot = RandomCell(map, rng, sp.SummerTerrain);
                    _groups.Add(new AnimalGroup(_nextId++, sp, rng.Range(sp.GroupMin, sp.GroupMax + 1), spot.X, spot.Y));
                }
        }

        public int Total(Species sp) => _groups.Where(g => g.Species == sp).Sum(g => g.Count);

        public IEnumerable<AnimalGroup> Living(Species sp) => _groups.Where(g => g.Species == sp && !g.Gone);

        public void DailyUpdate(Simulation sim)
        {
            var map = sim.World;
            var rng = sim.Rng;
            var season = sim.Clock.Season;

            foreach (var g in _groups)
            {
                if (g.Gone) continue;
                if (g.Species.Predator) FollowPrey(g);
                else if (WorldMap.Distance(g.X, g.Y, g.TargetX, g.TargetY) < 1.5 || rng.Chance(0.05))
                {
                    var terrain = season == Season.Winter ? g.Species.WinterTerrain : g.Species.SummerTerrain;
                    var spot = NearbyCell(map, rng, g.X, g.Y, 14, terrain);
                    g.TargetX = spot.X; g.TargetY = spot.Y;
                }
                Step(g, 3);
            }

            foreach (var pack in _groups.Where(g => g.Species.Predator && !g.Gone).ToList())
                PackHunts(sim, pack);

            if (sim.Clock.DayOfYear == 0) SpringBirths(sim);
        }

        void FollowPrey(AnimalGroup pack)
        {
            var prey = _groups.Where(g => g.Species == Species.Deer && !g.Gone)
                .OrderBy(g => WorldMap.Distance(g.X, g.Y, pack.X, pack.Y)).FirstOrDefault();
            if (prey != null) { pack.TargetX = prey.X; pack.TargetY = prey.Y; }
        }

        void PackHunts(Simulation sim, AnimalGroup pack)
        {
            pack.Hunger = Math.Min(1.5, pack.Hunger + 0.25);
            var prey = _groups.Where(g => !g.Gone && (g.Species == Species.Deer || g.Species == Species.Rabbit || g.Species == Species.Boar))
                .Where(g => WorldMap.Distance(g.X, g.Y, pack.X, pack.Y) < 5)
                .OrderByDescending(g => g.Species.RationsPerKill).FirstOrDefault();
            if (prey != null && sim.Rng.Chance(0.3))
            {
                prey.Count -= 1;
                pack.Hunger = 0;
            }
            if (pack.Hunger > 1.2 && sim.Rng.Chance(0.05))
            {
                pack.Count -= 1;
                if (pack.Gone) sim.Chronicle.Write(sim.Clock, Importance.Notable, "The last of the wolf pack starved.");
            }
        }

        void SpringBirths(Simulation sim)
        {
            foreach (var sp in Species.All)
            {
                int total = Total(sp);
                if (total <= 1)
                {
                    if (_extinct.Add(sp) && sp != Species.Wolf)
                        sim.Chronicle.Write(sim.Clock, Importance.Major, $"No {sp.Plural} are left in the valley.");
                    continue;
                }
                int births = (int)Math.Round(total * sp.BirthRate * Math.Max(0, 1 - (double)total / sp.CarryingCapacity));
                var groups = Living(sp).ToList();
                for (int i = 0; i < births; i++) groups[sim.Rng.Range(0, groups.Count)].Count++;

                // Big groups split, so herds spread over the valley.
                foreach (var g in groups.Where(g => g.Count > sp.GroupMax * 1.5).ToList())
                {
                    int half = g.Count / 2;
                    g.Count -= half;
                    _groups.Add(new AnimalGroup(_nextId++, sp, half, g.X, g.Y));
                }
            }
            _groups.RemoveAll(g => g.Gone);
        }

        static void Step(AnimalGroup g, double maxCells)
        {
            double dx = g.TargetX - g.X, dy = g.TargetY - g.Y;
            double d = Math.Sqrt(dx * dx + dy * dy);
            if (d < 0.01) return;
            double s = Math.Min(maxCells, d) / d;
            g.X += dx * s; g.Y += dy * s;
        }

        static Cell RandomCell(WorldMap map, Rng rng, Terrain terrain)
        {
            for (int i = 0; i < 200; i++)
            {
                var c = map[rng.Range(0, map.Size), rng.Range(0, map.Size)];
                if (c.Terrain == terrain) return c;
            }
            return map[rng.Range(0, map.Size), rng.Range(0, map.Size)];
        }

        static Cell NearbyCell(WorldMap map, Rng rng, double x, double y, double radius, Terrain terrain)
        {
            for (int i = 0; i < 40; i++)
            {
                int cx = (int)(x + rng.Range(-radius, radius)), cy = (int)(y + rng.Range(-radius, radius));
                if (map.InBounds(cx, cy) && map[cx, cy].Terrain == terrain) return map[cx, cy];
            }
            return RandomCell(map, rng, terrain);
        }
    }
}

