using System.Collections.Generic;
using Anthro.Sim.Activities;

namespace Anthro.Sim.People
{
    /// <summary>
    /// What a person expects an activity to yield, learned from their own results and from others.
    /// This is the simplest real form of learning in the sim: prediction, error, adjustment.
    /// </summary>
    public sealed class Expectations
    {
        readonly Dictionary<Verb, double> _values = new Dictionary<Verb, double>();

        public double Get(Verb verb, double fallback) => _values.TryGetValue(verb, out var v) ? v : fallback;

        public bool Has(Verb verb) => _values.ContainsKey(verb);

        /// <summary>
        /// Move toward what actually happened. Open people adjust faster; cautious people
        /// weigh disappointments double.
        /// </summary>
        public void Learn(Person p, Verb verb, double outcome, double fallback)
        {
            double current = Get(verb, fallback);
            double error = outcome - current;
            double rate = 0.1 + 0.3 * p.M(MindTrait.Openness);
            if (error < 0) rate *= 1 + (1 - p.M(MindTrait.Boldness));
            _values[verb] = current + System.Math.Min(1, rate) * error;
        }

        /// <summary>Copy part of someone else's expectation (social learning).</summary>
        public void Absorb(Verb verb, double theirs, double weight, double fallback)
        {
            double current = Get(verb, fallback);
            _values[verb] = current + weight * (theirs - current);
        }

        public IEnumerable<KeyValuePair<Verb, double>> All => _values;
    }
}

