using System;
using System.Linq;
using Anthro.Sim.People;
using Anthro.Sim.World;

namespace Anthro.Sim.Activities
{
    /// <summary>Walk out → gather → walk back. Yield depends on the patch, skill, age and interest.</summary>
    public sealed class Forage : Activity
    {
        public const double FallbackPerHour = 0.4;

        Cell? _patch;
        int _travel, _gatherLeft;
        double _gathered, _storable;
        int _hours;

        public Forage(Person p) : base(p) { }
        public override Verb Verb => Verb.Forage;

        public override void Begin(Simulation sim)
        {
            _patch = sim.World.Around(sim.Band.CampX, sim.Band.CampY, 12)
                .Where(c => c.PlantStock > 0.3)
                .OrderByDescending(c => c.PlantStock / (1 + WorldMap.Distance(c.X, c.Y, sim.Band.CampX, sim.Band.CampY) * 0.08)
                                        + sim.Rng.Range(0, 0.6))
                .FirstOrDefault();
            if (_patch == null) { Step = "finding nothing"; _gatherLeft = 2; return; }
            _travel = Math.Max(1, WorldMap.TravelHours(WorldMap.Distance(_patch.X, _patch.Y, sim.Band.CampX, sim.Band.CampY)));
            _gatherLeft = 4 + (int)(P.M(MindTrait.Patience) * 3);
            Step = "walking out";
        }

        public override void Hour(Simulation sim)
        {
            _hours++;
            P.Fatigue = Inheritance.Clamp01(P.Fatigue + 0.04);
            if (_travel > 0 && Step == "walking out") { _travel--; if (_travel == 0) Step = "gathering"; return; }
            if (_gatherLeft > 0)
            {
                Step = _patch == null ? "finding nothing" : "gathering";
                if (_patch != null)
                {
                    P.X = _patch.X; P.Y = _patch.Y;
                    double age = P.AgeYears(sim.Clock);
                    double ageFactor = age < 14 ? age / 14 : age > 55 ? 0.7 : 1;
                    double rate = 0.35 * (0.5 + P.S(Skill.Foraging)) * (1 + 0.3 * P.I(Interest.Plants)) * ageFactor;
                    double take = Math.Min(_patch.PlantStock, rate);
                    _patch.PlantStock -= take;
                    _gathered += take;
                    if (Cell.Storable(_patch.Plant)) _storable += take;
                    P.Practice(Skill.Foraging, 1);
                }
                if (--_gatherLeft == 0) { Step = "walking back"; _travel = Math.Max(1, _travel); }
                return;
            }
            if (--_travel > 0) return;
            Finish(sim);
        }

        void Finish(Simulation sim)
        {
            P.X = sim.Band.CampX; P.Y = sim.Band.CampY;
            sim.Band.Food.Stored += _storable;
            sim.Band.Food.Plants += _gathered - _storable;
            double perHour = _gathered / Math.Max(1, _hours);
            P.Expect.Learn(P, Verb.Forage, perHour, FallbackPerHour);
            if (perHour > FallbackPerHour) P.Nudge(Interest.Plants, 0.005);
            Done = true;
        }
    }

    /// <summary>A trip to the hills for flint. Without flint there are no new tools.</summary>
    public sealed class GatherFlint : Activity
    {
        int _hoursLeft;
        Cell? _source;

        public GatherFlint(Person p) : base(p) { }
        public override Verb Verb => Verb.GatherFlint;

        public override void Begin(Simulation sim)
        {
            _source = sim.World.All().Where(c => c.Has(Feature.Flint))
                .OrderBy(c => WorldMap.Distance(c.X, c.Y, sim.Band.CampX, sim.Band.CampY)).FirstOrDefault();
            _hoursLeft = _source == null ? 1 : 2 + 2 * WorldMap.TravelHours(WorldMap.Distance(_source.X, _source.Y, sim.Band.CampX, sim.Band.CampY));
            Step = "walking to the flint";
        }

        public override void Hour(Simulation sim)
        {
            P.Fatigue = Inheritance.Clamp01(P.Fatigue + 0.05);
            if (--_hoursLeft > 0) return;
            if (_source != null)
            {
