using System;
using System.Collections.Generic;
using System.Linq;
using Anthro.Sim.Core;
using Anthro.Sim.Ecology;
using Anthro.Sim.People;
using Anthro.Sim.World;

namespace Anthro.Sim.Activities
{
    /// <summary>
    /// A group hunt: gather a party → walk out → track → stalk → strike → (chase) → butcher → walk back → share.
    /// Every member holds a <see cref="Hunt"/> activity pointing at the same party; the party advances once per hour.
    /// </summary>
    public sealed class HuntParty
    {
        public const double FallbackPerHour = 0.6;

        public enum Phase { Gather, Out, Track, Stalk, Strike, Chase, Butcher, Back, Done }

        public readonly List<Person> Members = new List<Person>();
        public Phase Current { get; private set; } = Phase.Gather;
        public AnimalGroup? Target { get; private set; }
        public Person? Killer { get; private set; }

        int _left, _hours, _travel;
        double _rations;
        bool _chased;
        long _lastTick = -1;

        public HuntParty(Person leader) { Members.Add(leader); }

        public bool IsDone => Current == Phase.Done;

        public string StepName => Current switch
        {
            Phase.Gather => "gathering the party",
            Phase.Out => "walking out",
            Phase.Track => Target == null ? "tracking" : $"tracking {Target.Species.Plural}",
            Phase.Stalk => "stalking",
            Phase.Strike => "striking",
            Phase.Chase => "chasing",
            Phase.Butcher => "butchering",
            Phase.Back => _rations > 0 ? "carrying meat home" : "walking back",
            _ => "home",
        };

        public void Recruit(Simulation sim)
        {
            var leader = Members[0];
            var candidates = sim.Band.Members
                .Where(p => p != leader && p.Alive && CanHunt(sim, p) && (p.Current == null || p.Current.Interruptible) && !(p.Current is Hunt))
                .Select(p => (p, score: p.M(MindTrait.Boldness) * 0.5 + p.I(Interest.Animals) * 0.5 + p.GetAffinity(leader) * 0.5
                                       + p.S(Skill.Hunting) * 0.3 + sim.Rng.Range(0, 0.5)))
                .Where(x => x.score > 0.75)
                .OrderByDescending(x => x.score)
                .Take(5);
            foreach (var (p, _) in candidates)
            {
                Members.Add(p);
                p.Current = new Hunt(p, this);
            }
        }

        public static bool CanHunt(Simulation sim, Person p)
        {
            double age = p.AgeYears(sim.Clock);
            return age >= 14 && age < 55 && p.Health > 0.6 && p.Injury < 0.3 && sim.Clock.Day - p.LastHuntDay >= 2;
        }

        public void Advance(Simulation sim)
        {
            if (_lastTick == sim.Clock.Tick || IsDone) return;
            _lastTick = sim.Clock.Tick;
            _hours++;
            var alive = Members.Where(m => m.Alive).ToList();
            if (alive.Count == 0) { Current = Phase.Done; return; }
            foreach (var m in alive)
            {
                m.Fatigue = Inheritance.Clamp01(m.Fatigue + 0.05);
                m.Practice(Skill.Hunting, 1);
            }

            switch (Current)
            {
                case Phase.Gather: ChooseTarget(sim, alive); break;
                case Phase.Out: if (--_left <= 0) { Current = Phase.Track; _left = 6; } break;
                case Phase.Track: Track(sim, alive); break;
                case Phase.Stalk: Stalk(sim, alive); break;
                case Phase.Strike: Strike(sim, alive); break;
                case Phase.Chase: if (--_left <= 0) Current = Phase.Strike; break;
                case Phase.Butcher: if (--_left <= 0) GoBack(); break;
                case Phase.Back: if (--_left <= 0) Finish(sim, alive); break;
            }
        }

        void ChooseTarget(Simulation sim, List<Person> alive)
        {
            double bold = alive.Average(m => m.M(MindTrait.Boldness));
            var options = sim.Ecology.Groups
                .Where(g => !g.Gone && g.Species.Huntable)
                .Where(g => g.Species != Species.Mammoth || alive.Count >= 4)
                .Select(g => (g, d: WorldMap.Distance(g.X, g.Y, sim.Band.CampX, sim.Band.CampY)))
                .Where(x => x.d < 30)
                .Select(x => (x.g, x.d, score: x.g.Species.RationsPerKill * x.g.Species.KillChance
                                               - x.g.Species.Danger * 120 * (1 - bold) - x.d * 0.5 + sim.Rng.Range(0, 10)))
                .OrderByDescending(x => x.score)
                .ToList();
            if (options.Count == 0) { GoBack(); return; }
            Target = options[0].g;
            _travel = Math.Max(1, WorldMap.TravelHours(options[0].d));
            _left = _travel;
            Current = Phase.Out;
        }

        void Track(Simulation sim, List<Person> alive)
        {
            if (Target == null || Target.Gone) { GoBack(); return; }
            double skill = alive.Average(m => m.S(Skill.Hunting));
            if (sim.Rng.Chance(0.2 + 0.5 * skill)) { Current = Phase.Stalk; return; }
            if (--_left <= 0) GoBack();
        }

        void Stalk(Simulation sim, List<Person> alive)
        {
            var sp = Target!.Species;
            double stealth = alive.Average(m => (m.S(Skill.Hunting) + m.M(MindTrait.Patience)) / 2);
            if (sim.Rng.Chance(sp.Wariness * (1.2 - stealth) * (0.85 + 0.05 * alive.Count)))
            {
                if (!_chased && sim.Rng.Chance(0.3 * alive.Average(m => m.M(MindTrait.Boldness)) + 0.1))
                {
                    _chased = true; Current = Phase.Chase; _left = 2;
                }
                else GoBack();
                return;
            }
            Current = Phase.Strike;
        }

        void Strike(Simulation sim, List<Person> alive)
        {
            var sp = Target!.Species;
            double skill = alive.Average(m => m.S(Skill.Hunting));
            double tools = sim.Band.Materials.Tools >= alive.Count ? 1 : 0.7;
            double weapons = sim.Band.AnyoneKnows("spear.stone") ? 1.2 : 1;
            double pKill = sp.KillChance * (0.6 + skill * 0.8) * Math.Min(1.5, 0.7 + 0.15 * alive.Count) * tools * weapons;
            if (_chased) pKill *= 0.6;
            sim.Band.Materials.Tools = Math.Max(0, sim.Band.Materials.Tools - 0.2 * alive.Count);

            if (sim.Rng.Chance(sp.Danger))
            {
                var victim = alive.OrderByDescending(m => m.M(MindTrait.Boldness) + sim.Rng.Range(0, 0.3)).First();
                victim.Injury = Inheritance.Clamp01(victim.Injury + sim.Rng.Range(0.2, 0.9) * (1.2 - victim.B(BodyTrait.Endurance) * 0.4));
                if (victim.Injury >= 0.95)
                    sim.Kill(victim, sp == Species.Mammoth ? "trampled by a mammoth" : $"killed by a {sp.Name}");
                else
                    sim.Chronicle.Write(sim.Clock, Importance.Notable, $"{victim.Name} was badly hurt hunting {sp.Plural}.");
            }

            if (sim.Rng.Chance(pKill))
            {
                Target.Count--;
                _rations = sp.RationsPerKill;
                Killer = alive.OrderByDescending(m => m.S(Skill.Hunting) + m.M(MindTrait.Boldness) * 0.5 + sim.Rng.Range(0, 0.5)).First();
                Current = Phase.Butcher;
                _left = sp == Species.Mammoth ? 6 : sp == Species.Rabbit ? 1 : 2;
                return;
            }
            if (!_chased && sim.Rng.Chance(0.35)) { _chased = true; Current = Phase.Chase; _left = 2; return; }
            GoBack();
        }

        void GoBack()
        {
            Current = Phase.Back;
            _left = Math.Max(1, _travel);
        }

        void Finish(Simulation sim, List<Person> alive)
        {
            Current = Phase.Done;
            var band = sim.Band;
            if (_rations > 0 && Target != null)
            {
                var sp = Target.Species;
                band.Food.Meat += _rations;
                band.Materials.Hides += sp.Hides;
                band.Materials.Sinew += sp.Sinew;
                band.Materials.Bone += sp.Bone;
                sim.RecordKill(sp, Killer!, alive.Count);
                if (Killer != null && Killer.Alive)
                {
                    Killer.Prestige += sp.RationsPerKill / 100.0;
                    Killer.Nudge(Interest.Animals, 0.02);
                }
            }
            double perHour = _rations / Math.Max(1, alive.Count * _hours);
            foreach (var m in alive)
            {
                m.LastHuntDay = sim.Clock.Day;
                m.X = band.CampX; m.Y = band.CampY;
                m.Expect.Learn(m, Verb.Hunt, perHour, FallbackPerHour);
            }
        }
    }

    public sealed class Hunt : Activity
    {
        public readonly HuntParty Party;

        public Hunt(Person p, HuntParty party) : base(p) { Party = party; }

        public override Verb Verb => Verb.Hunt;
        public override bool Interruptible => false;

        public override void Begin(Simulation sim)
        {
            if (Party.Members[0] == P) Party.Recruit(sim);
        }

        public override void Hour(Simulation sim)
        {
            Party.Advance(sim);
            Step = Party.StepName;
            Done = Party.IsDone;
        }
    }
}

