using System;
using System.Collections.Generic;
using System.Linq;
using Anthro.Sim.Activities;
using Anthro.Sim.Core;
using Anthro.Sim.Discovery;
using Anthro.Sim.Ecology;
using Anthro.Sim.People;
using Anthro.Sim.World;

namespace Anthro.Sim
{
    public sealed class YearStats
    {
        public int Year;
        public int Births;
        public int Population;
        public readonly Dictionary<string, int> Deaths = new Dictionary<string, int>();
        public readonly Dictionary<string, int> Kills = new Dictionary<string, int>();
    }

    /// <summary>
    /// One valley, one band. <see cref="Step"/> advances one in-game hour. Everything is driven by
    /// a single seed, so the same seed always replays the same history.
    /// </summary>
    public sealed class Simulation
    {
        public readonly Rng Rng;
        public readonly SimClock Clock = new SimClock();
        public readonly Chronicle Chronicle = new Chronicle();
        public readonly WorldMap World;
        public readonly EcologySystem Ecology = new EcologySystem();
        public readonly Band Band = new Band();
        public readonly DiscoveryWeb? Web;

        /// <summary>Best plant patches near camp, refreshed daily so foragers don't each scan the map.</summary>
        public readonly List<Cell> ForagePatches = new List<Cell>();

        public YearStats ThisYear { get; private set; } = new YearStats();
        public event Action<YearStats>? YearEnded;

        readonly Names _names = new Names();
        readonly HashSet<Species> _killedBefore = new HashSet<Species>();
        int _nextPersonId;
        long _lastCampMove = -100;
        bool _wolvesSeenThisSeason, _hungerReportedThisSeason;

        static readonly string[] DefaultKnown = { "fire.make", "knap.flake", "knap.blade", "spear.wood", "forage.rounds", "lang.speech", "wood.shape", "shelter.brush" };

        Simulation(ulong seed, DiscoveryWeb? web)
        {
            Rng = new Rng(seed);
            Web = web;
            World = WorldGen.Generate(Rng.Fork(1));
            Ecology.Populate(World, Rng.Fork(2));
        }

        public static Simulation Create(ulong seed, DiscoveryWeb? web = null, int bandSize = 30)
        {
            var sim = new Simulation(seed, web);
            sim.FoundBand(bandSize);
            return sim;
        }

        public bool Extinct => Band.Members.Count == 0;

        public void Step()
        {
            if (Clock.Hour == 0) Daily();
            if (Clock.Hour == 7 || Clock.Hour == 19) Meal();

            foreach (var p in Band.Members.ToList())
            {
                if (!p.Alive) continue;
                if (p.Current == null || p.Current.Done)
                {
                    p.Current = Decider.Choose(this, p);
                    p.Current.Begin(this);
                }
                p.Current.Hour(this);
            }

            Clock.Advance();
            if (Clock.Tick % (SimClock.HoursPerDay * SimClock.DaysPerYear) == 0) EndYear();
        }

        public void RunYears(int years)
        {
            long end = Clock.Tick + (long)years * SimClock.HoursPerDay * SimClock.DaysPerYear;
            while (Clock.Tick < end && !Extinct) Step();
        }

        // ---- Founding ------------------------------------------------------------------------

        void FoundBand(int size)
        {
            Band.Name = _names.Next(Rng);
            for (int i = 0; i < TraitCounts.Mind; i++) Band.AttractionMind[i] = Rng.Normal(0, 0.2);
            for (int i = 0; i < TraitCounts.Body; i++) Band.AttractionBody[i] = Rng.Normal(0, 0.2);

            var camp = ScoreCampSites(30).First();
            Band.CampX = camp.X; Band.CampY = camp.Y;

            for (int i = 0; i < 3; i++) NewFounder(Rng.Range(48, 63), Rng.Chance(0.5) ? Sex.Female : Sex.Male);
            int couples = Math.Max(1, size / 4);
            for (int i = 0; i < couples && Band.Members.Count < size; i++)
            {
                double womanAge = Rng.Range(18, 38);
                var woman = NewFounder(womanAge, Sex.Female);
                var man = NewFounder(Math.Max(16, womanAge + Rng.Range(-2, 8)), Sex.Male);
                woman.Partner = man; man.Partner = woman;
                woman.AddAffinity(man, 0.6); man.AddAffinity(woman, 0.6);
                int kids = Rng.Range(0, 4);
                for (int k = 0; k < kids && Band.Members.Count < size; k++)
                    NewChild(woman, man, Rng.Range(0, Math.Max(1, womanAge - 16)));
            }
            while (Band.Members.Count < size) NewFounder(Rng.Range(14, 26), Rng.Chance(0.5) ? Sex.Female : Sex.Male);

            Band.Food.Meat = 30; Band.Food.Plants = 20;
            Band.Materials.Flint = 6; Band.Materials.Tools = 25;
            RefreshForagePatches();
            Chronicle.Write(Clock, Importance.Major,
                $"The {Band.Name} band, {Band.Members.Count} people, made camp in a {World[(int)Band.CampX, (int)Band.CampY].Terrain.ToString().ToLower()} by the river.");
        }

        Person NewFounder(double ageYears, Sex sex)
        {
            var p = new Person(_nextPersonId++, _names.Next(Rng), sex, -(long)(ageYears * SimClock.DaysPerYear));
            for (int i = 0; i < p.Mind.Length; i++) p.Mind[i] = Inheritance.Founder(Rng);
            for (int i = 0; i < p.Body.Length; i++) p.Body[i] = Inheritance.Founder(Rng);
            for (int i = 0; i < p.Interests.Length; i++) p.Interests[i] = Inheritance.Clamp01(Rng.Normal(0.35, 0.15));
            SeedSkills(p, ageYears);
            Join(p);
            return p;
        }

        Person NewChild(Person mother, Person father, double ageYears)
        {
            var p = new Person(_nextPersonId++, _names.Next(Rng), Rng.Chance(0.5) ? Sex.Female : Sex.Male, Clock.Day - (long)(ageYears * SimClock.DaysPerYear));
            p.Mother = mother; p.Father = father;
            mother.Children.Add(p); father.Children.Add(p);
            for (int i = 0; i < p.Mind.Length; i++) p.Mind[i] = Inheritance.Blend(Rng, mother.Mind[i], father.Mind[i]);
            for (int i = 0; i < p.Body.Length; i++) p.Body[i] = Inheritance.Blend(Rng, mother.Body[i], father.Body[i]);
            for (int i = 0; i < p.Interests.Length; i++)
                p.Interests[i] = Inheritance.Clamp01((mother.Interests[i] + father.Interests[i]) / 2 * 0.4 + Rng.Normal(0.2, 0.1));
            SeedSkills(p, ageYears);
            p.AddAffinity(mother, 0.5); p.AddAffinity(father, 0.4);
            mother.AddAffinity(p, 0.6); father.AddAffinity(p, 0.5);
            Join(p);
            return p;
        }

        void SeedSkills(Person p, double age)
        {
            double grown = Inheritance.Clamp01(age / 25);
            p.Skills[(int)Skill.Foraging] = grown * Rng.Range(0.4, 0.9);
            p.Skills[(int)Skill.Hunting] = age >= 14 ? grown * Rng.Range(0.2, 0.8) * (0.5 + p.M(MindTrait.Boldness)) : 0;
            p.Skills[(int)Skill.Knapping] = age >= 12 ? grown * Rng.Range(0.1, 0.7) : 0;
            p.Skills[(int)Skill.Fire] = grown * 0.5;
            p.Skills[(int)Skill.Caring] = age >= 14 ? Rng.Range(0.2, 0.6) : 0;
            p.Skills[(int)Skill.Teaching] = age >= 20 ? Rng.Range(0.1, 0.5) : 0;
        }

        /// <summary>
        /// Everyone is born into the band's starting culture. Stages discovered later have to be
        /// taught (next slice).
        /// </summary>
        void Join(Person p)
        {
            foreach (var id in Web != null ? Web.KnownAtStart.Select(s => s.Id) : DefaultKnown) p.Knows.Add(id);
            p.X = Band.CampX; p.Y = Band.CampY;
            Band.Members.Add(p);
        }

        // ---- Daily ---------------------------------------------------------------------------

        void Daily()
        {
            if (Clock.DayOfYear == 0 && Clock.Year == 0) World.Climate.NewYear(Rng);
            var season = Clock.Season;
            double temp = World.Climate.TemperatureC(season);

            if (Clock.DayOfSeason == 0)
            {
                _wolvesSeenThisSeason = false;
                _hungerReportedThisSeason = false;
                if (season == Season.Winter && World.Climate.WinterSeverity > 1)
                    Chronicle.Write(Clock, Importance.Notable, "A hard winter set in.");
            }

            foreach (var c in World.All()) c.DailyRegrow(season);
            Ecology.DailyUpdate(this);
            Band.Food.DailySpoil(temp);
            Band.Materials.Tools *= 0.997;

            foreach (var p in Band.Members.ToList()) DailyBody(p, temp);
            foreach (var p in Band.Members.Where(m => m.DueDay == Clock.Day).ToList()) GiveBirth(p);
            foreach (var p in Band.Members.ToList()) MaybeConceive(p);
            if (Clock.DayOfYear == 0) FormPairs();
            WolvesNearCamp();
            if (Clock.Day % 7 == 0) ConsiderMovingCamp();
            RefreshForagePatches();
            ReportHunger();
        }

        void Meal()
        {
            double need = 0;
            foreach (var p in Band.Members) need += MealNeed(p);
            if (need <= 0) return;
            double eaten = Band.Food.Take(need);
            double share = eaten / need;
            foreach (var p in Band.Members) p.Satiety = Inheritance.Clamp01(p.Satiety + (share - p.Satiety) * 0.3);
        }

        double MealNeed(Person p)
        {
            double age = p.AgeYears(Clock);
            double need = age < 14 ? 0.2 + 0.3 * age / 14 : 0.5;
            if (p.DueDay >= 0) need += 0.1;
            return need * (0.85 + 0.3 * p.B(BodyTrait.Build) * p.B(BodyTrait.Height));
        }

        void DailyBody(Person p, double temp)
        {
            double age = p.AgeYears(Clock);

            if (p.Satiety < 0.35) p.Health -= (0.35 - p.Satiety) * 0.06;
            else p.Health = Math.Min(1 - p.Injury * 0.5, p.Health + 0.01);
            p.Injury = Math.Max(0, p.Injury - 0.01 * (0.5 + p.B(BodyTrait.Endurance)));

            double cold = Math.Max(0, -temp / 12.0 - p.B(BodyTrait.ColdTolerance) * 0.5 - p.B(BodyTrait.Build) * 0.2 - 0.25);
            if (age < 5 || age > 60) cold *= 1.5;
            p.Health -= cold * 0.03;

            if (Rng.Chance(0.0015 * (1.5 - p.B(BodyTrait.Endurance)))) p.Health -= Rng.Range(0.1, 0.45);
            if (age < 3 && p.CareToday < 3) p.Health -= 0.01;
            p.CareToday = 0;
            p.Fatigue *= 0.9;

            if (age < 12) DriftTowardParents(p);

            p.Health = Math.Min(1, p.Health);
            if (p.Health <= 0)
            {
                Kill(p, p.Satiety < 0.35 ? "starvation" : cold > 0.3 ? "cold" : p.Injury > 0.5 ? "wounds" : "illness");
                return;
            }
            double yearly = age < 1 ? 0.10 : age < 5 ? 0.025 : age < 15 ? 0.006 : 0.004 * Math.Exp((age - 25) / 10.0);
            if (Rng.Chance(yearly / SimClock.DaysPerYear * (1.6 - 0.6 * p.Health)))
                Kill(p, age > 55 ? "old age" : age < 5 ? "childhood illness" : "illness");
        }

        /// <summary>Children's interests lean toward whoever raises them.</summary>
        static void DriftTowardParents(Person child)
        {
            foreach (var parent in new[] { child.Mother, child.Father })
            {
                if (parent == null || !parent.Alive) continue;
                for (int i = 0; i < child.Interests.Length; i++)
                    child.Interests[i] += (parent.Interests[i] - child.Interests[i]) * 0.002;
            }
        }

        public void Kill(Person p, string cause)
        {
            if (!p.Alive) return;
            double age = p.AgeYears(Clock);
            p.Alive = false;
            p.DeathCause = cause;
            Band.Members.Remove(p);
            Band.Dead.Add(p);
            if (p.Partner != null) { p.Partner.Partner = null; p.Partner = null; }
            ThisYear.Deaths[cause] = ThisYear.Deaths.TryGetValue(cause, out var n) ? n + 1 : 1;

            string what = cause.StartsWith("killed") || cause.StartsWith("trampled") ? $"was {cause}" : $"died of {cause}";
            string who = p.Prestige > 1.5 ? $"{p.Name}, one of the band's great hunters," : p.Name;
            Chronicle.Write(Clock, age < 5 ? Importance.Detail : Importance.Notable, $"{who} {what} at {(int)age}.");

            foreach (var stage in p.Knows)
                if (!Band.AnyoneKnows(stage) && Web != null && Web.Stages.TryGetValue(stage, out var s) && !s.Known)
                    Chronicle.Write(Clock, Importance.Major, $"When {p.Name} died, the band lost {s.Name.ToLower()}.");

            if (Band.Members.Count == 0)
                Chronicle.Write(Clock, Importance.Major, $"With {p.Name}'s death, the {Band.Name} band is gone.");
        }

        // ---- Families ------------------------------------------------------------------------

        void MaybeConceive(Person p)
        {
            if (p.Sex != Sex.Female || p.DueDay >= 0 || p.Partner == null || !p.Partner.Alive) return;
            double age = p.AgeYears(Clock);
            if (age < 16 || age > 42 || p.Satiety < 0.5) return;
            if (p.Children.Any(c => c.Alive && c.AgeYears(Clock) < 2)) return;
            if (Rng.Chance(0.12 / 30 * p.Health)) p.DueDay = Clock.Day + 270;
        }

        void GiveBirth(Person mother)
        {
            mother.DueDay = -1;
            var father = mother.Partner ?? Band.Dead.LastOrDefault(d => d.Partner == null && d.Sex == Sex.Male) ?? mother;
            var child = NewChild(mother, father, 0);
            ThisYear.Births++;
            Chronicle.Write(Clock, Importance.Detail, $"{child.Name} was born to {mother.Name} and {father.Name}.");
            if (Rng.Chance(0.012 * (1.5 - mother.Health))) Kill(mother, "childbirth");
        }

        void FormPairs()
        {
            var women = Band.Members.Where(p => p.Sex == Sex.Female && p.Partner == null && Between(p, 16, 45)).ToList();
            var men = Band.Members.Where(p => p.Sex == Sex.Male && p.Partner == null && Between(p, 16, 60)).ToList();
            foreach (var w in women.OrderBy(_ => Rng.NextUInt()))
            {
                var pick = men.Where(m => !w.IsKin(m))
                    .Select(m => (m, score: w.GetAffinity(m) + Attraction(m) + m.GetAffinity(w) + Attraction(w) + Rng.Range(0, 0.4)))
                    .OrderByDescending(x => x.score).FirstOrDefault();
                if (pick.m == null || pick.score < 0.3) continue;
                w.Partner = pick.m; pick.m.Partner = w;
                w.AddAffinity(pick.m, 0.3); pick.m.AddAffinity(w, 0.3);
                men.Remove(pick.m);
                Chronicle.Write(Clock, Importance.Detail, $"{w.Name} and {pick.m.Name} paired.");
            }
        }

        bool Between(Person p, double min, double max) { var a = p.AgeYears(Clock); return a >= min && a <= max; }

        /// <summary>How attractive the band's culture finds this person.</summary>
        double Attraction(Person p)
        {
            double s = 0;
            for (int i = 0; i < p.Mind.Length; i++) s += Band.AttractionMind[i] * (p.Mind[i] - 0.5);
            for (int i = 0; i < p.Body.Length; i++) s += Band.AttractionBody[i] * (p.Body[i] - 0.5);
            return s + p.Prestige * 0.1;
        }

        // ---- Hunting results ------------------------------------------------------------------

        public void RecordKill(Species sp, Person killer, int partySize)
        {
            ThisYear.Kills[sp.Name] = ThisYear.Kills.TryGetValue(sp.Name, out var n) ? n + 1 : 1;

            // A band admires its successful hunters a little more each time: culture drifting.
            Band.AttractionMind[(int)MindTrait.Boldness] = Math.Min(1, Band.AttractionMind[(int)MindTrait.Boldness] + 0.002);
            Band.AttractionBody[(int)BodyTrait.Strength] = Math.Min(1, Band.AttractionBody[(int)BodyTrait.Strength] + 0.002);

            if (sp == Species.Mammoth)
                Chronicle.Write(Clock, Importance.Major, $"{killer.Name}'s party of {partySize} brought down a mammoth.");
            else if (_killedBefore.Add(sp) && sp != Species.Rabbit)
                Chronicle.Write(Clock, Importance.Notable, $"{killer.Name} made the band's first {sp.Name} kill in this valley.");
        }

        // ---- Threats and movement --------------------------------------------------------------

        void WolvesNearCamp()
        {
            double strength = Band.Strength(Clock);
            foreach (var pack in Ecology.Living(Species.Wolf).ToList())
            {
                if (WorldMap.Distance(pack.X, pack.Y, Band.CampX, Band.CampY) > 12 || pack.Hunger < 0.75) continue;
                double power = pack.Count * pack.Hunger * 0.8;
                if (power > strength * 0.35 && Rng.Chance(0.25))
                {
                    var exposed = Band.Members.Where(p => p.Current is Forage || p.Current is GatherFlint || p.AgeYears(Clock) < 8).ToList();
                    if (exposed.Count == 0) exposed = Band.Members.ToList();
                    var victim = Rng.Pick(exposed);
                    victim.Injury = Inheritance.Clamp01(victim.Injury + Rng.Range(0.3, 1.0));
                    pack.Hunger = 0;
                    if (victim.Injury >= 0.9) Kill(victim, "killed by wolves");
                    else Chronicle.Write(Clock, Importance.Major, $"Starving wolves attacked {victim.Name}.");
                }
                else if (!_wolvesSeenThisSeason && Rng.Chance(0.1))
                {
                    _wolvesSeenThisSeason = true;
                    Chronicle.Write(Clock, Importance.Detail, "Wolves circled the camp at night, picking at scraps.");
                }
            }
        }

        void ConsiderMovingCamp()
        {
            if (Clock.Day - _lastCampMove < 30) return;
            double here = CampScore(Band.CampX, Band.CampY);
            var best = ScoreCampSites(12).First();
            if (CampScore(best.X, best.Y) <= here * 1.5) return;

            double dx = best.X - Band.CampX, dy = best.Y - Band.CampY;
            string dir = Math.Abs(dx) > Math.Abs(dy) ? (dx > 0 ? "east" : "west") : (dy > 0 ? "south" : "north");
            Band.CampX = best.X; Band.CampY = best.Y;
            _lastCampMove = Clock.Day;
            Chronicle.Write(Clock, Importance.Notable, $"The band moved camp {dir}, to the {best.Terrain.ToString().ToLower()}.");
        }

        IEnumerable<Cell> ScoreCampSites(int samples)
        {
            var list = new List<Cell>();
            for (int i = 0; i < samples * 4 && list.Count < samples; i++)
            {
                var c = World[Rng.Range(0, World.Size), Rng.Range(0, World.Size)];
                if (c.Terrain == Terrain.Forest || c.Terrain == Terrain.Grassland) list.Add(c);
            }
            return list.OrderByDescending(c => CampScore(c.X, c.Y));
        }

        double CampScore(double x, double y)
        {
            double plants = World.Around(x, y, 10).Sum(c => c.PlantStock);
            double game = Ecology.Groups.Where(g => !g.Gone && g.Species.Huntable && WorldMap.Distance(g.X, g.Y, x, y) < 15)
                .Sum(g => g.Count * g.Species.RationsPerKill * 0.1);
            double water = World.Around(x, y, 4).Any(c => c.Terrain == Terrain.River) ? 1.2 : 0.8;
            return (plants + game) * water;
        }

        void RefreshForagePatches()
        {
            ForagePatches.Clear();
            ForagePatches.AddRange(World.Around(Band.CampX, Band.CampY, 12)
                .Where(c => c.PlantStock > 0.3)
                .OrderByDescending(c => c.PlantStock / (1 + WorldMap.Distance(c.X, c.Y, Band.CampX, Band.CampY) * 0.08))
                .Take(25));
        }

        void ReportHunger()
        {
            if (_hungerReportedThisSeason || Band.Members.Count == 0) return;
            if (Band.Members.Average(p => p.Satiety) < 0.4)
            {
                _hungerReportedThisSeason = true;
                Chronicle.Write(Clock, Importance.Major, "Hunger gripped the band.");
            }
        }

        void EndYear()
        {
            ThisYear.Population = Band.Members.Count;
            YearEnded?.Invoke(ThisYear);
            ThisYear = new YearStats { Year = Clock.Year };
            World.Climate.NewYear(Rng);
        }
    }
}

