    /// <summary>
    /// A species is described by what it physically is and how it lives. How hunts and populations
    /// turn out comes from these properties meeting people's skills and weapons, never from a
    /// per-species outcome number.
    /// </summary>
    public sealed class Species
    {
        public string Name = "";
        public string Plural = "";
        public int GroupMin, GroupMax;

        // ---- Population (the valley is one corner of a wider region) ----
        /// <summary>Animals across the whole region at the start, valley included.</summary>
        public int RegionalStart;
        /// <summary>What the whole region can support.</summary>
        public int RegionalCapacity;
        /// <summary>Yearly growth rate when far below capacity.</summary>
