using System;
using System.Collections.Generic;
using System.Linq;
using Anthro.Sim.Core;
using Anthro.Sim.Ecology;
using Anthro.Sim.People;
using Anthro.Sim.World;

namespace Anthro.Sim.Activities
{
    /// <summary>
    /// A group hunt: gather a party → walk out → track → stalk → strike → (chase) → butcher → walk back → share.
    /// Every member holds a <see cref="Hunt"/> pointing at the same party; the party advances once per hour.
    ///
    /// Nothing here is a per-species success rate. Hunters must get within weapon range before the
    /// animals bolt (flight distance grows with fear), land enough hits to match the animal's size,
    /// and face a charge from aggressive animals they wound.
    /// </summary>
    public sealed class HuntParty
    {
        public const double FallbackPerHour = 0.6;

        public enum Phase { Gather, Out, Track, Stalk, Strike, Chase, Butcher, Back, Done }

        public readonly List<Person> Members = new List<Person>();
        public Phase Current { get; private set; } = Phase.Gather;
        public AnimalGroup? Target { get; private set; }
        public Weapon? Weapon { get; private set; }
        public Person? Killer { get; private set; }

        int _left, _hours, _travel, _trackHours, _chases;
        double _damage, _rations;
        Species? _killed;
        long _lastTick = -1;

        public HuntParty(Person leader) { Members.Add(leader); }

        public bool IsDone => Current == Phase.Done;

        public string StepName => Current switch
        {
            Phase.Gather => "gathering the party",
            Phase.Out => "walking out",
            Phase.Track => Target == null ? "tracking" : $"tracking {Target.Species.Plural}",
            Phase.Stalk => "stalking",
            Phase.Strike => "striking",
            Phase.Chase => "chasing a wounded animal",
            Phase.Butcher => "butchering",
            Phase.Back => _rations > 0 ? "carrying meat home" : "walking back",
            _ => "home",
        };

        public void Recruit(Simulation sim)
        {
            var leader = Members[0];
            var candidates = sim.Band.Members
                .Where(p => p != leader && p.Alive && CanHunt(sim, p) && (p.Current == null || p.Current.Interruptible) && !(p.Current is Hunt))
                .Select(p => (p, score: p.M(MindTrait.Boldness) * 0.5 + p.I(Interest.Animals) * 0.5 + p.GetAffinity(leader) * 0.5
                                       + p.S(Skill.Hunting) * 0.3 + sim.Rng.Range(0, 0.5)))
                .Where(x => x.score > 0.75)
                .OrderByDescending(x => x.score)
                .Take(5);
            foreach (var (p, _) in candidates)
            {
                Members.Add(p);
                p.Current = new Hunt(p, this);
            }
        }

        public static bool CanHunt(Simulation sim, Person p)
        {
            double age = p.AgeYears(sim.Clock);
            return age >= 14 && p.Health > 0.6 && p.Injury < 0.3 && p.Sickness < 0.2 && sim.Clock.Day - p.LastHuntDay >= 2;
        }

        public void Advance(Simulation sim)
        {
            if (_lastTick == sim.Clock.Tick || IsDone) return;
            _lastTick = sim.Clock.Tick;
            _hours++;
            var alive = Members.Where(m => m.Alive).ToList();
            if (alive.Count == 0) { Current = Phase.Done; return; }
            foreach (var m in alive)
            {
                m.Fatigue = Inheritance.Clamp01(m.Fatigue + 0.05);
                m.Practice(Skill.Hunting, 1);
            }

            switch (Current)
            {
                case Phase.Gather: ChooseTarget(sim, alive); break;
                case Phase.Out: if (--_left <= 0) { Current = Phase.Track; _trackHours = 6; } break;
                case Phase.Track: Track(sim, alive); break;
                case Phase.Stalk: Stalk(sim, alive); break;
                case Phase.Strike: Strike(sim, alive); break;
                case Phase.Chase: Chase(sim, alive); break;
                case Phase.Butcher: if (--_left <= 0) GoBack(); break;
                case Phase.Back: if (--_left <= 0) Finish(sim, alive); break;
            }
        }

        /// <summary>
        /// Hunters weigh meat they can actually eat before it rots against how dangerous the animal
        /// looks to them and whether their party feels big enough for it.
        /// </summary>
        void ChooseTarget(Simulation sim, List<Person> alive)
        {
            double bold = alive.Average(m => m.M(MindTrait.Boldness));
            double horizon = sim.World.Climate.TemperatureC(sim.Clock.Season) < 0 ? 20 : 4;
            double canEat = sim.Band.Members.Count * 0.9 * horizon;
            var options = sim.Ecology.Groups
                .Where(g => !g.Gone && g.Species.Huntable)
                .Select(g => (g, d: WorldMap.Distance(g.X, g.Y, sim.Band.CampX, sim.Band.CampY)))
                .Where(x => x.d < 30)
                .Select(x =>
                {
                    var sp = x.g.Species;
                    double danger = sp.Aggression * sp.Size / 3 * (1.2 - bold);
                    double feasible = Math.Min(1, alive.Count / (sp.Size * 0.7));
                    double score = Math.Min(sp.Meat, canEat) * feasible * (1 - Math.Min(0.9, danger)) - x.d * 0.5 + sim.Rng.Range(0, 8);
                    return (x.g, x.d, score);
                })
                .OrderByDescending(x => x.score)
                .ToList();
            if (options.Count == 0) { GoBack(); return; }
            Target = options[0].g;
            Weapon = Weapon.Best(sim.Band, Target);
            _travel = Math.Max(1, WorldMap.TravelHours(options[0].d));
            _left = _travel;
            Current = Phase.Out;
        }

        void Track(Simulation sim, List<Person> alive)
        {
            if (Target == null || Target.Gone) { GoBack(); return; }
            double skill = alive.Average(m => m.S(Skill.Hunting));
            if (sim.Rng.Chance(0.2 + 0.5 * skill)) { Current = Phase.Stalk; return; }
            if (--_trackHours <= 0) GoBack();
        }

        /// <summary>Get within weapon range before the animals notice. Bigger parties make more noise.</summary>
        void Stalk(Simulation sim, List<Person> alive)
        {
            if (Target == null || Target.Gone) { GoBack(); return; }
            double stealth = alive.Average(m => (m.S(Skill.Hunting) + m.M(MindTrait.Patience)) / 2)
                             * Math.Max(0.5, 1 - 0.05 * (alive.Count - 2));
            double approach = Math.Max(0.03, Math.Min(0.95, stealth * Weapon!.Range / Target.FlightDistance * 1.5));
            if (sim.Rng.Chance(approach)) { Current = Phase.Strike; return; }

            sim.Ecology.Startle(Target, 0.3);
            Current = --_trackHours > 0 ? Phase.Track : Phase.Back;
            if (Current == Phase.Back) _left = Math.Max(1, _travel);
        }

        /// <summary>
        /// Everyone throws or thrusts. Hits add up against the animal's size. A wounded aggressive
        /// animal may charge; at close range that reaches the hunters.
        /// </summary>
        void Strike(Simulation sim, List<Person> alive)
        {
            if (Target == null || Target.Gone) { GoBack(); return; }
            var sp = Target.Species;
            var weapon = Weapon!;
            double toolFactor = sim.Band.Materials.Tools >= alive.Count ? 1 : 0.7;
            sim.Band.Materials.Tools = Math.Max(0, sim.Band.Materials.Tools - 0.2 * alive.Count);

            foreach (var m in alive)
            {
                double hit = 0.3 + 0.5 * m.S(Skill.Hunting) + (m.B(BodyTrait.Dexterity) - 0.5) * 0.2;
                if (sim.Rng.Chance(hit)) _damage += weapon.Power * toolFactor * sim.Rng.Range(0.6, 1.4) * (0.8 + m.B(BodyTrait.Strength) * 0.4);
            }
            sim.Ecology.Startle(Target, 0.5);

            if (_damage >= sp.Size) { Kill(sim, alive); return; }

            if (_damage > 0 && sim.Rng.Chance(sp.Aggression * (_chases > 0 ? 1.3 : 1)))
                Charge(sim, alive, sp, weapon);

            bool wounded = _damage > 0;
            bool pursue = wounded && _chases < 2 && sim.Rng.Chance(0.3 + 0.5 * alive.Average(m => m.M(MindTrait.Boldness)));
            if (pursue) { Current = Phase.Chase; _left = 2; return; }
            _damage = 0;
            Current = --_trackHours > 0 && !wounded ? Phase.Track : Phase.Back;
            if (Current == Phase.Back) _left = Math.Max(1, _travel);
        }

        void Charge(Simulation sim, List<Person> alive, Species sp, Weapon weapon)
        {
            double exposure = weapon.CloseRange ? 1 : 0.4;
            foreach (var m in alive)
            {
                if (!sim.Rng.Chance(sp.Aggression * 0.35 * exposure)) continue;
                double wound = sim.Rng.Range(0.15, 0.6) * (0.5 + sp.Size / 4) * (1.2 - m.B(BodyTrait.Endurance) * 0.4);
                m.Injury = Inheritance.Clamp01(m.Injury + wound);
                string by = sp == Species.Mammoth ? "trampled by a mammoth" : $"gored by a {sp.Name}";
                if (m.Injury >= 0.95) sim.Kill(m, by);
                else sim.Chronicle.Write(sim.Clock, Importance.Notable, $"{m.Name} was {by.Replace("trampled", "hurt").Replace("gored", "hurt")} while hunting.");
            }
        }

        /// <summary>Run down a wounded animal: endurance and nerve against its speed and how badly it's hurt.</summary>
        void Chase(Simulation sim, List<Person> alive)
        {
            if (--_left > 0) return;
            if (Target == null || Target.Gone) { GoBack(); return; }
            _chases++;
            double runners = alive.Average(m => (m.B(BodyTrait.Endurance) + m.M(MindTrait.Boldness)) / 2);
            double caught = runners * (1 - Target.Species.Speed) + 0.4 * Math.Min(1, _damage / Target.Species.Size);
            if (sim.Rng.Chance(caught)) { Current = Phase.Strike; return; }
            _damage = 0;
            GoBack();
        }

        void Kill(Simulation sim, List<Person> alive)
        {
            var sp = Target!.Species;
            Target.Count--;
            sim.Ecology.RecordKill(sp);
            _killed = sp;
            _rations = sp.Meat;
            _damage = 0;
