4	using Anthro.Sim.Core;
5	
6	namespace Anthro.Sim.People
7	{
8	    /// <summary>Shared food, kept by kind because each spoils at a different rate.</summary>
9	    public sealed class FoodStore
10	    {
11	        public double Meat, Plants, Stored;
12	        /// <summary>Average age of the meat in camp, in days. Past a few days it makes people sick.</summary>
13	        public double MeatAge;
14	
15	        public double Total => Meat + Plants + Stored;
16	
17	        public void AddMeat(double rations)
18	        {
19	            if (rations <= 0) return;
20	            MeatAge = Meat * MeatAge / (Meat + rations);
21	            Meat += rations;
22	        }
23	
24	        /// <summary>Eat what spoils first. Reports how much of it was meat.</summary>
25	        public double Take(double amount, out double meat)
26	        {
27	            double taken = 0;
28	            meat = TakeFrom(ref Meat, amount);
29	            taken += meat;
30	            taken += TakeFrom(ref Plants, amount - taken);
31	            taken += TakeFrom(ref Stored, amount - taken);
32	            return taken;
33	        }
34	
35	        static double TakeFrom(ref double pool, double want)
36	        {
37	            double t = Math.Min(pool, Math.Max(0, want));
38	            pool -= t;
39	            return t;
40	        }
41	
42	        /// <summary>Meat rots in days unless it's freezing; greens and roots in about a week; nuts and grain keep.</summary>
43	        public void DailySpoil(double temperatureC)
