            && Between(a, 16, a.Sex == Sex.Female ? 45 : 60) && Between(b, 16, b.Sex == Sex.Female ? 45 : 60);

        /// <summary>A pair forms when the fondness is mutual, nudged by what the band finds attractive.</summary>
