using System;
using System.Collections.Generic;
using System.Linq;
using Anthro.Sim.People;

namespace Anthro.Sim.Activities
{
    /// <summary>
    /// Picks what a person does next. Each option scores
    ///   need it meets × expected result + interest + trait pulls + social pull, plus a little noise,
    /// and the highest wins. Adding noise before taking the max is a softmax in disguise.
    /// </summary>
    public static class Decider
    {
        public static Activity Choose(Simulation sim, Person p)
        {
            var clock = sim.Clock;
            int hour = clock.Hour;
            double age = p.AgeYears(clock);

            if (clock.IsNight)
            {
                int until = hour >= 21 ? 24 - hour + 6 : 6 - hour;
                return new Sleep(p, Math.Max(1, until));
            }
            if (age < 3) return new Play(p);

            var band = sim.Band;
            int people = Math.Max(1, band.Members.Count);
            double foodDays = band.Food.Total / (people * 0.9);
            double hunger = Inheritance.Clamp01(1 - foodDays / 6);
            bool earlyDay = hour >= 6 && hour <= 13;
            // Work for food scales with need: with days of food in hand, people mostly rest and talk.
            double drive = 0.25 + hunger * 1.5;
            bool partyOut = band.Members.Any(o => o.Current is Hunt h && !h.Party.IsDone);
            double meatDays = band.Food.Meat / (people * 0.9);
            var options = new List<(double score, Func<Activity> make)>();

            options.Add((p.Fatigue * 1.5 + (1 - p.Health) + p.Injury + p.Sickness * 3 + 0.05, () => new Rest(p)));
            options.Add((0.2 + p.M(MindTrait.Sociability) * 0.5 + (hour >= 17 ? 0.7 : 0), () => new Socialize(p)));

            if (age < 12) options.Add((1.0, () => new Play(p)));

            if (age >= 6 && earlyDay)
            {
                double expect = p.Expect.Get(Verb.Forage, Forage.FallbackPerHour) / Forage.FallbackPerHour;
                options.Add((drive * (0.6 + expect * 0.3 + p.I(Interest.Plants) * 0.4 + p.M(MindTrait.Patience) * 0.1),
                    () => new Forage(p)));
            }

            if (earlyDay && HuntParty.CanHunt(sim, p))
            {
                double expect = p.Expect.Get(Verb.Hunt, HuntParty.FallbackPerHour) / HuntParty.FallbackPerHour;
                double busyWithBaby = p.DueDay >= 0 || p.Children.Any(c => c.Alive && c.AgeYears(clock) < 2) && p.Sex == Sex.Female ? 0.6 : 0;
                options.Add((drive * (0.4 + expect * 0.3 + p.M(MindTrait.Boldness) * 0.4 + p.I(Interest.Animals) * 0.4
                             + p.B(BodyTrait.Strength) * 0.2) - busyWithBaby - (partyOut ? 0.4 : 0) - (meatDays > 1.5 ? 0.6 : 0),
                    () => new Hunt(p, new HuntParty(p))));
            }

            if (age >= 12)
            {
                int adults = Math.Max(1, band.Adults(clock).Count());
                double toolNeed = Inheritance.Clamp01(1 - band.Materials.Tools / (adults * 1.5));
                if (band.Materials.Flint > 0)
                    options.Add((toolNeed * 1.3 + p.I(Interest.StoneEarth) * 0.4 + p.S(Skill.Knapping) * 0.2, () => new Knap(p)));
                else if (earlyDay && toolNeed > 0.3)
                    options.Add((0.6 + toolNeed * 0.6 + p.I(Interest.StoneEarth) * 0.3, () => new GatherFlint(p)));
            }

            var child = p.Children.Where(c => c.Alive && c.AgeYears(clock) < 4).OrderBy(c => c.AgeYears(clock)).FirstOrDefault();
            if (child != null && child.CareToday < 6)
                options.Add((0.5 + p.M(MindTrait.Warmth) * 0.6 + (6 - child.CareToday) / 6 * 0.6, () => new Care(p, child)));

            if (age >= 10 && p.Sickness < 0.2)
            {
                var sick = band.Members.Where(o => o != p && o.Sickness > 0.25 && o.CareToday < 4)
                    .OrderByDescending(o => p.GetAffinity(o) + o.Sickness).FirstOrDefault();
                if (sick != null)
                    options.Add((p.M(MindTrait.Warmth) * 0.8 + p.S(Skill.Caring) * 0.3 + p.GetAffinity(sick) * 0.6 + sick.Sickness * 0.5,
                        () => new Care(p, sick)));
            }

            if (age >= 5 && age < 16)
            {
                var teacher = band.Members.Where(o => o != p && o.Current is Knap || o != p && o.Current is Care)
                    .OrderByDescending(o => p.GetAffinity(o)).FirstOrDefault();
                if (teacher != null)
                {
                    var (skill, interest) = teacher.Current is Knap ? (Skill.Knapping, Interest.StoneEarth) : (Skill.Caring, Interest.People);
                    options.Add((0.5 + p.M(MindTrait.Curiosity) * 0.6, () => new WatchAndLearn(p, teacher, skill, interest)));
                }
            }

            var best = options.Select(o => (score: o.score + sim.Rng.Normal(0, 0.15), o.make)).OrderByDescending(o => o.score).First();
            return best.make();
        }
    }
}

