        /// anything that's gone wrong today) and their tiredness. Darkness ends any hunt.
        /// </summary>
        bool KeepGoing(Simulation sim, List<Person> alive, double hope)
        {
            if (sim.Clock.Hour >= 19 || Target == null || Target.Gone) return false;
            double go = 0, stop = 0;
