        double Influence(Person m) => 0.5 + m.M(MindTrait.Charisma) + m.Prestige * 0.3 + m.S(Skill.Hunting) * 0.5 + (m == Leader ? 0.5 : 0);

        /// <summary>How readily someone goes along with the leader against their own judgment.</summary>
        double Deference(Person m) =>
            m.GetAffinity(Leader) * (0.5 + Leader.M(MindTrait.Charisma)) + m.M(MindTrait.Sociability) * 0.3 + (1 - m.M(MindTrait.Temper)) * 0.2;

        double FearOf(Person m, Species sp) =>
            m.Expect.Get(Expectations.Danger(sp.Name), InstinctiveDanger(sp)) * (1.3 - m.M(MindTrait.Boldness)) * (1.2 - m.M(MindTrait.Resilience) * 0.4);

