            var sp = Target.Species;
            var weapon = Weapon!;
            double toolFactor = sim.Band.Materials.Tools >= alive.Count ? 1 : 0.7;
            sim.Band.Materials.Tools = Math.Max(0, sim.Band.Materials.Tools - 0.2 * alive.Count);

