        {
            Current = Phase.Back;
            _left = Math.Max(1, _travel);
        }

        void Finish(Simulation sim, List<Person> alive)
        {
            Current = Phase.Done;
            var band = sim.Band;
            if (_killed != null)
            {
                band.Food.AddMeat(_rations);
