cut('Simulation.cs', "        /// <summary>A pair forms when the fondness is mutual", "        /// <summary>How attractive the band's culture finds this person.</summary>", '''        /// <summary>
        /// Two people pair. If they come from different bands, whoever is less tied to their own
        /// people moves.
        /// </summary>
        public void Pair(Person a, Person b)
        {
            a.Partner = b; b.Partner = a;
            a.AddAffinity(b, 0.3); b.AddAffinity(a, 0.3);
            bool aHere = Band.Members.Contains(a), bHere = Band.Members.Contains(b);
            if (aHere && bHere)
            {
                Chronicle.Write(Clock, Importance.Detail, $"{a.Name} and {b.Name} paired.");
                return;
            }
            var local = aHere ? a : b;
            var visitor = aHere ? b : a;
            var home = Neighbors.First(n => n.People.Contains(visitor));
            double localTies = Band.Members.Where(o => o != local).Sum(o => local.GetAffinity(o));
            double visitorTies = home.People.Where(o => o != visitor).Sum(o => visitor.GetAffinity(o));
            if (visitorTies <= localTies)
            {
                home.People.Remove(visitor);
                visitor.X = Band.CampX; visitor.Y = Band.CampY;
                Band.Members.Add(visitor);
                Chronicle.Write(Clock, Importance.Notable, $"{visitor.Name} of the {home.Name} band paired with {local.Name} and joined the band.");
            }
            else
            {
                Band.Members.Remove(local);
                Band.Departed.Add(local);
                local.Current = null;
                home.People.Add(local);
                Chronicle.Write(Clock, Importance.Notable, $"{local.Name} paired with {visitor.Name} and left to live with the {home.Name} band.");
            }
        }

        // ---- Neighbors -------------------------------------------------------------------------

        /// <summary>The valley sits in the middle of a region three times its width.</summary>
        double RegionMin => -World.Size;
        double RegionMax => World.Size * 2;

        NeighborBand NewNeighborBand()
        {
            var n = new NeighborBand { Name = _names.Next(Rng) };
            n.X = Rng.Range(RegionMin, RegionMax); n.Y = Rng.Range(RegionMin, RegionMax);
            n.TargetX = n.X; n.TargetY = n.Y;
            int size = Rng.Range(18, 30);
            for (int i = 0; i < size; i++) n.People.Add(MakeStranger(Rng.Range(0, 60), Rng.Chance(0.5) ? Sex.Female : Sex.Male));
            return n;
        }

        /// <summary>
        /// Neighbors wander the region. When their wandering brings them near the camp they visit;
        /// they stay longer the friendlier the two bands are.
        /// </summary>
        void MoveNeighbors()
        {
            foreach (var n in Neighbors)
            {
                double friendliness = n.Visiting
                    ? n.People.Average(v => Band.Members.Count == 0 ? 0 : Band.Members.Max(m => v.GetAffinity(m)))
                    : 0;
                bool restless = WorldMap.Distance(n.X, n.Y, n.TargetX, n.TargetY) < 2 && Rng.Chance(n.Visiting ? 0.12 - friendliness * 0.1 : 0.2);
                if (restless || Rng.Chance(0.01))
                {
                    n.TargetX = Rng.Range(RegionMin, RegionMax);
                    n.TargetY = Rng.Range(RegionMin, RegionMax);
                }
                double dx = n.TargetX - n.X, dy = n.TargetY - n.Y, d = Math.Sqrt(dx * dx + dy * dy);
                if (d > 0.01) { double step = Math.Min(4, d) / d; n.X += dx * step; n.Y += dy * step; }

                double toCamp = WorldMap.Distance(n.X, n.Y, Band.CampX, Band.CampY);
                if (!n.Visiting && toCamp < 10)
                {
                    n.Visiting = true;
                    n.TargetX = n.X; n.TargetY = n.Y;
                    Chronicle.Write(Clock, Importance.Notable, $"The {n.Name} band made camp nearby.");
                }
                else if (n.Visiting && toCamp > 14)
                {
                    n.Visiting = false;
                    Chronicle.Write(Clock, Importance.Detail, $"The {n.Name} band moved on.");
                }
            }
            if (Clock.DayOfYear == 0) RenewNeighbors();
        }

        /// <summary>
        /// Neighbors' lives aren't simulated yet: each year their elders pass and their children
        /// come of age, keeping the band's size and age spread.
        /// </summary>
        void RenewNeighbors()
        {
            foreach (var n in Neighbors)
            {
                n.People.RemoveAll(p => p.AgeYears(Clock) > 65);
                while (n.People.Count < 22) n.People.Add(MakeStranger(Rng.Range(10, 16), Rng.Chance(0.5) ? Sex.Female : Sex.Male));
            }
        }

        // ---- Moving camp -----------------------------------------------------------------------

        /// <summary>How attached people are to the current camp. Grows with time spent there.</summary>
        double Attachment => Math.Min(1, (Clock.Day - _campSince) / 180.0) * 0.25;

        /// <summary>
        /// Someone who remembers a better place than what they've been finding lately may propose
        /// moving there. Each adult weighs it: their own memory of the place if they have one,
        /// otherwise how much they trust whoever proposed it. Influence decides.
        /// </summary>
        public void ConsiderMoving(Person proposer)
        {
            if (proposer.AgeYears(Clock) < 18 || proposer.Places.Count == 0) return;
            double local = proposer.Expect.Get(Verb.Forage, Forage.FallbackPerHour);
            int bestKey = -1; double bestValue = 0;
            foreach (var kv in proposer.Places)
            {
                int x = kv.Key / 1000, y = kv.Key % 1000;
                double d = WorldMap.Distance(x, y, Band.CampX, Band.CampY);
                if (d < 6) continue;
                double v = kv.Value - d * 0.004;
                if (v > bestValue) { bestValue = v; bestKey = kv.Key; }
            }
            if (bestKey < 0 || bestValue <= local * (1.4 + Attachment)) return;

            double yes = 0, no = 0;
            foreach (var a in Band.Members.Where(m => m.AgeYears(Clock) >= 16))
            {
                double mine = a.Expect.Get(Verb.Forage, Forage.FallbackPerHour);
                double trust = a == proposer ? 1 : Inheritance.Clamp01(a.GetAffinity(proposer) * (0.5 + proposer.M(MindTrait.Charisma)));
                double theirs = a.Places.TryGetValue(bestKey, out var known) ? known : mine + (bestValue - mine) * trust;
                double weight = 0.5 + a.M(MindTrait.Charisma) + a.Prestige * 0.3 + a.AgeYears(Clock) / 60;
                if (theirs > mine * (1.2 + Attachment)) yes += weight; else no += weight;
            }
            if (yes <= no) return;

            int tx = bestKey / 1000, ty = bestKey % 1000;
            double dx = tx - Band.CampX, dy = ty - Band.CampY;
            string dir = Math.Abs(dx) > Math.Abs(dy) ? (dx > 0 ? "east" : "west") : (dy > 0 ? "south" : "north");
            Band.CampX = tx; Band.CampY = ty;
            _campSince = Clock.Day;
            RefreshForagePatches();
            Chronicle.Write(Clock, Importance.Notable, $"On {proposer.Name}'s urging, the band moved camp {dir}, to the {World[tx, ty].Terrain.ToString().ToLower()}.");
        }

''')
