patch('Simulation.cs', [
 # Ties: only a person's closest bonds matter.
 ("""        /// <summary>
        /// What someone would lose by leaving a group: their bonds there, with their own children
        /// counting most, then other close kin, then friends.
        /// </summary>
        static double Ties(Person p, IEnumerable<Person> group)
        {
            double t = 0;
            foreach (var o in group)
            {
                if (o == p) continue;
                double weight = p.Children.Contains(o) ? 3 : p.IsKin(o) ? 2 : 1;
                t += p.GetAffinity(o) * weight;
            }
            return t;
        }""",
  """        /// <summary>
        /// What someone would lose by leaving a group: their closest bonds there (a person's circle
        /// is a handful of people, not the whole band), with their own children counting most,
        /// then other close kin, then friends.
        /// </summary>
        static double Ties(Person p, IEnumerable<Person> group)
        {
            var bonds = new List<double>();
            foreach (var o in group)
            {
                if (o == p) continue;
                double weight = p.Children.Contains(o) && o.Alive ? 3 : p.IsKin(o) ? 2 : 1;
                double b = p.GetAffinity(o) * weight;
                if (b > 0) bonds.Add(b);
            }
            bonds.Sort();
            double t = 0;
            for (int i = bonds.Count - 1, k = 0; i >= 0 && k < 8; i--, k++) t += bonds[i];
            return t;
        }

        /// <summary>How well-off the band looks: people notice hunger.</summary>
        double Prospects => Band.Members.Count == 0 ? 0 : Band.Members.Average(m => m.Satiety);"""),
 # Prospects enter the residence decision.
 ("""            double visitorCost = Ties(visitor, home.People) - Ties(visitor, Band.Members) * 0.5 - residence;
            double localCost = Ties(local, Band.Members) - Ties(local, home.People) * 0.5 + residence;""",
  """            // Neighbors' hunger isn't simulated yet; people assume they're doing about as well as most.
            double theirProspects = 0.8, ourProspects = Prospects;
            double visitorCost = Ties(visitor, home.People) - Ties(visitor, Band.Members) * 0.5 - residence - (ourProspects - theirProspects) * 4;
            double localCost = Ties(local, Band.Members) - Ties(local, home.People) * 0.5 + residence - (theirProspects - ourProspects) * 4;"""),
 # Splitting: after a camp-move idea fails, a hungry, restless person may propose leaving altogether.
 ("""            if (yes <= no) return;

            var (tx, ty) = Person.FromPlaceKey(bestKey);""",
  """            if (yes <= no) { ConsiderSplitting(proposer); return; }

            var (tx, ty) = Person.FromPlaceKey(bestKey);"""),
 ("""        bool Between(Person p, double min, double max)""",
  """        /// <summary>
        /// When a band is hungry and the land nearby is worked out, someone restless may propose
        /// leaving to find new land. Starting from their own family, the people closest to them
        /// each weigh relief from hunger against the bonds they'd leave behind; children go with
        /// their parents. A small group can't make it alone and people know it, so it only happens
        /// if enough agree. Those who leave become a neighboring band.
        /// </summary>
        void ConsiderSplitting(Person proposer)
        {
            double hunger = 1 - Prospects;
            if (hunger < 0.25 || proposer.AgeYears(Clock) < 20) return;

            var going = new HashSet<Person> { proposer };
            void AddFamily(Person p)
            {
                if (p.Partner != null && Band.Members.Contains(p.Partner)) going.Add(p.Partner);
                foreach (var c in p.Children) if (c.Alive && Band.Members.Contains(c) && c.AgeYears(Clock) < 14) going.Add(c);
            }
            AddFamily(proposer);

            var candidates = Band.Members.Where(m => !going.Contains(m) && m.AgeYears(Clock) >= 14)
                .OrderByDescending(m => going.Max(g => m.GetAffinity(g))).ToList();
            foreach (var m in candidates)
            {
                var staying = Band.Members.Where(o => !going.Contains(o));
                double relief = hunger * 6 * (0.5 + m.M(MindTrait.Boldness));
                if (relief + Ties(m, going) > Ties(m, staying))
                {
                    going.Add(m);
                    AddFamily(m);
                }
            }
            if (going.Count < 12 || Band.Members.Count - going.Count < 12) return;

            var band = new NeighborBand { Name = _names.Next(Rng) };
            band.X = Band.CampX; band.Y = Band.CampY;
            band.TargetX = Rng.Chance(0.5) ? RegionMin : RegionMax;
            band.TargetY = Rng.Range(RegionMin, RegionMax);
            foreach (var p in going)
            {
                Band.Members.Remove(p);
                Band.Departed.Add(p);
                p.Current = null;
                band.People.Add(p);
            }
            Neighbors.Add(band);
            Chronicle.Write(Clock, Importance.Major,
                $"Hunger split the band: {proposer.Name} led {going.Count} people away to find new land. They call themselves the {band.Name}.");
        }

        bool Between(Person p, double min, double max)"""),
])
print('ok')

