            double want = Math.Max(0, 1.0 - P.Stomach) * need;
            double perHead = food.Total / Math.Max(1, sim.Band.Members.Count);
            double restraint = 2.2 - P.Expect.Get(Expectations.Norm("sharing"), 0.6) - P.M(MindTrait.Warmth) * 0.4;
