# Rotten meat exposure is per person now.
s = s.replace("        double _rottenMeatToday;\n", "")
s = s.replace("            _rottenMeatToday = 0;\n", "            foreach (var p in Band.Members) p.AteRotten = false;\n")
s = s.replace("            double meat = _rottenMeatToday * 0.05;", "            double meat = p.AteRotten ? 0.05 : 0;")
s = s.replace("            Band.Food.AddMeat(30); Band.Food.Plants = 20;", "            Band.Food.AddMeat(30); Band.Food.Plants = 20; Band.Food.Stored = 20;")
