# 1. Lactation is buffered by the mother's body.
patch('Simulation.cs', [
 ("""                double milk = nurse?.Satiety ?? 0;""",
  """                // A nursing mother keeps her milk up by drawing on her own body; it only fails when she's badly starved.
                double milk = nurse == null ? 0 : Math.Min(1, nurse.Satiety / 0.4);"""),
])

# 2. Parents feed their young children first.
patch('Activities/CampActivities.cs', [
 ("""            double eaten = food.Take(take, out double meat);
            if (meat > 0 && food.MeatAge > 3) P.AteRotten = true;
            P.Stomach += eaten / need;
        }""",
  """            // A parent feeds their hungry small children before themselves.
            foreach (var child in P.Children)
            {
                if (!child.Alive || child.AgeYears(sim.Clock) < 1 || child.AgeYears(sim.Clock) >= 6 || child.Stomach >= 0.6) continue;
                if (!sim.Band.Members.Contains(child)) continue;
                double childNeed = sim.DailyNeed(child);
                double gave = food.Take(Math.Max(0, 1.0 - child.Stomach) * childNeed, out double childMeat);
                if (childMeat > 0 && food.MeatAge > 3) child.AteRotten = true;
                child.Stomach += gave / childNeed;
            }
            double eaten = food.Take(take, out double meat);
            if (meat > 0 && food.MeatAge > 3) P.AteRotten = true;
            P.Stomach += eaten / need;
        }"""),
])

# 3. Cold: huddling with family, direct harm only when severe, and cold weakens immunity.
