patch('People/Person.cs', [
 ("""        /// <summary>Nourishment: how much of the last couple of days they've had food in them (0 to 1).</summary>
        public double Satiety = 1;""",
  """        /// <summary>Body reserves (fat), in days of this person's own need. Built up when food is plentiful, burned when it isn't.</summary>
        public double Reserve = 4;
        /// <summary>Nourishment (0 to 1): about three days of reserves or more is fully nourished.</summary>
        public double Satiety = 1;"""),
])

patch('Simulation.cs', [
 ("""            p.Stomach = Math.Max(0, p.Stomach - effort / 24);
            double fed = p.Stomach > 0.05 ? 1 : 0;
            if (age < 2)
            {""",
  """            // Burn from the stomach first, then from the body's reserves.
            double burn = effort / 24;
            double fromStomach = Math.Min(p.Stomach, burn);
            p.Stomach -= fromStomach;
            p.Reserve = Math.Max(0, p.Reserve - (burn - fromStomach));
            // A well-filled stomach slowly lays down reserves, up to what this body can carry.
            double maxReserve = 5 + 4 * p.B(BodyTrait.Build);
            if (p.Stomach > 0.5 && p.Reserve < maxReserve)
            {
                double store = Math.Min(0.02, p.Stomach - 0.5);
                p.Stomach -= store;
                p.Reserve += store;
            }
            if (age >= 2)
            {
                p.Satiety = Math.Min(1, p.Reserve / 3);
                return;
            }
            double fed;
            {"""),
])

