            // With plenty in camp, people eat more and put on reserves against lean times.
            if (food.Total / Math.Max(1, sim.Band.Members.Count) > 3 * need) want *= 1.5;"""),
])
s = open('Activities/Decider.cs', encoding='utf-8').read()
s = s.replace("""            if (band.Food.Total > 0.05) options.Add(new Option(Verb.Eat, (0.6 - p.Stomach) * 4, () => new Eat(p)));""",
"""            // Hunger is the belly and, more slowly, the body's reserves running down.
            if (band.Food.Total > 0.05) options.Add(new Option(Verb.Eat, (0.6 - p.Stomach) * 4 + (1 - p.Satiety) * 1.5, () => new Eat(p)));""")
open('Activities/Decider.cs', 'w', encoding='utf-8').write(s)
print('ok')

