2	using System.Collections.Generic;
3	
4	namespace Anthro.Sim.World
5	{
6	    public sealed class WorldMap
7	    {
8	        /// <summary>
9	        /// Real-world size of one cell. The map is a band's real home range (~20 km across) at real
10	        /// densities of plants and animals; cells are just how finely the ecology is tracked.
11	        /// </summary>
12	        public const double CellMeters = 200;
13	
14	        /// <summary>A real distance expressed in cells. Every range in the sim is written in meters through this.</summary>
15	        public static double Cells(double meters) => meters / CellMeters;
16	
17	        public readonly int Size;
18	        public readonly Cell[,] Cells;
19	        public readonly Climate Climate = new Climate();
20	
21	        public WorldMap(int size)
22	        {
23	            Size = size;
24	            Cells = new Cell[size, size];

