1	using System;
2	using System.Collections.Generic;
3	using System.Linq;
4	using Anthro.Sim.Core;
5	using Anthro.Sim.People;
6	
7	namespace Anthro.Sim.Activities
8	{
9	    public readonly struct Option
10	    {
11	        public readonly Verb Verb;
12	        public readonly double Score;
13	        public readonly Func<Activity> Make;
14	
15	        public Option(Verb verb, double score, Func<Activity> make) { Verb = verb; Score = score; Make = make; }
16	    }
17	
18	    /// <summary>
19	    /// What a person could do right now, and how much each pulls on them:
20	    ///   need it meets × expected result + interest + trait pulls + social pull.
21	    /// The same scores answer "what would I rather be doing?" when someone asks them to join a hunt.
22	    /// </summary>
23	    public static class Decider
24	    {
25	        public static Activity Choose(Simulation sim, Person p)
26	        {
27	            var clock = sim.Clock;
28	            if (clock.IsNight)
29	            {
30	                int hour = clock.Hour;
31	                return new Sleep(p, Math.Max(1, hour >= 21 ? 24 - hour + 6 : 6 - hour));
32	            }
33	            double age = p.AgeYears(clock);
34	            if (age < 3)
35	                return age >= 1 && p.Stomach < 0.4 && sim.Band.Food.Total > 0 ? new Eat(p) : (Activity)new Play(p);
36	
37	            // Noise before taking the max: a softmax in disguise, so people aren't perfectly predictable.
38	            return Options(sim, p).Select(o => (score: o.Score + sim.Rng.Normal(0, 0.15), o.Make))
39	                .OrderByDescending(o => o.score).First().Make();
40	        }
41	
42	        /// <summary>The strongest pull other than <paramref name="except"/>: what this person gives up to do it.</summary>
43	        public static double BestAlternative(Simulation sim, Person p, Verb except)
44	        {
45	            var others = Options(sim, p).Where(o => o.Verb != except).ToList();
46	            return others.Count == 0 ? 0 : others.Max(o => o.Score);
47	        }
48	
49	        public static double ScoreOf(Simulation sim, Person p, Verb verb)
50	        {
51	            foreach (var o in Options(sim, p)) if (o.Verb == verb) return o.Score;
52	            return double.NegativeInfinity;
53	        }
54	
55	        /// <summary>
56	        /// How strongly someone feels the need to put food by for winter: how lean they remember
57	        /// winters being, how patient they are, and how far short of enough the camp's keeping-food is.
58	        /// Only felt as winter approaches.
59	        /// </summary>
60	        public static double Foresight(Simulation sim, Person p)
61	        {
62	            var season = sim.Clock.Season;
63	            if (season != Season.Autumn && !(season == Season.Summer && sim.Clock.DayOfSeason > 45)) return 0;
64	            double lean = p.Expect.Get("lean:winter", 0.2);
65	            int people = Math.Max(1, sim.Band.Members.Count);
66	            // Enough keeping-food for as much of a winter as they expect to go hungry.
67	            double enough = people * 0.9 * SimClock.DaysPerSeason * lean;
68	            double shortfall = enough <= 0 ? 0 : Inheritance.Clamp01(1 - sim.Band.Food.Stored / enough);
69	            return lean * (0.5 + p.M(MindTrait.Patience) * 0.5) * shortfall;
70	        }
71	
72	        public static List<Option> Options(Simulation sim, Person p)
73	        {
74	            var clock = sim.Clock;
75	            int hour = clock.Hour;
76	            double age = p.AgeYears(clock);
77	            var band = sim.Band;
78	            int people = Math.Max(1, band.Members.Count);
79	
80	            // Need: how many days the camp's food would last, and meat on its own (it rots, and people crave it).
81	            // Hunger is felt three ways: the camp's food running low, an empty belly, and the body thinning.
82	            double hunger = Math.Max(Inheritance.Clamp01(1 - band.Food.Total / (people * 0.9) / 6),
83	                            Math.Max(1 - p.Satiety, Inheritance.Clamp01((0.5 - p.Stomach) * 2) * 0.6));
84	            double meatHunger = Inheritance.Clamp01(1 - band.Food.Meat / (people * 0.9) / 3);
85	            bool daylightAhead = hour >= 6 && hour <= 13;
86	            var options = new List<Option>();
87	
88	            options.Add(new Option(Verb.Rest, p.Fatigue * 1.5 + (1 - p.Health) + p.Injury + p.Sickness * 3 + 0.05, () => new Rest(p)));
89	            // Hunger is the belly and, more slowly, the body's reserves running down.
90	            if (band.Food.Total > 0.05) options.Add(new Option(Verb.Eat, (0.6 - p.Stomach) * 4 + (1 - p.Satiety) * 1.5, () => new Eat(p)));
91	            // Hungry people don't sit around talking.
92	            options.Add(new Option(Verb.Socialize, (0.2 + p.M(MindTrait.Sociability) * 0.5 + (hour >= 17 ? 0.7 : 0)) * (1 - hunger * 0.7), () => new Socialize(p)));
93	
94	            if (age < 12) options.Add(new Option(Verb.Play, 1.0, () => new Play(p)));
95	
96	            // Food work is weighed the way real foragers weigh it: by the food an hour of it has
97	            // actually been bringing in (learned), scaled by need, with interest, nerve and the hope
98	            // of standing as smaller pulls.
99	            const double Reference = 0.4;
100	            if (age >= 6 && daylightAhead)
101	            {
102	                double drive = 0.25 + hunger * 1.5 + Foresight(sim, p) * 1.2;
103	                double yield = p.Expect.Get(Verb.Forage, Forage.FallbackPerHour) / Reference;
104	                options.Add(new Option(Verb.Forage, drive * yield * (0.7 + p.I(Interest.Plants) * 0.3 + p.M(MindTrait.Patience) * 0.1),
105	                    () => new Forage(p)));
106	            }
107	
108	            if (daylightAhead && HuntParty.CanHunt(sim, p))
109	            {
110	                double drive = 0.25 + Math.Max(hunger, meatHunger * 0.7) * 1.5;
111	                double yield = Math.Max(0, p.Expect.Get(Verb.Hunt, HuntParty.FallbackPerHour)) / Reference;
112	                double standing = p.M(MindTrait.Boldness) * p.Expect.Get(Expectations.Norm("valor"), 0.5) * 0.4;
113	                // Late pregnancy and nursing make a long, rough day away from camp costly.
114	                double tied = p.DueDay >= 0 || p.Sex == Sex.Female && p.Children.Any(c => c.Alive && c.AgeYears(clock) < 2) ? 0.6 : 0;
115	                options.Add(new Option(Verb.Hunt, drive * yield * (0.7 + p.I(Interest.Animals) * 0.3 + p.B(BodyTrait.Strength) * 0.1) + standing - tied,
116	                    () => new Hunt(p, new HuntParty(p))));
117	            }
118	
119	            if (age >= 12)
120	            {
121	                int adults = Math.Max(1, band.Adults(clock).Count());
122	                double toolNeed = Inheritance.Clamp01(1 - band.Materials.Tools / (adults * 1.5));
123	                if (band.Materials.Flint > 0)
124	                    options.Add(new Option(Verb.Knap, toolNeed * 1.3 + p.I(Interest.StoneEarth) * 0.4 + p.S(Skill.Knapping) * 0.2, () => new Knap(p)));
125	                else if (daylightAhead)
126	                    options.Add(new Option(Verb.GatherFlint, toolNeed * 1.2 + p.I(Interest.StoneEarth) * 0.3, () => new GatherFlint(p)));
127	            }
128	
129	            var child = p.Children.Where(c => c.Alive && c.AgeYears(clock) < 4).OrderBy(c => c.AgeYears(clock)).FirstOrDefault();
130	            if (child != null && child.CareToday < 6)
131	                options.Add(new Option(Verb.Care, 0.5 + p.M(MindTrait.Warmth) * 0.6 + (6 - child.CareToday) / 6 * 0.6, () => new Care(p, child)));
132	
133	            if (age >= 10 && p.Sickness < 0.2)
134	            {
135	                var sick = band.Members.Where(o => o != p && o.Sickness > 0.25 && o.CareToday < 4)
136	                    .OrderByDescending(o => p.GetAffinity(o) + o.Sickness).FirstOrDefault();
137	                if (sick != null && (child == null || child.CareToday >= 6))
138	                    options.Add(new Option(Verb.Care, p.M(MindTrait.Warmth) * 0.8 + p.S(Skill.Caring) * 0.3 + p.I(Interest.Healing) * 0.5 + p.GetAffinity(sick) * 0.6 + sick.Sickness * 0.5,
139	                        () => new Care(p, sick)));
140	            }
141	
142	            if (age >= 5 && age < 16)
143	            {
144	                var teacher = band.Members.Where(o => o != p && (o.Current is Knap || o.Current is Care))
145	                    .OrderByDescending(o => p.GetAffinity(o)).FirstOrDefault();
146	                if (teacher != null)
147	                {
148	                    var (skill, interest) = teacher.Current is Knap ? (Skill.Knapping, Interest.StoneEarth) : (Skill.Caring, Interest.People);
149	                    options.Add(new Option(Verb.WatchAndLearn, 0.5 + p.M(MindTrait.Curiosity) * 0.6, () => new WatchAndLearn(p, teacher, skill, interest)));
150	                }
151	            }
152	            // When people are hungry, everything that doesn't get food or keep them alive fades.
153	            for (int i = 0; i < options.Count; i++)
154	            {
155	                var o = options[i];
156	                bool essential = o.Verb == Verb.Forage || o.Verb == Verb.Hunt || o.Verb == Verb.Eat || o.Verb == Verb.Rest
157	                                 || o.Verb == Verb.Care || o.Verb == Verb.Sleep || o.Verb == Verb.Socialize;
