public sealed class Eat : TimedActivity
{
    public Eat(Person p) : base(p, 1) { Step = "eating"; }
    public override Verb Verb => Verb.Eat;
    protected override double FatiguePerHour => -0.02;

    protected override void OnHour(Simulation sim)
    {
        var food = sim.Band.Food;
        double need = sim.DailyNeed(P);
        if (need <= 0 || food.Total <= 0) return;
        double want = Math.Max(0, 1.0 - P.Stomach) * need;
        // With plenty in camp, people eat more and put on reserves against lean times.
        if (food.Total / Math.Max(1, sim.Band.Members.Count) > 3 * need) want *= 1.5;
        double perHead = food.Total / Math.Max(1, sim.Band.Members.Count);
        double restraint = 2.2 - P.Expect.Get(Expectations.Norm("sharing"), 0.6) - P.M(MindTrait.Warmth) * 0.4;
        double take = Math.Min(want, Math.Max(perHead * restraint, 0.05 * need));
        // A parent feeds their hungry children before themselves.
        foreach (var child in P.Children)
        {
            if (!child.Alive || child.AgeYears(sim.Clock) < 1 || child.AgeYears(sim.Clock) >= 14 || child.Stomach >= 0.6) continue;
            if (!sim.Band.Members.Contains(child)) continue;
            double childNeed = sim.DailyNeed(child);
            double gave = food.Take(Math.Max(0, 1.0 - child.Stomach) * childNeed, out double childMeat);
            if (childMeat > 0 && food.MeatAge > 3) child.AteRotten = true;
            child.Stomach += gave / childNeed;
        }
        double eaten = food.Take(take, out double meat);
        sim.ThisYear.Eaten += eaten;
        if (meat > 0 && food.MeatAge > 3) P.AteRotten = true;
        P.Stomach += eaten / need;
    }
}

public sealed class Rest : TimedActivity
{
    public Rest(Person p) : base(p, 2) { Step = "resting"; }
    public override Verb Verb => Verb.Rest;
    protected override double FatiguePerHour => -0.08;
    protected override void OnHour(Simulation sim) => P.Health = Inheritance.Clamp01(P.Health + 0.002);
}

