        /// <summary>
        /// When a band is hungry and the land nearby is worked out, someone restless may propose
        /// leaving to find new land. Starting from their own family, the people closest to them
        /// each weigh relief from hunger against the bonds they'd leave behind; children go with
        /// their parents. A small group can't make it alone and people know it, so it only happens
        /// if enough agree. Those who leave become a neighboring band.
        /// </summary>
        void ConsiderSplitting(Person proposer)
        {
            // People leave over a long hard stretch, not one bad week, or when the camp has grown
            // so big that most of it is near-strangers.
            double hunger = _hardship;
            double crowding = Crowding(proposer);
            if (hunger + crowding < 0.3 || proposer.AgeYears(Clock) < 20) return;
            if (Clock.Day - proposer.LastSplitProposalDay < SimClock.DaysPerSeason) return;
            proposer.LastSplitProposalDay = Clock.Day;

            var going = new HashSet<Person> { proposer };
            void AddFamily(Person p)
            {
                if (p.Partner != null && Band.Members.Contains(p.Partner)) going.Add(p.Partner);
                foreach (var c in p.Children) if (c.Alive && Band.Members.Contains(c) && c.AgeYears(Clock) < 14) going.Add(c);
            }
            AddFamily(proposer);

            var candidates = Band.Members.Where(m => !going.Contains(m) && m.AgeYears(Clock) >= 14)
                .OrderByDescending(m => going.Max(g => m.GetAffinity(g))).ToList();
            foreach (var m in candidates)
            {
                var staying = Band.Members.Where(o => !going.Contains(o));
                double relief = (hunger * 6 + Crowding(m) * 3) * (0.5 + m.M(MindTrait.Boldness));
                if (relief + Ties(m, going) > Ties(m, staying))
                {
                    going.Add(m);
                    AddFamily(m);
                }
            }
            if (going.Count < 12 || Band.Members.Count - going.Count < 12) return;

            var band = new NeighborBand { Name = _names.Next(Rng) };
            band.X = Band.CampX; band.Y = Band.CampY;
            band.TargetX = Rng.Chance(0.5) ? RegionMin : RegionMax;
            band.TargetY = Rng.Range(RegionMin, RegionMax);
            foreach (var p in going)
            {
                Band.Members.Remove(p);
                Band.Departed.Add(p);
                p.Current = null;
                band.People.Add(p);
            }
            Neighbors.Add(band);
            Chronicle.Write(Clock, Importance.Major,
                $"Hard times split the band: {proposer.Name} led {going.Count} people away to find new land. They call themselves the {band.Name}.");
        }

        bool Between(Person p, double min, double max) { var age = p.AgeYears(Clock); return age >= min && age <= max; }

        /// <summary>How attractive the band's culture finds this person.</summary>
        public double Attraction(Person p)
        {
            double s = 0;
            for (int i = 0; i < p.Mind.Length; i++) s += Band.AttractionMind[i] * (p.Mind[i] - 0.5);
            for (int i = 0; i < p.Body.Length; i++) s += Band.AttractionBody[i] * (p.Body[i] - 0.5);
            return s + p.Prestige * 0.1;
        }

