using System;
using System.Collections.Generic;
using System.Linq;
using Anthro.Sim.Activities;
using Anthro.Sim.Core;
using Anthro.Sim.People;
using Anthro.Sim.World;

namespace Anthro.Sim
{
    /// <summary>
    /// The social fabric: households that own their food, asking for food and being refused, trust
    /// and fondness that grow and fade, theft and fights when times are desperate, and bands that
    /// split along the lines of who likes and trusts whom.
    /// </summary>
    public sealed partial class Simulation
    {
        int _nextHouseholdId;

        // ---- Households ------------------------------------------------------------------------

        public Household NewHousehold(params Person[] people)
        {
            var h = new Household(_nextHouseholdId++);
            Band.Households.Add(h);
            foreach (var p in people) MoveInto(p, h);
            return h;
        }

        /// <summary>
        /// Moves someone into a household. Their own young children who lived with them come too;
        /// if they leave a hearth empty, its food comes with them.
        /// </summary>
        public void MoveInto(Person p, Household h, bool withDependents = true)
        {
            var old = p.Home;
            if (old == h) return;
            if (old != null) old.Members.Remove(p);
            h.Members.Add(p);
            p.Home = h;
            if (withDependents && old != null)
                foreach (var c in p.Children.Where(c => c.Alive && c.Home == old && c.AgeYears(Clock) < 14).ToList())
                    MoveInto(c, h, false);
            if (old != null && old.Members.Count == 0)
            {
                MoveFood(old, h);
                Band.Households.Remove(old);
            }
        }

        /// <summary>Takes someone out of their household (death or departure). Children left with no adult are taken in by others.</summary>
        void LeaveHousehold(Person p)
        {
            var h = p.Home;
            if (h == null) return;
            h.Members.Remove(p);
            p.Home = null;
            if (h.Members.Count > 0 && !h.Adults(Clock).Any())
                foreach (var orphan in h.Members.ToList()) Adopt(orphan);
            if (h.Members.Count == 0)
            {
                // The food of an emptied hearth goes to whoever was closest to its last member.
                var heir = Band.Households.Where(o => o != h)
                    .OrderByDescending(o => o.Members.Sum(m => p.GetAffinity(m))).FirstOrDefault();
                if (heir != null) MoveFood(h, heir);
                Band.Households.Remove(h);
            }
        }

        /// <summary>
        /// An orphan is taken in: by grandparents, grown siblings, aunts and uncles first, otherwise by
        /// the warm-hearted adult who's fondest of them.
        /// </summary>
        void Adopt(Person child)
        {
            double Kinship(Person a)
            {
                if (child.Mother?.Mother == a || child.Mother?.Father == a || child.Father?.Mother == a || child.Father?.Father == a) return 3;
                if (child.Mother != null && child.Mother.Children.Contains(a)) return 2.5;
                if (child.Father != null && child.Father.Children.Contains(a)) return 2.5;
                var auntsUncles = new[] { child.Mother?.Mother, child.Mother?.Father, child.Father?.Mother, child.Father?.Father }
                    .Where(g => g != null).SelectMany(g => g!.Children);
                return auntsUncles.Contains(a) ? 2 : 0;
            }
            var carer = Band.Members.Where(a => a != child && a.Home != null && a.AgeYears(Clock) >= 16)
                .OrderByDescending(a => Kinship(a) + a.GetAffinity(child) + a.M(MindTrait.Warmth) * 0.5).FirstOrDefault();
            if (carer == null) return;
            MoveInto(child, carer.Home!, false);
            carer.AddAffinity(child, 0.2);
            child.AddAffinity(carer, 0.2);
            Chronicle.Write(Clock, Importance.Detail, $"{carer.Name} took in {child.Name}.");
        }

        static void MoveFood(Household from, Household to)
        {
            to.Food.AddMeat(from.Food.Meat);
            to.Food.Plants += from.Food.Plants;
            to.Food.Stored += from.Food.Stored;
            from.Food.Meat = from.Food.Plants = from.Food.Stored = 0;
        }

        static void MoveFood(Household from, Household to, double amount, out double meat)
        {
            double taken = from.Food.Take(amount, out meat);
            to.Food.AddMeat(meat);
            to.Food.Plants += taken - meat;
        }

        /// <summary>A person's household, making one if somehow they have none.</summary>
        public Household HomeOf(Person p) => p.Home ?? NewHousehold(p);

        // ---- Bonds over time -------------------------------------------------------------------

        /// <summary>
        /// Fondness fades without time together (toward a floor that's higher for family), and trust
        /// drifts back toward no-opinion. Daily time together is what keeps bonds alive.
        /// </summary>
        void DailyBonds()
        {
            var known = new Dictionary<int, Person>();
            foreach (var m in Band.Members) known[m.Id] = m;
            foreach (var p in Band.Members)
            {
                foreach (var id in p.Affinity.Keys.ToList())
                {
                    double floor = known.TryGetValue(id, out var o) && p.IsKin(o) ? 0.4 : 0.05;
                    double v = p.Affinity[id];
                    if (v > floor) p.Affinity[id] = v - (v - floor) * 0.003;
                }
                foreach (var id in p.Trust.Keys.ToList())
                    p.Trust[id] += (0.5 - p.Trust[id]) * 0.002;
            }
        }

        /// <summary>How much of the camp this person distrusts (0 when everyone is trusted or unknown).</summary>
        double Strife(Person p)
        {
            double sum = 0; int n = 0;
            foreach (var o in Band.Members)
            {
                if (o == p || o.AgeYears(Clock) < 14) continue;
                sum += Math.Max(0, 0.5 - p.GetTrust(o)) * 2;
                n++;
            }
            return n == 0 ? 0 : sum / n;
        }

        // ---- Meat ----------------------------------------------------------------------------------

        /// <summary>
        /// A kill is shared. How much stays with the hunters' families and how much goes round the
        /// camp follows the band's sharing norm. Those who receive think better of the hunters.
        /// </summary>
        public void ShareMeat(double rations, List<Person> party, Person? killer)
        {
            if (rations <= 0 || Band.Households.Count == 0) return;
            var adults = Band.Members.Where(m => m.AgeYears(Clock) >= 16).ToList();
            double sharing = adults.Count == 0 ? 0.6 : adults.Average(m => m.Expect.Get(Expectations.Norm("sharing"), 0.6));
            double kept = rations * (1 - sharing) * 0.6;

            var hunterHomes = party.Where(m => m.Alive && Band.Members.Contains(m)).Select(m => (home: HomeOf(m), weight: m == killer ? 2.0 : 1.0)).ToList();
            double totalWeight = hunterHomes.Sum(h => h.weight);
            foreach (var (home, weight) in hunterHomes) home.Food.AddMeat(totalWeight <= 0 ? 0 : kept * weight / totalWeight);

            double rest = rations - (totalWeight > 0 ? kept : 0);
            int mouths = Band.Households.Sum(h => h.Members.Count);
            foreach (var h in Band.Households)
            {
                h.Food.AddMeat(mouths <= 0 ? 0 : rest * h.Members.Count / mouths);
                if (killer == null || h.Members.Any(m => party.Contains(m))) continue;
                foreach (var a in h.Adults(Clock))
                {
                    a.AddTrust(killer, 0.02);
                    a.AddAffinity(killer, 0.01);
                }
            }
        }

        /// <summary>A hunt that comes back empty while the band is going hungry dents trust in whoever led it.</summary>
        public void BlameFailedHunt(Person leader, List<Person> party)
        {
            if (_hardship < 0.2) return;
            foreach (var a in Band.Members)
                if (!party.Contains(a) && a.AgeYears(Clock) >= 16) a.AddTrust(leader, -0.03 * _hardship);
        }

        // ---- Asking for food ---------------------------------------------------------------------

        static bool AtCamp(Person p) => !(p.Current is Forage || p.Current is Hunt || p.Current is GatherFlint);

        /// <summary>
        /// A hungry person whose household is short asks another household. The one asked weighs it by
        /// their warmth, the band's sharing norm, how fond of and how trusting they are of the asker,
        /// kinship, and how much their own family can spare. Giving builds trust; refusing breeds resentment.
        /// Returns how much food came into the asker's household.
        /// </summary>
        public double AskForFood(Person asker, double amount)
        {
            var home = HomeOf(asker);
            var options = Band.Households
                .Where(h => h != home && h.Food.Total > 0.5 && h.DaysOfFood > home.DaysOfFood + 0.5)
                .Select(h => (h, giver: h.Adults(Clock).Where(AtCamp).OrderByDescending(a => a.M(MindTrait.Warmth)).FirstOrDefault()))
                .Where(x => x.giver != null)
                .OrderByDescending(x => (asker.IsKin(x.giver!) ? 1 : 0) + asker.GetAffinity(x.giver!) + asker.GetTrust(x.giver!))
                .Take(2)
                .ToList();

            foreach (var (h, giverOrNull) in options)
            {
                var giver = giverOrNull!;
                double scarcity = Inheritance.Clamp01(1 - h.DaysOfFood / 4) * 0.8;
                double willing = giver.Expect.Get(Expectations.Norm("sharing"), 0.6) * 0.5 + giver.M(MindTrait.Warmth) * 0.4
                                 + giver.GetAffinity(asker) * 0.4 + giver.GetTrust(asker) * 0.3 + (giver.IsKin(asker) ? 0.4 : 0) - scarcity
                                 + Rng.Normal(0, 0.1);
                double spare = Math.Max(0, h.Food.Total - h.Members.Count * 0.9);
                double give = Math.Min(spare, amount * Inheritance.Clamp01(willing));
                if (give > 0.05)
                {
                    MoveFood(h, home, give, out _);
                    asker.AddTrust(giver, 0.04);
                    asker.AddAffinity(giver, 0.02);
                    giver.AddAffinity(asker, 0.01);
                    ThisYear.Shared += give;
                    return give;
                }
                asker.AddTrust(giver, -0.04);
                asker.AddAffinity(giver, -0.02);
                ThisYear.Refusals++;
            }
            return 0;
        }

        // ---- Theft and fights ------------------------------------------------------------------

        /// <summary>
        /// Desperation, a cold heart, a band that doesn't hold sharing sacred, and nerve together may
        /// lead someone to take food from a better-off household. If anyone at camp sees it, the
        /// victims' trust and fondness collapse, the thief's standing falls, and tempers may flare.
        /// Returns how much was taken into the thief's household.
        /// </summary>
        public double ConsiderTheft(Person thief, double amount)
        {
            double desperate = 1 - Math.Min(thief.Satiety, thief.Stomach * 2);
            if (desperate < 0.4) return 0;
            double propensity = desperate * (1 - thief.M(MindTrait.Warmth)) * (1.2 - thief.Expect.Get(Expectations.Norm("sharing"), 0.6))
                                * (0.4 + thief.M(MindTrait.Boldness) * 0.6);
            if (!Rng.Chance(propensity * 0.3)) return 0;

            var home = HomeOf(thief);
            var victim = Band.Households.Where(h => h != home && h.Food.Total > 1).OrderByDescending(h => h.DaysOfFood).FirstOrDefault();
            if (victim == null) return 0;
            double took = Math.Min(amount, victim.Food.Total * 0.3);
            MoveFood(victim, home, took, out _);
            ThisYear.Thefts++;

            int witnesses = Band.Members.Count(m => m != thief && m.Home != home && m.AgeYears(Clock) >= 10 && AtCamp(m) && !(m.Current is Sleep));
            if (!Rng.Chance(1 - Math.Pow(0.85, witnesses))) return took;

            var wronged = victim.Adults(Clock).ToList();
            foreach (var a in wronged) { a.AddTrust(thief, -0.4); a.AddAffinity(thief, -0.3); }
            foreach (var a in Band.Members.Where(m => m.Home != home && !wronged.Contains(m) && m.AgeYears(Clock) >= 14)) a.AddTrust(thief, -0.1);
            thief.Prestige = Math.Max(0, thief.Prestige - 0.2);
            var face = wronged.Where(AtCamp).OrderByDescending(a => a.M(MindTrait.Temper)).FirstOrDefault();
            Chronicle.Write(Clock, Importance.Notable,
                $"{thief.Name} was caught taking food from {(face ?? wronged.FirstOrDefault())?.Name ?? "another"}'s family.");
            if (face != null && Rng.Chance(Inheritance.Clamp01((face.M(MindTrait.Temper) + thief.M(MindTrait.Temper)) / 2 - 0.25)))
                Fight(face, thief, "stolen food");
            return took;
        }

        /// <summary>
        /// A fight: strength and temper against strength and temper. The loser is hurt, sometimes
        /// badly; both come away with less fondness and trust, and the loser's family resents the winner.
        /// </summary>
        public void Fight(Person a, Person b, string over)
        {
            double Power(Person p) => p.B(BodyTrait.Strength) * (0.6 + 0.4 * p.M(MindTrait.Temper)) * p.Health + Rng.Range(0, 0.4);
            var (winner, loser) = Power(a) >= Power(b) ? (a, b) : (b, a);
            loser.Injury = Inheritance.Clamp01(loser.Injury + Rng.Range(0.1, 0.5) * (0.5 + winner.B(BodyTrait.Strength)));
            winner.Injury = Inheritance.Clamp01(winner.Injury + Rng.Range(0, 0.15));
            foreach (var (x, y) in new[] { (a, b), (b, a) }) { x.AddAffinity(y, -0.4); x.AddTrust(y, -0.2); }
            foreach (var kin in Band.Members.Where(m => m != loser && m.IsKin(loser)))
            {
                kin.AddAffinity(winner, -0.15);
                kin.AddTrust(winner, -0.1);
            }
            ThisYear.Fights++;
            if (loser.Injury >= 0.95) Kill(loser, $"killed in a fight with {winner.Name}");
            else Chronicle.Write(Clock, Importance.Notable, $"{a.Name} and {b.Name} came to blows over {over}; {loser.Name} was hurt.");
        }

        // ---- Splitting and leaving -----------------------------------------------------------------

        /// <summary>
        /// When life in the band has become hard (a long hungry stretch, a camp full of near-strangers,
        /// or a camp full of people they distrust), someone may propose leaving. Households decide
        /// whole: each weighs relief against the bonds they'd leave behind. Each adult also judges
        /// whether the leaving group is big enough for them to risk it (the bold accept smaller
        /// groups). A bold person may strike out with just their own family to join a neighboring
        /// band. Those who leave become a band of their own.
        /// </summary>
        void ConsiderSplitting(Person proposer)
        {
            double hardship = _hardship;
            double misery = hardship + Crowding(proposer) + Strife(proposer);
            if (misery < 0.3 || proposer.AgeYears(Clock) < 20 || proposer.Home == null) return;
            if (Clock.Day - proposer.LastSplitProposalDay < SimClock.DaysPerSeason) return;
            proposer.LastSplitProposalDay = Clock.Day;

            var going = new List<Household> { proposer.Home };
            IEnumerable<Person> Going() => going.SelectMany(h => h.Members);
            IEnumerable<Person> Staying() => Band.Members.Where(m => !going.Contains(m.Home!));

            foreach (var h in Band.Households.Where(h => h != proposer.Home).ToList())
            {
                var head = h.Adults(Clock).OrderByDescending(a => a.M(MindTrait.Charisma) + a.AgeYears(Clock) / 60).FirstOrDefault();
                if (head == null) continue;
                double relief = (hardship * 6 + Crowding(head) * 3 + Strife(head) * 3) * (0.5 + head.M(MindTrait.Boldness));
                if (relief + Ties(head, Going()) > Ties(head, Staying())) going.Add(h);
            }

            // Each adult's sense of how many grown people a group needs to make it on its own.
            static double Needed(Person a) => 2 + (1 - a.M(MindTrait.Boldness)) * 6;
            bool changed = true;
            while (changed)
            {
                changed = false;
                int adults = Going().Count(m => m.AgeYears(Clock) >= 16);
                foreach (var h in going.Where(h => h != proposer.Home).ToList())
                    if (h.Adults(Clock).All(a => adults < Needed(a)) && hardship < 0.6) { going.Remove(h); changed = true; }
            }

            int goingAdults = Going().Count(m => m.AgeYears(Clock) >= 16);
            int stayingAdults = Staying().Count(m => m.AgeYears(Clock) >= 16);
            if (stayingAdults < 2) return;

            if (goingAdults < Needed(proposer) && hardship < 0.6)
            {
                // Too few to go it alone. A bold enough person may instead take their family to a neighboring band.
                if (going.Count == 1 && proposer.M(MindTrait.Boldness) > 0.6 && Neighbors.Count > 0)
                {
                    var join = Neighbors.OrderBy(n => WorldMap.Distance(n.X, n.Y, Band.CampX, Band.CampY)).First();
                    var family = Going().ToList();
                    Depart(family, join);
                    Chronicle.Write(Clock, Importance.Notable, family.Count == 1
                        ? $"{proposer.Name} struck out alone to join the {join.Name} band."
                        : $"{proposer.Name} took their family of {family.Count} to join the {join.Name} band.");
                }
                return;
            }

            var band = new NeighborBand { Name = _names.Next(Rng) };
            band.X = Band.CampX; band.Y = Band.CampY;
            band.TargetX = Rng.Chance(0.5) ? RegionMin : RegionMax;
            band.TargetY = Rng.Range(RegionMin, RegionMax);
            var people = Going().ToList();
            Depart(people, band);
            Neighbors.Add(band);
            string why = Strife(proposer) > hardship && Strife(proposer) > Crowding(proposer) ? "Bad blood" : hardship >= Crowding(proposer) ? "Hard times" : "A crowded camp";
            Chronicle.Write(Clock, Importance.Major,
                $"{why} split the band: {proposer.Name} led {people.Count} people away to find new land. They call themselves the {band.Name}.");
        }

        void Depart(List<Person> people, NeighborBand to)
        {
            foreach (var p in people)
            {
                LeaveHousehold(p);
                Band.Members.Remove(p);
                if (!Band.Departed.Contains(p)) Band.Departed.Add(p);
                p.Current = null;
                to.People.Add(p);
            }
        }

        /// <summary>
        /// People who left may come back when their old band and their new one meet, if they're more
        /// bound to the people here than to those they left with. Their partner and children come too.
        /// </summary>
        void ConsiderReturns(NeighborBand n)
        {
            foreach (var p in n.People.Where(p => Band.Departed.Contains(p) && p.Alive && p.AgeYears(Clock) >= 16).ToList())
            {
                if (!n.People.Contains(p)) continue;
                var family = n.People.Where(o => o == p || o == p.Partner || (p.Children.Contains(o) && o.AgeYears(Clock) < 14)).ToList();
                double here = Ties(p, Band.Members);
                double there = Ties(p, n.People.Except(family));
                if (here <= there * 1.3 + 0.5) continue;
                foreach (var f in family)
                {
                    n.People.Remove(f);
                    Band.Departed.Remove(f);
                    f.X = Band.CampX; f.Y = Band.CampY;
                    Band.Members.Add(f);
                }
                NewHousehold(family.ToArray());
                Chronicle.Write(Clock, Importance.Notable, family.Count == 1
                    ? $"{p.Name} came back to the band."
                    : $"{p.Name} came back to the band, bringing {family.Count - 1} more.");
            }
        }
    }
}

