        /// A meal from the family's own store. If it's short, they ask another household, and if
        /// that fails and they're desperate, some will steal. Hungry children of the household are
        /// fed first: warm-hearted adults give them nearly everything if need be.
        /// </summary>
        protected override void OnHour(Simulation sim)
        {
            var home = sim.HomeOf(P);
            double need = sim.DailyNeed(P);
            if (need <= 0) return;
            double want = Math.Max(0, 1.0 - P.Stomach) * need;
            // With plenty at hand, people eat more and put on reserves against lean times.
            if (home.DaysOfFood > 3) want *= 1.5;

            var kids = home.Members.Where(c => c != P && c.AgeYears(sim.Clock) >= 1 && c.AgeYears(sim.Clock) < 14 && c.Stomach < 0.6).ToList();
            double kidsWant = kids.Sum(c => Math.Max(0, 1.0 - c.Stomach) * sim.DailyNeed(c));

