using System;
using System.Collections.Generic;
using System.Linq;
using Anthro.Sim.Core;

namespace Anthro.Sim.People
{
    /// <summary>Shared food, kept by kind because each spoils at a different rate.</summary>
    public sealed class FoodStore
    {
        public double Meat, Plants, Stored;
        /// <summary>Average age of the meat in camp, in days. Past a few days it makes people sick.</summary>
        public double MeatAge;

        public double Total => Meat + Plants + Stored;

        public void AddMeat(double rations)
        {
            if (rations <= 0) return;
            MeatAge = Meat * MeatAge / (Meat + rations);
            Meat += rations;
        }

        /// <summary>Eat what spoils first. Reports how much of it was meat.</summary>
        public double Take(double amount, out double meat)
        {
            double taken = 0;
            meat = TakeFrom(ref Meat, amount);
            taken += meat;
            taken += TakeFrom(ref Plants, amount - taken);
            taken += TakeFrom(ref Stored, amount - taken);
            return taken;
        }

        static double TakeFrom(ref double pool, double want)
        {
            double t = Math.Min(pool, Math.Max(0, want));
            pool -= t;
            return t;
        }

        /// <summary>Meat rots in days unless it's freezing; greens and roots in about a week; nuts and grain keep.</summary>
        public void DailySpoil(double temperatureC)
        {
            Meat *= temperatureC < 0 ? 0.97 : 0.8;
            MeatAge = Meat < 0.5 ? 0 : MeatAge + (temperatureC < 0 ? 0.2 : 1);
            Plants *= 0.92;
            Stored *= 0.996;
        }
    }

    public sealed class Materials
    {
        public int Hides, Sinew, Bone, Flint;
        public double Tools;
    }

    public sealed class Band
    {
        public string Name = "";
namespace Anthro.Sim.People
{
    /// <summary>
    /// How well a band keeps out the cold. Fire and windbreaks are known from the start;
    /// caves, hide clothing and tents raise protection as they're discovered.
    /// </summary>
    public static class Shelter
    {
        public static double Protection(Band band)
        {
            double p = 0;
            if (band.AnyoneKnows("fire.make")) p += 0.3;
            if (band.AnyoneKnows("shelter.brush")) p += 0.2;
            if (band.AnyoneKnows("hide.wrap")) p += 0.15;
            if (band.AnyoneKnows("shelter.cave")) p += 0.15;
            if (band.AnyoneKnows("hide.tent")) p += 0.15;
            if (band.AnyoneKnows("hide.needle")) p += 0.2;
            return p;
        }

        /// <summary>Below this temperature, people start losing health to cold.</summary>
        public static double ComfortTemp(Band band) => 5 - Protection(band) * 15;
    }
}
