        void Depart(List<Person> people, NeighborBand to)
        {
            // Households leave whole: take everyone out first so no child is briefly "orphaned".
            foreach (var p in people)
            {
                if (p.Home != null) p.Home.Members.Remove(p);
                p.Home = null;
            }
            foreach (var h in Band.Households.Where(h => h.Members.Count == 0).ToList()) Band.Households.Remove(h);
            foreach (var h in Band.Households.Where(h => h.Members.Count > 0 && !h.Adults(Clock).Any()).ToList())
                foreach (var orphan in h.Members.ToList()) Adopt(orphan);
            foreach (var p in people)
            {
                p.LeftDay = Clock.Day;
                Band.Members.Remove(p);
                if (!Band.Departed.Contains(p)) Band.Departed.Add(p);
                p.Current = null;
                to.People.Add(p);
            }
        }

        /// <summary>
        /// People who left may come back when their old band and their new one meet, if they're more
        /// bound to the people here than to those they left with. Their partner and children come too.
        /// </summary>
        void ConsiderReturns(NeighborBand n)
        {
            foreach (var p in n.People.Where(p => Band.Departed.Contains(p) && p.Alive && p.AgeYears(Clock) >= 16).ToList())
            {
                // Coming back is something people do after a while away, not the next time they meet.
                if (!n.People.Contains(p) || Clock.Day - p.LeftDay < SimClock.DaysPerYear) continue;
                var family = n.People.Where(o => o == p || o == p.Partner || (p.Children.Contains(o) && o.AgeYears(Clock) < 14)).ToList();
                double here = Ties(p, Band.Members);
                double there = Ties(p, n.People.Except(family));
                if (here <= there * 1.3 + 0.5) continue;
                foreach (var f in family)
                {
                    n.People.Remove(f);
                    Band.Departed.Remove(f);
                    f.X = Band.CampX; f.Y = Band.CampY;
                    Band.Members.Add(f);
                }
                NewHousehold(family.ToArray());
                Chronicle.Write(Clock, Importance.Notable, family.Count == 1
                    ? $"{p.Name} came back to the band."
                    : $"{p.Name} came back to the band, bringing {family.Count - 1} more.");
            }
        }
    }
}

