108	        // ---- Founding ------------------------------------------------------------------------
109	
110	        void FoundBand(int size)
111	        {
112	            Band.Name = _names.Next(Rng);
113	            for (int i = 0; i < TraitCounts.Mind; i++) Band.AttractionMind[i] = Rng.Normal(0, 0.2);
114	            for (int i = 0; i < TraitCounts.Body; i++) Band.AttractionBody[i] = Rng.Normal(0, 0.2);
115	
116	            var camp = ScoreCampSites(30).First();
117	            Band.CampX = camp.X; Band.CampY = camp.Y;
118	
119	            // A typical forager band: about a quarter couples, a few elders and young adults, the rest children.
120	            int couples = Math.Max(1, (int)Math.Round(size * 0.25));
121	            int elders = Math.Max(1, size / 10);
122	            int youths = Math.Max(1, size / 10);
123	            var parents = new List<(Person mother, Person father, double motherAge)>();
124	            for (int i = 0; i < couples; i++)
125	            {
126	                double womanAge = Rng.Range(18, 38);
127	                var woman = NewFounder(womanAge, Sex.Female);
128	                var man = NewFounder(Math.Max(16, womanAge + Rng.Range(-2, 8)), Sex.Male);
129	                woman.Partner = man; man.Partner = woman;
130	                woman.AddAffinity(man, 0.6); man.AddAffinity(woman, 0.6);
131	                NewHousehold(woman, man);
132	                parents.Add((woman, man, womanAge));
133	            }
134	            for (int i = 0; i < elders; i++) NewFounder(Rng.Range(48, 63), Rng.Chance(0.5) ? Sex.Female : Sex.Male);
135	            for (int i = 0; i < youths; i++) NewFounder(Rng.Range(14, 20), i % 2 == 0 ? Sex.Female : Sex.Male);
136	            while (Band.Members.Count < size)
137	            {
138	                var (mother, father, motherAge) = parents[Rng.Range(0, parents.Count)];
139	                NewChild(mother, father, Rng.Range(0, Math.Max(1, Math.Min(13, motherAge - 16))));
140	            }
141	
142	            KnitTogether(Band.Members);
143	            SeedCulture(Band.Members);
144	            for (int i = 0; i < 3; i++) Neighbors.Add(NewNeighborBand());
145	            // A band that has been living here a while: a few days of food in each hearth.
146	            foreach (var h in Band.Households)
147	            {
148	                h.Food.AddMeat(1.3 * h.Members.Count);
149	                h.Food.Plants = 1.3 * h.Members.Count;
150	                h.Food.Stored = 2 * h.Members.Count;
151	            }
152	            Band.Materials.Flint = 6; Band.Materials.Tools = 25;
153	            RefreshForagePatches();
154	            Chronicle.Write(Clock, Importance.Major,
155	                $"The {Band.Name} band, {Band.Members.Count} people, made camp in a {World[(int)Band.CampX, (int)Band.CampY].Terrain.ToString().ToLower()} by the river.");
156	        }
