165	        /// <summary>Someone not (yet) of this band: founders, and the people of neighboring bands.</summary>
166	        Person MakeStranger(double ageYears, Sex sex)
167	        {
168	            var p = new Person(_nextPersonId++, _names.Next(Rng), sex, Clock.Day - (long)(ageYears * SimClock.DaysPerYear));
169	            for (int i = 0; i < p.Mind.Length; i++) p.Mind[i] = Inheritance.Founder(Rng);
170	            for (int i = 0; i < p.Body.Length; i++) p.Body[i] = Inheritance.Founder(Rng);
171	            for (int i = 0; i < p.Interests.Length; i++) p.Interests[i] = Inheritance.Clamp01(Rng.Normal(0.35, 0.15));
172	            SeedSkills(p, ageYears);
173	            foreach (var id in StartingKnowledge()) p.Knows.Add(id);
174	            return p;
175	        }
176	
177	        Person NewChild(Person mother, Person father, double ageYears)
178	        {
179	            var p = MakeChildOf(mother, father, ageYears);
180	            Join(p);
181	            return p;
182	        }
183	
184	        Person MakeChildOf(Person mother, Person father, double ageYears)
185	        {
186	            var p = new Person(_nextPersonId++, _names.Next(Rng), Rng.Chance(0.5) ? Sex.Female : Sex.Male, Clock.Day - (long)(ageYears * SimClock.DaysPerYear));
187	            p.Mother = mother; p.Father = father;
188	            mother.Children.Add(p); father.Children.Add(p);
189	            for (int i = 0; i < p.Mind.Length; i++) p.Mind[i] = Inheritance.Blend(Rng, mother.Mind[i], father.Mind[i]);
190	            for (int i = 0; i < p.Body.Length; i++) p.Body[i] = Inheritance.Blend(Rng, mother.Body[i], father.Body[i]);
191	            for (int i = 0; i < p.Interests.Length; i++)
192	                p.Interests[i] = Inheritance.Clamp01((mother.Interests[i] + father.Interests[i]) / 2 * 0.4 + Rng.Normal(0.2, 0.1));
193	            SeedSkills(p, ageYears);
194	            p.AddAffinity(mother, 0.5); p.AddAffinity(father, 0.4);
195	            mother.AddAffinity(p, 0.6); father.AddAffinity(p, 0.5);
196	            foreach (var id in StartingKnowledge()) p.Knows.Add(id);
197	            return p;
198	        }
199	
200	        void SeedSkills(Person p, double age)
201	        {
202	            double grown = Inheritance.Clamp01(age / 25);
203	            p.Skills[(int)Skill.Foraging] = grown * Rng.Range(0.4, 0.9);
204	            p.Skills[(int)Skill.Hunting] = age >= 14 ? grown * Rng.Range(0.2, 0.8) * (0.5 + p.M(MindTrait.Boldness)) : 0;
205	            p.Skills[(int)Skill.Knapping] = age >= 12 ? grown * Rng.Range(0.1, 0.7) : 0;
206	            p.Skills[(int)Skill.Fire] = grown * 0.5;
207	            p.Skills[(int)Skill.Caring] = age >= 14 ? Rng.Range(0.2, 0.6) : 0;
208	            p.Skills[(int)Skill.Teaching] = age >= 20 ? Rng.Range(0.1, 0.5) : 0;
209	            p.Skills[(int)Skill.Cooking] = grown * Rng.Range(0.2, 0.6);
210	        }
