287	        /// <summary>
288	        /// An hour of living: the stomach empties (faster when working hard), and nourishment
289	        /// follows whether there's food in it. Infants live on their mother's milk, or another
290	        /// nursing woman's.
291	        /// </summary>
292	        void Metabolize(Person p)
293	        {
294	            double age = p.AgeYears(Clock);
295	            double effort = p.Current switch
296	            {
297	                Sleep _ => 0.7, Rest _ => 0.8, Socialize _ => 0.9, Eat _ => 0.9,
298	                Hunt _ => 1.6, Forage _ => 1.2, GatherFlint _ => 1.3, GatherWood _ => 1.3, _ => 1.0,
299	            };
300	            // Burn from the stomach first, then from the body's reserves.
301	            double burn = effort / 24;
302	            double fromStomach = Math.Min(p.Stomach, burn);
303	            p.Stomach -= fromStomach;
304	            p.Reserve = Math.Max(0, p.Reserve - (burn - fromStomach));
305	            // A well-filled stomach slowly lays down reserves, up to what this body can carry.
306	            double maxReserve = 5 + 4 * p.B(BodyTrait.Build);
307	            if (p.Stomach > 0.5 && p.Reserve < maxReserve)
308	            {
309	                double store = Math.Min(0.02, p.Stomach - 0.5);
310	                p.Stomach -= store;
311	                p.Reserve += store;
312	            }
313	            if (age >= 2)
314	            {
315	                p.Satiety = Math.Min(1, p.Reserve / 3);
316	                return;
317	            }
318	            {
319	                var nurse = p.Mother != null && p.Mother.Alive && Band.Members.Contains(p.Mother) ? p.Mother
320	                    : Band.Members.FirstOrDefault(w => w.Sex == Sex.Female && w.Children.Any(c => c != p && c.Alive && c.AgeYears(Clock) < 2));
321	                // A nursing mother keeps her milk up by drawing on her own body; it only fails when she's badly starved.
322	                double milk = nurse == null ? 0 : Math.Min(1, nurse.Satiety / 0.4);
323	                double own = Math.Min(1, p.Reserve / 3);
324	                bool softFood = p.Home != null && p.Home.SoftFoodUntil >= Clock.Day;
325	                double fed = age < 1 ? milk : softFood ? Math.Max(milk, own) : (milk + own) / 2;
326	                p.Satiety += (fed - p.Satiety) * 0.02;
327	            }
328	        }
