451	            double weak = 1.3 - immune;
452	            // Colds are always around in any human group, and spread more when people huddle in winter.
453	            double coldSeason = Clock.Season == Season.Winter ? 3 : Clock.Season == Season.Autumn ? 1.5 : 1;
454	            // Small children catch everything going: their bodies haven't met these germs yet.
455	            double young = age < 5 ? 2.5 : age < 14 ? 1.5 : 1;
