using System;
using System.Collections.Generic;
using System.Linq;
using Anthro.Sim.Core;
using Anthro.Sim.World;

namespace Anthro.Sim.Ecology
{
    /// <summary>
    /// The valley is one corner of a wider region. Every species follows the same rules:
    /// the whole regional population breeds toward its capacity each spring; part of it comes into
    /// the valley for the warm season (fewer if the valley has proved dangerous); migratory animals
    /// leave again in autumn. Animals killed in the valley never go back to breed, so heavy hunting
    /// drains the region itself, fastest for slow breeders.
    /// </summary>
    public sealed class EcologySystem
    {
        readonly List<AnimalGroup> _groups = new List<AnimalGroup>();
        readonly Dictionary<Species, RegionalPool> _pools = new Dictionary<Species, RegionalPool>();
        readonly HashSet<Species> _goneFromRegion = new HashSet<Species>();
        int _nextId;

        public IReadOnlyList<AnimalGroup> Groups => _groups;

        public RegionalPool Pool(Species sp) => _pools[sp];

        public void Populate(Simulation sim)
        {
            foreach (var sp in Species.All) _pools[sp] = new RegionalPool(sp, sp.RegionalStart);
            foreach (var sp in Species.All) Arrive(sim, sp, quiet: true);
        }

        public int Total(Species sp) => _groups.Where(g => g.Species == sp).Sum(g => g.Count);

        public IEnumerable<AnimalGroup> Living(Species sp) => _groups.Where(g => g.Species == sp && !g.Gone);

        public void DailyUpdate(Simulation sim)
        {
            var season = sim.Clock.Season;
            foreach (var g in _groups)
            {
                if (g.Gone) continue;
                double toCamp = WorldMap.Distance(g.X, g.Y, sim.Band.CampX, sim.Band.CampY);
                g.Fear = Math.Max(0, g.Fear - 0.04);
                if (!g.Species.Predator && toCamp < WorldMap.FromMeters(1500)) g.Fear = Math.Min(1, g.Fear + 0.03);

                if (g.Species.Predator) FollowPrey(g);
                else if (WorldMap.Distance(g.X, g.Y, g.TargetX, g.TargetY) < WorldMap.FromMeters(300) || sim.Rng.Chance(0.05) || (g.Fear > 0.3 && toCamp < WorldMap.FromMeters(3000)))
                    ChooseRange(sim, g, season);
                Step(g, WorldMap.FromMeters(g.Species.Predator ? 6000 : 3000));
            }

            foreach (var pack in _groups.Where(g => g.Species.Predator && !g.Gone).ToList()) PackHunts(sim, pack);

            if (sim.Clock.DayOfYear == 0 && sim.Clock.Day > 0) NewYear(sim);
            if (sim.Clock.DayOfYear == (int)Season.Winter * SimClock.DaysPerSeason) Depart(sim);
            _groups.RemoveAll(g => g.Gone);
        }

        /// <summary>A hunt, a near miss or a kill frightens the herd.</summary>
        public void Startle(AnimalGroup g, double amount) => g.Fear = Math.Min(1, g.Fear + amount);

        /// <summary>Each kill teaches the region the valley is dangerous, in proportion to how many the region can spare.</summary>
        public void RecordKill(Species sp)
        {
            var pool = _pools[sp];
            pool.DangerMemory = Math.Min(0.9, pool.DangerMemory + 3.0 / sp.RegionalCapacity);
        }

        void NewYear(Simulation sim)
        {
            foreach (var sp in Species.All)
            {
                Breed(sim, sp);
                _pools[sp].DangerMemory *= 0.6;
                Arrive(sim, sp, quiet: false);
            }
        }

        void Breed(Simulation sim, Species sp)
        {
            var pool = _pools[sp];
            var local = Living(sp).ToList();
            int valley = local.Sum(g => g.Count);
            int total = pool.Count + valley;
            if (total == 0)
            {
                if (_goneFromRegion.Add(sp))
                    sim.Chronicle.Write(sim.Clock, Importance.Major, $"No {sp.Plural} are left anywhere in the region.");
                return;
            }
            int change = (int)Math.Round(total * sp.BirthRate * (1 - (double)total / sp.RegionalCapacity));
            int toValley = valley == 0 ? 0 : (int)Math.Round(change * (double)valley / total);
            pool.Count = Math.Max(0, pool.Count + change - toValley);
            for (int i = 0; i < Math.Abs(toValley) && local.Count > 0; i++)
                local[sim.Rng.Range(0, local.Count)].Count += Math.Sign(toValley);
        }

        /// <summary>
        /// Animals come in until the valley holds its share of the region, scaled down by how
        /// dangerous the valley has proved. Arrivals are random, so lean years happen.
        /// </summary>
        void Arrive(Simulation sim, Species sp, bool quiet)
        {
            var pool = _pools[sp];
            int valley = Total(sp);
            double target = (pool.Count + valley) * sp.ValleyShare * (1 - pool.DangerMemory);
            double lambda = Math.Max(0, target - valley) * (sp.MigratoryFraction > 0 ? 1.0 : 0.4);
            int arrivals = Math.Min(pool.Count, sim.Rng.Poisson(lambda));
            pool.Count -= arrivals;
            while (arrivals > 0)
            {
                int size = Math.Min(arrivals, sim.Rng.Range(sp.GroupMin, sp.GroupMax + 1));
                arrivals -= size;
                var edge = sim.World[sim.Rng.Chance(0.5) ? 0 : sim.World.Size - 1, sim.Rng.Range(0, sim.World.Size)];
                var g = new AnimalGroup(_nextId++, sp, size, edge.X, edge.Y);
                if (quiet) { var c = RandomCell(sim.World, sim.Rng, sp.SummerTerrain); g.X = c.X; g.Y = c.Y; }
                ChooseRange(sim, g, Season.Spring);
                _groups.Add(g);
            }
            if (!quiet && valley == 0 && Total(sp) == 0 && pool.Count > 0 && sp.Huntable && sp.MigratoryFraction > 0)
                sim.Chronicle.Write(sim.Clock, Importance.Notable, $"No {sp.Plural} came into the valley this spring.");
        }

        void Depart(Simulation sim)
        {
            foreach (var g in _groups.Where(g => !g.Gone && g.Species.MigratoryFraction > 0))
            {
                int leaving = (int)Math.Round(g.Count * g.Species.MigratoryFraction);
                g.Count -= leaving;
                _pools[g.Species].Count += leaving;
            }
        }

        void ChooseRange(Simulation sim, AnimalGroup g, Season season)
        {
            var terrain = season == Season.Winter ? g.Species.WinterTerrain : g.Species.SummerTerrain;
            if (g.Fear <= 0.3)
            {
                var spot = NearbyCell(sim.World, sim.Rng, g.X, g.Y, WorldMap.FromMeters(4000), terrain);
                g.TargetX = spot.X; g.TargetY = spot.Y;
                return;
            }
            // Frightened animals pick ground well away from people.
            Cell best = NearbyCell(sim.World, sim.Rng, g.X, g.Y, WorldMap.FromMeters(6000), terrain);
            for (int i = 0; i < 5; i++)
            {
                var c = NearbyCell(sim.World, sim.Rng, g.X, g.Y, WorldMap.FromMeters(6000), terrain);
                if (WorldMap.Distance(c.X, c.Y, sim.Band.CampX, sim.Band.CampY) > WorldMap.Distance(best.X, best.Y, sim.Band.CampX, sim.Band.CampY)) best = c;
            }
            g.TargetX = best.X; g.TargetY = best.Y;
        }

        void FollowPrey(AnimalGroup pack)
        {
            var prey = _groups.Where(g => !g.Gone && !g.Species.Predator && g.Species.Huntable && g.Species.Size < 4)
                .OrderBy(g => WorldMap.Distance(g.X, g.Y, pack.X, pack.Y)).FirstOrDefault();
            if (prey != null) { pack.TargetX = prey.X; pack.TargetY = prey.Y; }
        }

        /// <summary>Wolves hunt like people do: get close before the prey bolts. A big kill feeds the pack for days.</summary>
        void PackHunts(Simulation sim, AnimalGroup pack)
        {
            pack.Hunger = Math.Min(1.5, pack.Hunger + 0.25);
            if (pack.Hunger < 0.5) return;
            var prey = _groups.Where(g => !g.Gone && !g.Species.Predator && g.Species.Huntable && g.Species.Size < 4)
                .Where(g => WorldMap.Distance(g.X, g.Y, pack.X, pack.Y) < WorldMap.FromMeters(1500))
                .OrderByDescending(g => g.Species.Meat).FirstOrDefault();
            if (prey != null)
            {
                Startle(prey, 0.15);
                double catchChance = 0.45 * (1 - prey.FlightDistance / 120) * (pack.Species.Speed / (pack.Species.Speed + prey.Species.Speed) * 2);
                if (sim.Rng.Chance(catchChance))
                {
                    prey.Count--;
                    pack.Hunger -= Math.Min(1.3, prey.Species.Meat * 0.04 * 5 / Math.Max(1, pack.Count));
                }
            }
            if (pack.Hunger > 1.2 && sim.Rng.Chance(0.05))
            {
                pack.Count--;
                if (pack.Gone) sim.Chronicle.Write(sim.Clock, Importance.Notable, "The last of the wolf pack starved.");
            }
        }

        static void Step(AnimalGroup g, double maxCells)
        {
            double dx = g.TargetX - g.X, dy = g.TargetY - g.Y;
            double d = Math.Sqrt(dx * dx + dy * dy);
            if (d < 0.01) return;
            double s = Math.Min(maxCells, d) / d;
            g.X += dx * s; g.Y += dy * s;
        }

        static Cell RandomCell(WorldMap map, Rng rng, Terrain terrain)
        {
            for (int i = 0; i < 200; i++)
            {
                var c = map[rng.Range(0, map.Size), rng.Range(0, map.Size)];
                if (c.Terrain == terrain) return c;
            }
            return map[rng.Range(0, map.Size), rng.Range(0, map.Size)];
        }

        static Cell NearbyCell(WorldMap map, Rng rng, double x, double y, double radius, Terrain terrain)
        {
            for (int i = 0; i < 40; i++)
            {
                int cx = (int)(x + rng.Range(-radius, radius)), cy = (int)(y + rng.Range(-radius, radius));
                if (map.InBounds(cx, cy) && map[cx, cy].Terrain == terrain) return map[cx, cy];
            }
            return RandomCell(map, rng, terrain);
        }
    }
}
