using System;
using System.Collections.Generic;
using System.Linq;
using Anthro.Sim.Core;

namespace Anthro.Sim.World
{
    /// <summary>
    /// Builds a valley: a meandering river with marsh along it, forest and grassland on the slopes,
    /// and hills on one side holding flint, a cave and ochre. Clay sits on the riverbank.
    /// </summary>
    public static class WorldGen
    {
        /// <summary>Scales every cell's plant food. The calibration knob for carrying capacity.</summary>
        public const double PlantDensity = 2.4;

        public static WorldMap Generate(Rng rng, int size = 100)
        {
            var map = new WorldMap(size);
            int seed = (int)rng.NextUInt();
            double phase = rng.Range(0, Math.PI * 2);
            int hillSide = rng.Chance(0.5) ? 1 : -1;

            for (int y = 0; y < size; y++)
            {
                double riverX = size / 2.0 + size * 0.12 * Math.Sin(y / (size / 7.0) + phase)
                    + (Fractal(seed, 0.5, y * 0.05) - 0.5) * 6;
                for (int x = 0; x < size; x++)
                {
                    double offset = x - riverX;
                    double dist = Math.Abs(offset);
                    double elev = dist / (size / 2.0)
                        + (Fractal(seed + 1, x * 0.08, y * 0.08) - 0.5) * 0.5
                        + Math.Max(0, hillSide * offset / size) * 0.9;
                    double moisture = Fractal(seed + 2, x * 0.1, y * 0.1) + (dist < 4 ? 0.35 : 0);

                    var cell = new Cell { X = x, Y = y, Elevation = elev };
                    if (dist < 0.8) cell.Terrain = Terrain.River;
                    else if (elev > 0.8) cell.Terrain = Terrain.Hills;
                    else if (moisture > 0.8 && dist < WorldMap.FromMeters(1200)) cell.Terrain = Terrain.Marsh;
                    else if (moisture > 0.5) cell.Terrain = Terrain.Forest;
                    else cell.Terrain = Terrain.Grassland;

                    AssignPlants(cell, seed, rng);
                    map.Cells[x, y] = cell;
                }
            }

            PlaceFeatures(map, rng);
            foreach (var c in map.All())
            {
                c.PlantStock = c.PlantCapacity * Cell.SeasonFactor(c.Plant, Season.Spring);
                c.WoodCapacity = Cell.WoodCapacityOf(c.Terrain);
                c.Wood = c.WoodCapacity;
            }
            return map;
        }

        static void AssignPlants(Cell c, int seed, Rng rng)
        {
            double n = Fractal(seed + 3, c.X * 0.15, c.Y * 0.15);
            switch (c.Terrain)
            {
                case Terrain.Marsh:
                    c.Plant = PlantFood.Roots; c.PlantCapacity = 5; c.Features |= Feature.Reeds; break;
                case Terrain.Forest:
                    c.Plant = n > 0.5 ? PlantFood.Nuts : PlantFood.Berries; c.PlantCapacity = 6; break;
                case Terrain.Grassland:
                    c.Plant = n > 0.6 ? PlantFood.WildGrain : n > 0.3 ? PlantFood.Roots : PlantFood.Greens;
                    c.PlantCapacity = 4; break;
                case Terrain.Hills:
                    c.Plant = PlantFood.Berries; c.PlantCapacity = 1.5; break;
                default:
                    c.Plant = PlantFood.None; c.PlantCapacity = 0; break;
            }
            // Per-cell plant food, calibrated so the range supports a real forager band (roughly 0.1
            // people per km² in a temperate climate) rather than an unrealistically packed one.
            c.PlantCapacity *= rng.Range(0.7, 1.3) * PlantDensity;
        }

    {
        public int Hides, Sinew, Bone, Flint;
        public double Tools;
    }

    public sealed class Band
    {
        public string Name = "";
        public readonly List<Person> Members = new List<Person>();
        public readonly List<Person> Dead = new List<Person>();
        /// <summary>People who left to live with neighboring bands.</summary>
        public readonly List<Person> Departed = new List<Person>();
        public readonly List<Household> Households = new List<Household>();

        /// <summary>All the food in camp, across households.</summary>
        public double FoodTotal => Households.Sum(h => h.Food.Total);
        public double MeatTotal => Households.Sum(h => h.Food.Meat);
        public readonly Materials Materials = new Materials();
        public double CampX, CampY;

        /// <summary>Waste around camp. Builds with people and days in one place; moving to a fresh site leaves it behind.</summary>
        public double Filth;

        /// <summary>
        /// The band's custom about who moves when a couple spans two bands: +1 the woman joins the man's
        /// people, -1 the man joins hers. Starts with no custom; forms from what couples actually do.
        /// </summary>
        public double ResidenceNorm;

        /// <summary>
        /// What this band finds attractive, by trait. Culture, not biology: it drifts with what
        /// the band admires, and it's how sexual selection pushes evolution.
        /// </summary>
        public readonly double[] AttractionMind = new double[TraitCounts.Mind];
        public readonly double[] AttractionBody = new double[TraitCounts.Body];

        public IEnumerable<Person> Adults(SimClock clock) => Members.Where(p => p.IsAdult(clock));

        /// <summary>
        /// How dangerous the band looks to a predator: healthy, armed adults plus fire.
        /// Predators lurk when this is high and attack when it's low.
        /// </summary>
        public double Strength(SimClock clock) =>
            3 + Members.Where(p => { var a = p.AgeYears(clock); return a >= 14 && a < 60; })
                .Sum(p => p.Health * (1 - p.Injury) * (0.5 + p.B(BodyTrait.Strength)));

        public bool AnyoneKnows(string stageId) => Members.Any(p => p.Knows.Contains(stageId));
    }
}

