using System.Diagnostics;
using Anthro.Runner;
using Anthro.Sim;
using Anthro.Sim.Core;
using Anthro.Sim.Ecology;

// Usage: dotnet run --project Anthro.Runner -- [--seed N] [--years N] [--detail] [--quiet]
Console.OutputEncoding = System.Text.Encoding.UTF8;
ulong seed = 1;
int years = 100;
bool detail = false, quiet = false, families = false, kids = false;
string[] grant = Array.Empty<string>();
for (int i = 0; i < args.Length; i++)
{
    switch (args[i])
    {
        case "--seed": seed = ulong.Parse(args[++i]); break;
        case "--years": years = int.Parse(args[++i]); break;
        case "--detail": detail = true; break;
        case "--quiet": quiet = true; break;
        case "--families": families = true; break;
        case "--kids": kids = true; break;
        case "--grant": grant = args[++i].Split(',', StringSplitOptions.RemoveEmptyEntries); break;
        case "--profile": Anthro.Sim.Core.Profiler.Enabled = true; break;
    }
}

var webPath = WebLoader.Find();
var web = webPath != null ? WebLoader.Load(webPath) : null;
if (web == null) Console.WriteLine("(discovery-web.json not found; running with built-in starting knowledge)");
else
{
    var problems = web.Validate().ToList();
    Console.WriteLine($"Discovery web: {web.Tiles.Count} skills, {web.Stages.Count} stages, {web.KnownAtStart.Count()} known at start.");
    foreach (var p in problems) Console.WriteLine($"  ! {p}");
}

var sim = Simulation.Create(seed, web);
// Testing only: hand the founding band some knowledge, to see what a technology does before discovery exists.
foreach (var m in sim.Band.Members) foreach (var g in grant) m.Knows.Add(g);
if (grant.Length > 0) Console.WriteLine($"Granted: {string.Join(", ", grant)}");
Console.WriteLine($"Seed {seed}. Running {years} years.\n");

if (!quiet)
{
    sim.Chronicle.Written += e =>
    {
        if (e.Importance == Importance.Detail && !detail) return;
        string mark = e.Importance == Importance.Major ? "■" : "·";
        Console.WriteLine($"  {mark} Y{e.Year,-3} {e.Season,-6} {e.Text}");
    };
}
foreach (var e in sim.Chronicle.Entries) Console.WriteLine($"  ■ Y{e.Year,-3} {e.Season,-6} {e.Text}");

sim.YearEnded += y =>
{
    if (kids) foreach (var c in sim.Band.Members.Where(m => m.AgeYears(sim.Clock) >= 2 && m.AgeYears(sim.Clock) < 15)) Console.WriteLine($"     kid {c.Name,-8} age {c.AgeYears(sim.Clock),4:F1} stomach {c.Stomach:F2} reserve {c.Reserve:F2} fed {c.Satiety:F2} health {c.Health:F2} doing {c.Current}");
    if (families) Console.WriteLine($"     food: needed {y.Needed:F0} gathered {y.Gathered:F0} hunted {y.Hunted:F0} eaten-at-camp {y.Eaten:F0} spoiled {y.Spoiled:F0} | adult hours: " + string.Join(", ", y.Hours.OrderByDescending(h => h.Value).Select(h => $"{h.Key} {h.Value}")));
using System;
using System.Collections.Generic;

namespace Anthro.Sim.Core
{
    public enum Importance { Detail, Notable, Major }

    public sealed class ChronicleEntry
    {
        public int Year;
        public Season Season;
        public int DayOfSeason;
        public Importance Importance;
        public string Text = "";

        public override string ToString() => $"Year {Year}, {Season}: {Text}";
    }

    /// <summary>The story log. Unity will read the same entries to raise notifications.</summary>
    public sealed class Chronicle
    {
        readonly List<ChronicleEntry> _entries = new List<ChronicleEntry>();

        public IReadOnlyList<ChronicleEntry> Entries => _entries;

        public event Action<ChronicleEntry>? Written;

        public void Write(SimClock clock, Importance importance, string text)
        {
            var entry = new ChronicleEntry
            {
                Year = clock.Year,
                Season = clock.Season,
                DayOfSeason = clock.DayOfSeason,
                Importance = importance,
                Text = text,
            };
            _entries.Add(entry);
            Written?.Invoke(entry);
        }
    }
}
