using Anthro.Sim.People;

namespace Anthro.Sim.Activities
{
    public enum Verb { Sleep, Rest, Socialize, Forage, Hunt, Knap, GatherFlint, Care, Play, WatchAndLearn, Eat, Cook, GatherWood, Preserve }

    /// <summary>
    /// Something a person is doing, as a sequence of steps. <see cref="Step"/> names the current
    /// step so a viewer can pick the right animation (e.g. "stalk", "butcher").
    /// </summary>
    public abstract class Activity
    {
        protected readonly Person P;

        protected Activity(Person person) { P = person; }

        public abstract Verb Verb { get; }
        public string Step { get; protected set; } = "";
        public bool Done { get; protected set; }

        /// <summary>Whether a group activity (a hunt) may pull this person away.</summary>
        public virtual bool Interruptible => true;

        public virtual void Begin(Simulation sim) { }

        /// <summary>Advance one in-game hour.</summary>
        public abstract void Hour(Simulation sim);

        public override string ToString() => string.IsNullOrEmpty(Step) ? Verb.ToString() : $"{Verb} ({Step})";
    }

    /// <summary>A fixed-length activity at or near camp.</summary>
    public abstract class TimedActivity : Activity
    {
        int _hoursLeft;

        protected TimedActivity(Person person, int hours) : base(person) { _hoursLeft = hours; }

        public override void Hour(Simulation sim)
        {
            OnHour(sim);
            P.Fatigue = People.Inheritance.Clamp01(P.Fatigue + FatiguePerHour);
            if (--_hoursLeft <= 0) { OnEnd(sim); Done = true; }
        }

        protected virtual double FatiguePerHour => 0.03;
        protected abstract void OnHour(Simulation sim);
        protected virtual void OnEnd(Simulation sim) { }
    }
}
using System;
using System.Collections.Generic;
using System.Linq;
using Anthro.Sim.Core;
using Anthro.Sim.People;

namespace Anthro.Sim.Activities
{
    public readonly struct Option
    {
        public readonly Verb Verb;
        public readonly double Score;
        public readonly Func<Activity> Make;

        public Option(Verb verb, double score, Func<Activity> make) { Verb = verb; Score = score; Make = make; }
    }

    /// <summary>
    /// What a person could do right now, and how much each pulls on them:
    ///   need it meets × expected result + interest + trait pulls + social pull.
    /// The same scores answer "what would I rather be doing?" when someone asks them to join a hunt.
    /// </summary>
    public static class Decider
    {
        public static Activity Choose(Simulation sim, Person p)
        {
            var clock = sim.Clock;
            if (clock.IsNight)
            {
                int hour = clock.Hour;
                return new Sleep(p, Math.Max(1, hour >= clock.Sunrise ? 24 - hour + clock.Sunrise : clock.Sunrise - hour));
            }
            double age = p.AgeYears(clock);
            if (age < 3)
                return age >= 1 && p.Stomach < 0.4 && sim.Band.FoodTotal > 0 ? new Eat(p) : (Activity)new Play(p);

            // Noise before taking the max: a softmax in disguise, so people aren't perfectly predictable.
            return Options(sim, p).Select(o => (score: o.Score + sim.Rng.Normal(0, 0.15), o.Make))
                .OrderByDescending(o => o.score).First().Make();
        }

        /// <summary>The strongest pull other than <paramref name="except"/>: what this person gives up to do it.</summary>
        public static double BestAlternative(Simulation sim, Person p, Verb except)
        {
            var others = Options(sim, p).Where(o => o.Verb != except).ToList();
            return others.Count == 0 ? 0 : others.Max(o => o.Score);
        }

        public static double ScoreOf(Simulation sim, Person p, Verb verb)
        {
            foreach (var o in Options(sim, p)) if (o.Verb == verb) return o.Score;
            return double.NegativeInfinity;
        }

        /// <summary>
        /// How strongly someone feels the need to put food by for winter: how lean they remember
        /// winters being, how patient they are, and how far short of enough the camp's keeping-food is.
        /// Only felt as winter approaches.
        /// </summary>
        public static double Foresight(Simulation sim, Person p)
