            var camp = CampSites(band.Rng, 40).FirstOrDefault(c => Bands.All(b => b == band || b.Band.Members.Count == 0
                           || WorldMap.Distance(c.X, c.Y, b.Band.CampX, b.Band.CampY) > WorldMap.FromMeters(8000)))
