                    {
                        _together.Add(key);
                        a.Chronicle.Write(Clock, Importance.Notable, $"The {b.Band.Name} band made camp nearby.");
                        b.Chronicle.Write(Clock, Importance.Notable, $"The {a.Band.Name} band made camp nearby.");
