            bool aMoves = Cost(a, bandA, bandB) <= Cost(b, bandB, bandA);
            var mover = aMoves ? a : b;
            var partner = aMoves ? b : a;
            var from = aMoves ? bandA : bandB;
            var to = aMoves ? bandB : bandA;
