namespace Anthro.Sim.Ecology
{
    /// <summary>A herd, pack or warren that moves and lives as one unit.</summary>
    public sealed class AnimalGroup
    {
        public readonly int Id;
        public readonly Species Species;
        public int Count;
        public double X, Y;
        public double TargetX, TargetY;

        /// <summary>Predators only. Above 0.75 a pack is hungry enough to get bold.</summary>
        public double Hunger;

        /// <summary>
        /// Rises when hunted or crowded by people, fades with quiet days. Frightened animals spot
        /// hunters sooner and keep away from camp.
        /// </summary>
        public double Fear;

        public AnimalGroup(int id, Species species, int count, double x, double y)
        {
            Id = id; Species = species; Count = count; X = x; Y = y; TargetX = x; TargetY = y;
        }

        public bool Gone => Count <= 0;

        /// <summary>How close hunters must get before the animals bolt, in meters.</summary>
        public double FlightDistance => Species.Wariness * (1 + Fear) * 60;
    }

    /// <summary>The animals of one species living beyond the valley's edges.</summary>
        public double Meat;
        public int Hides, Sinew, Bone;

        public Terrain SummerTerrain, WinterTerrain;

        public static readonly Species Deer = new Species
        {
            Name = "deer", Plural = "deer", GroupMin = 6, GroupMax = 14,
            RegionalStart = 320, RegionalCapacity = 500, BirthRate = 0.4, ValleyShare = 0.15, MigratoryFraction = 0.6,
            Size = 1.5, Wariness = 0.6, Aggression = 0.05, Speed = 0.6,
            Huntable = true, Meat = 40, Hides = 1, Sinew = 2, Bone = 3,
            SummerTerrain = Terrain.Grassland, WinterTerrain = Terrain.Forest,
        };

        public static readonly Species Boar = new Species
        {
            Name = "boar", Plural = "boar", GroupMin = 3, GroupMax = 7,
            RegionalStart = 70, RegionalCapacity = 120, BirthRate = 0.6, ValleyShare = 0.25,
            Size = 2.0, Wariness = 0.4, Aggression = 0.6, Speed = 0.4,
            Huntable = true, Meat = 30, Hides = 1, Sinew = 1, Bone = 2,
            SummerTerrain = Terrain.Forest, WinterTerrain = Terrain.Forest,
        };

        public static readonly Species Rabbit = new Species
        {
            Name = "rabbit", Plural = "rabbits", GroupMin = 10, GroupMax = 20,
            RegionalStart = 350, RegionalCapacity = 600, BirthRate = 1.5, ValleyShare = 0.12,
            Size = 0.3, Wariness = 0.8, Aggression = 0, Speed = 0.7,
            Huntable = true, Meat = 2,
            SummerTerrain = Terrain.Grassland, WinterTerrain = Terrain.Grassland,
        };

        public static readonly Species Mammoth = new Species
        {
            Name = "mammoth", Plural = "mammoths", GroupMin = 4, GroupMax = 8,
            RegionalStart = 30, RegionalCapacity = 40, BirthRate = 0.08, ValleyShare = 0.2, MigratoryFraction = 1.0,
            Size = 6, Wariness = 0.35, Aggression = 0.8, Speed = 0.3,
            Huntable = true, Meat = 400, Hides = 3, Sinew = 6, Bone = 12,
            SummerTerrain = Terrain.Grassland, WinterTerrain = Terrain.Grassland,
        };

        public static readonly Species Wolf = new Species
        {
            Name = "wolf", Plural = "wolves", GroupMin = 5, GroupMax = 8,
            RegionalStart = 24, RegionalCapacity = 36, BirthRate = 0.35, ValleyShare = 0.3,
            Size = 1.2, Wariness = 0.5, Aggression = 0.7, Speed = 0.7,
            Predator = true,
            SummerTerrain = Terrain.Forest, WinterTerrain = Terrain.Forest,
