        public int RegionalStart;
        /// <summary>What the whole region can support.</summary>
        public int RegionalCapacity;
        /// <summary>Yearly growth rate when far below capacity.</summary>
        public double BirthRate;
        /// <summary>Share of the regional population that spends the warm season in the valley, if nothing scares them off.</summary>
        public double ValleyShare;
        /// <summary>Share of the valley's animals that leave for the winter and rejoin the region.</summary>
        public double MigratoryFraction;

        // ---- Body and behavior ----
        /// <summary>How much damage it takes to kill, in units of one good spear hit.</summary>
        public double Size;

