using System;
using Anthro.Sim.Core;

namespace Anthro.Sim.People
{
    public enum MindTrait { Curiosity, Boldness, Sociability, Patience, Openness, Temper, Warmth, Credulity, Charisma, Aptitude, Resilience }

    public enum BodyTrait { Strength, Dexterity, Endurance, ColdTolerance, Height, Build, Immunity }

    public enum Interest { StoneEarth, Wood, Plants, Animals, Water, Fire, People, Spirits, Sky, Art, Healing, Hearth }

    public enum Skill { Foraging, Hunting, Knapping, Fire, Crafting, Caring, Teaching, Cooking }

    public static class TraitCounts
    {
        public static readonly int Mind = Enum.GetValues(typeof(MindTrait)).Length;
        public static readonly int Body = Enum.GetValues(typeof(BodyTrait)).Length;
        public static readonly int Interests = Enum.GetValues(typeof(Interest)).Length;
        public static readonly int Skills = Enum.GetValues(typeof(Skill)).Length;
    }

    public static class Inheritance
    {
        /// <summary>Parents' average plus drift, with an occasional bigger jump (a new variation).</summary>
        public static double Blend(Rng rng, double mother, double father)
        {
            double drift = rng.Chance(0.03) ? rng.Normal(0, 0.25) : rng.Normal(0, 0.08);
            return Clamp01((mother + father) / 2 + drift);
        }

        public static double Founder(Rng rng) => Clamp01(rng.Normal(0.5, 0.15));

        public static double Clamp01(double v) => v < 0 ? 0 : v > 1 ? 1 : v;
    }
}
using System;
using Anthro.Sim.Core;

namespace Anthro.Sim.World
{
    public enum Terrain { River, Marsh, Grassland, Forest, Hills }

    [Flags]
    public enum Feature { None = 0, Flint = 1, Clay = 2, Ochre = 4, Cave = 8, Reeds = 16 }

    public enum PlantFood { None, Greens, Roots, Berries, Nuts, WildGrain }

    /// <summary>One ~50 m square of the valley.</summary>
    public sealed class Cell
    {
        public int X, Y;
        public Terrain Terrain;
        public double Elevation;
        public Feature Features;
        public PlantFood Plant;
        public double PlantCapacity;
        public double PlantStock;
        /// <summary>Dead wood lying about, in days of a cooking fire. Forests hold the most; it builds back slowly.</summary>
        public double Wood, WoodCapacity;

        public bool Has(Feature f) => (Features & f) != 0;

        /// <summary>How much of a plant's capacity the season supports. Above 1 is a glut.</summary>
        public static double SeasonFactor(PlantFood plant, Season season)
        {
            switch (plant)
            {
                case PlantFood.Greens: return Pick(season, 1.0, 0.8, 0.4, 0.05);
                case PlantFood.Roots: return Pick(season, 0.6, 0.8, 1.0, 0.3);
                case PlantFood.Berries: return Pick(season, 0.1, 1.2, 0.8, 0.0);
                case PlantFood.Nuts: return Pick(season, 0.0, 0.2, 1.5, 0.1);
                case PlantFood.WildGrain: return Pick(season, 0.0, 0.6, 1.3, 0.0);
                default: return 0;
            }
        }

        /// <summary>
        /// How much food value a unit of this plant carries relative to an average plant food. Nuts and
        /// grain are dense; greens are mostly water.
        /// </summary>
        public static double Richness(PlantFood plant) => plant switch
        {
            PlantFood.Nuts => 1.4, PlantFood.WildGrain => 1.3, PlantFood.Roots => 1.0, PlantFood.Berries => 0.8, PlantFood.Greens => 0.5, _ => 0,
        };

        /// <summary>Nuts and grain keep for months; everything else spoils within days.</summary>
        public static bool Storable(PlantFood plant) => plant == PlantFood.Nuts || plant == PlantFood.WildGrain;

        static double Pick(Season s, double spring, double summer, double autumn, double winter) =>
            s == Season.Spring ? spring : s == Season.Summer ? summer : s == Season.Autumn ? autumn : winter;

        public static double WoodCapacityOf(Terrain t) => t switch
        {
            Terrain.Forest => 40, Terrain.Marsh => 4, Terrain.Hills => 4, Terrain.Grassland => 2, _ => 0,
        };

        /// <summary>Stock drifts toward what the season supports: grows when below, rots when above.</summary>
using System;
using System.Linq;
using Anthro.Sim.People;
using Anthro.Sim.World;

namespace Anthro.Sim.Activities
{
    /// <summary>Walk out → gather → walk back. Yield depends on the patch, skill, age and interest.</summary>
    public sealed class Forage : Activity
    {
        public const double FallbackPerHour = 0.4;

        enum Phase { Out, Gather, Back }

        Phase _phase;
        Cell? _patch;
        int _travel, _left, _hours;
        double _gathered, _storable, _eatenHere;

        public Forage(Person p) : base(p) { }
        public override Verb Verb => Verb.Forage;

        public override void Begin(Simulation sim)
        {
            // Curious people sometimes try somewhere farther afield; that's how the band learns its land.
            if (sim.Rng.Chance(P.M(MindTrait.Curiosity) * 0.25))
            {
                _patch = null;
                for (int i = 0; i < 20 && _patch == null; i++)
                {
                    double reach = WorldMap.FromMeters(7000);
                    int x = (int)(sim.Band.CampX + sim.Rng.Range(-reach, reach)), y = (int)(sim.Band.CampY + sim.Rng.Range(-reach, reach));
                    if (sim.World.InBounds(x, y) && sim.World[x, y].PlantCapacity > 0) _patch = sim.World[x, y];
                }
                P.Nudge(Interest.Plants, 0.002);
            }
            else
            {
                // Someone stocking up for winter goes for food that keeps.
                bool stocking = Decider.Foresight(sim, P) > 0.15;
                var choices = sim.ForagePatches.Where(c => c.PlantStock > 0.3 && (!stocking || Cell.Storable(c.Plant))).Take(8).ToList();
                if (choices.Count == 0) choices = sim.ForagePatches.Where(c => c.PlantStock > 0.3).Take(8).ToList();
                _patch = choices.Count == 0 ? null : choices[sim.Rng.Range(0, choices.Count)];
            }
            _travel = _patch == null ? 1 : Math.Max(1, sim.TravelHours(WorldMap.Distance(_patch.X, _patch.Y, sim.Band.CampX, sim.Band.CampY), P));
            _left = _travel;
            _phase = Phase.Out;
            Step = "walking out";
        }

        public override void Hour(Simulation sim)
        {
            _hours++;
            P.Fatigue = Inheritance.Clamp01(P.Fatigue + 0.04);
            switch (_phase)
            {
                case Phase.Out:
                    if (--_left > 0) return;
                    _phase = Phase.Gather;
                    _left = 4 + (int)(P.M(MindTrait.Patience) * 3);

