void Daily()
{
    var season = Clock.Season;
    // Each cell regrows on its own, so the map is shared out across the processor's cores.
    using (Profiler.Measure("daily plants"))
        System.Threading.Tasks.Parallel.For(0, World.Size, x => { for (int y = 0; y < World.Size; y++) World.Cells[x, y].DailyRegrow(season); });
    using (Profiler.Measure("daily ecology")) Ecology.DailyUpdate(this);
    foreach (var band in Bands.ToList()) band.Daily();

