// ---- Meat ----------------------------------------------------------------------------------

/// <summary>
/// A kill is shared. How much stays with the hunters' families and how much goes round the
/// camp follows the band's sharing norm. Those who receive think better of the hunters.
/// </summary>
public void ShareMeat(double rations, List<Person> party, Person? killer)
{
    if (rations <= 0 || Band.Households.Count == 0) return;
    var adults = Band.Members.Where(m => m.AgeYears(Clock) >= 16).ToList();
    double sharing = adults.Count == 0 ? 0.6 : adults.Average(m => m.Expect.Get(Expectations.Norm("sharing"), 0.6));
    double kept = rations * (1 - sharing) * 0.6;

    var hunterHomes = party.Where(m => m.Alive && Band.Members.Contains(m)).Select(m => (home: HomeOf(m), weight: m == killer ? 2.0 : 1.0)).ToList();
    double totalWeight = hunterHomes.Sum(h => h.weight);
    foreach (var (home, weight) in hunterHomes) home.Food.AddMeat(totalWeight <= 0 ? 0 : kept * weight / totalWeight);

    double rest = rations - (totalWeight > 0 ? kept : 0);
    int mouths = Band.Households.Sum(h => h.Members.Count);
    foreach (var h in Band.Households)
    {
        h.Food.AddMeat(mouths <= 0 ? 0 : rest * h.Members.Count / mouths);
        if (killer == null || h.Members.Any(m => party.Contains(m))) continue;
        foreach (var a in h.Adults(Clock))
        {
            a.AddTrust(killer, 0.02);
            a.AddAffinity(killer, 0.01);
        }
    }
}

/// <summary>A hunt that comes back empty while the band is going hungry dents trust in whoever led it.</summary>
public void BlameFailedHunt(Person leader, List<Person> party)
{
    if (_hardship < 0.2) return;
    foreach (var a in Band.Members)
        if (!party.Contains(a) && a.AgeYears(Clock) >= 16) a.AddTrust(leader, -0.03 * _hardship);
}

// ---- Asking for food ---------------------------------------------------------------------

static bool AtCamp(Person p) => !(p.Current is Forage || p.Current is Hunt || p.Current is GatherFlint || p.Current is GatherWood || p.Current is Visit || p.Current is Fish);

/// <summary>
/// A hungry person whose household is short asks another household. The one asked weighs it by
/// their warmth, the band's sharing norm, how fond of and how trusting they are of the asker,
/// kinship, and how much their own family can spare. Giving builds trust; refusing breeds resentment.
/// Returns how much food came into the asker's household.
/// </summary>
public double AskForFood(Person asker, double amount)
{
    if (asker.LastAskDay == Clock.Day) return 0;
    asker.LastAskDay = Clock.Day;
    var home = HomeOf(asker);
    var options = Band.Households
        .Where(h => h != home && h.Food.Total > 0.5 && h.DaysOfFood > home.DaysOfFood + 0.5)
        .Select(h => (h, giver: h.Adults(Clock).Where(AtCamp).OrderByDescending(a => a.M(MindTrait.Warmth)).FirstOrDefault()))
        .Where(x => x.giver != null)
        .OrderByDescending(x => (asker.IsKin(x.giver!) ? 1 : 0) + asker.GetAffinity(x.giver!) + asker.GetTrust(x.giver!))
        .Take(2)
        .ToList();

    foreach (var (h, giverOrNull) in options)
    {
        var giver = giverOrNull!;
        double scarcity = Inheritance.Clamp01(1 - h.DaysOfFood / 4) * 0.8;
        double willing = giver.Expect.Get(Expectations.Norm("sharing"), 0.6) * 0.5 + giver.M(MindTrait.Warmth) * 0.4
                         + giver.GetAffinity(asker) * 0.4 + giver.GetTrust(asker) * 0.3 + (giver.IsKin(asker) ? 0.4 : 0) - scarcity
                         + Rng.Normal(0, 0.1);
        double spare = Math.Max(0, h.Food.Total - h.Members.Count * 0.9);
        double give = Math.Min(spare, amount * Inheritance.Clamp01(willing));
        if (give > 0.05)
        {
            MoveFood(h, home, give, out _);
            asker.AddTrust(giver, 0.04);
            asker.AddAffinity(giver, 0.02);
            giver.AddAffinity(asker, 0.01);
            ThisYear.Shared += give;
            return give;
        }
        // Being turned away stings in proportion to how much they could have spared.
        double couldSpare = Inheritance.Clamp01(spare / Math.Max(0.1, amount));
        asker.AddTrust(giver, -0.05 * couldSpare);
        asker.AddAffinity(giver, -0.03 * couldSpare);
        ThisYear.Refusals++;
    }
    return 0;
}

// ---- Theft and fights ------------------------------------------------------------------

static double Norm(Person p, string name, double fallback) => p.Expect.Get(Expectations.Norm(name), fallback);

/// <summary>How fond / trusting someone is of a household, on average over its adults.</summary>
double FondOf(Person p, Household h) { var a = h.Adults(Clock).ToList(); return a.Count == 0 ? 0 : a.Average(x => p.GetAffinity(x)); }
double TrustOf(Person p, Household h) { var a = h.Adults(Clock).ToList(); return a.Count == 0 ? 0.5 : a.Average(x => p.GetTrust(x)); }

/// <summary>How hungry a household is: its people's nourishment.</summary>
static double HungerOf(Household h) => h.Members.Count == 0 ? 0 : 1 - h.Members.Average(m => m.Satiety);

/// <summary>
/// Desperation, a cold heart, a band that doesn't hold sharing sacred, nerve, and a restless
/// culture may lead someone to take food. Who they take from follows their relationships:
/// never kin, rarely people they're fond of, most readily a family they distrust that
/// turned them away while sitting on plenty. A busy camp deters it.
/// Returns how much was taken into the thief's household.
/// </summary>
public double ConsiderTheft(Person thief, double amount)
{
    if (thief.LastTheftThoughtDay == Clock.Day) return 0;
    thief.LastTheftThoughtDay = Clock.Day;
    // Real desperation: the body's reserves running out, not a skipped meal.
    double desperate = 1 - thief.Satiety;
    if (desperate < 0.4) return 0;

    var home = HomeOf(thief);
    var victim = Band.Households
        .Where(h => h != home && h.Food.Total > 1 && !h.Members.Any(m => m.IsKin(thief)))
        .OrderByDescending(h => h.DaysOfFood * (1 - FondOf(thief, h)) * (1.5 - TrustOf(thief, h)))
        .FirstOrDefault();
    if (victim == null) return 0;

    double resentment = Math.Max(0, 0.5 - TrustOf(thief, victim)) * 2;
    double propensity = desperate * (1 - thief.M(MindTrait.Warmth)) * (1.2 - Norm(thief, "sharing", 0.6))
                        * (0.4 + thief.M(MindTrait.Boldness) * 0.6) * (1 - FondOf(thief, victim)) * (1 + resentment)
                        * (1.3 - Norm(thief, "peace", 0.6));
    int watching = Band.Members.Count(m => m != thief && m.Home != home && m.AgeYears(Clock) >= 10 && AtCamp(m) && !(m.Current is Sleep));
    double seen = 1 - Math.Pow(0.85, watching);
    if (!Rng.Chance(propensity * 0.3 * (1 - seen * 0.8))) return 0;

    double took = Math.Min(amount, victim.Food.Total * 0.3);
    MoveFood(victim, home, took, out _);
    ThisYear.Thefts++;
    if (!Rng.Chance(seen)) return took;

    // How big a deal it is: how much was taken against the family's needs, how hungry they
    // already were, and how hard the times are.
    double perDay = Math.Max(0.5, victim.Members.Count * 0.9);
    double severity = Math.Min(4, (0.5 + took / perDay) * (1 + HungerOf(victim)) * (1 + _hardship));

    var wronged = victim.Adults(Clock).ToList();
    foreach (var a in wronged)
    {
        // Betrayal by someone you were fond of cuts deepest.
        double betrayal = 1 + a.GetAffinity(thief);
        a.AddTrust(thief, -0.15 * severity * betrayal);
        a.AddAffinity(thief, -0.1 * severity * betrayal);
    }
    // Bystanders take sides by whom they're closer to.
    foreach (var o in Band.Members.Where(m => m.Home != home && !wronged.Contains(m) && m.AgeYears(Clock) >= 14))
    {
        double side = wronged.Count == 0 ? 0 : wronged.Average(w => o.GetAffinity(w)) - o.GetAffinity(thief);
        o.AddTrust(thief, -0.04 * severity * (1 + Math.Max(0, side)));
    }
    thief.Prestige = Math.Max(0, thief.Prestige - 0.1 * severity);
    var face = wronged.Where(AtCamp).OrderByDescending(a => a.M(MindTrait.Temper)).FirstOrDefault();
    Chronicle.Write(Clock, severity > 2 ? Importance.Major : Importance.Notable,
        $"{thief.Name} was caught taking food from {(face ?? wronged.FirstOrDefault())?.Name ?? "another"}'s family{(severity > 2 ? " while their own children went hungry" : "")}.");
    if (face != null)
    {
        double flare = Inheritance.Clamp01((face.M(MindTrait.Temper) + thief.M(MindTrait.Temper)) / 2 - 0.25)
                       * Math.Min(1.5, severity / 1.5) * (1.3 - Norm(face, "peace", 0.6));
        if (Rng.Chance(flare)) Fight(face, thief, "stolen food", 0.7 + severity * 0.2);
    }
    return took;
}

/// <summary>
/// A fight: strength and temper against strength and temper. How hard it goes depends on how
/// much is at stake. The loser is hurt, sometimes badly; both come away with less fondness and
/// trust, and the loser's family resents the winner. A killing horrifies most of the band.
/// </summary>
public void Fight(Person a, Person b, string over, double intensity = 1)
{
    double Power(Person p) => p.B(BodyTrait.Strength) * (0.6 + 0.4 * p.M(MindTrait.Temper)) * p.Health + Rng.Range(0, 0.4);
    var (winner, loser) = Power(a) >= Power(b) ? (a, b) : (b, a);
    loser.Injury = Inheritance.Clamp01(loser.Injury + Rng.Range(0.1, 0.5) * (0.5 + winner.B(BodyTrait.Strength)) * intensity);
    winner.Injury = Inheritance.Clamp01(winner.Injury + Rng.Range(0, 0.15) * intensity);
    foreach (var (x, y) in new[] { (a, b), (b, a) }) { x.AddAffinity(y, -0.4); x.AddTrust(y, -0.2); }
    foreach (var kin in Band.Members.Where(m => m != loser && m.IsKin(loser)))
    {
        kin.AddAffinity(winner, -0.15);
        kin.AddTrust(winner, -0.1);
    }
    ThisYear.Fights++;
    if (loser.Injury >= 0.95)
    {
        Kill(loser, $"killed in a fight with {winner.Name}");
        // A killing in the band horrifies most people, most of all those who loved the dead.
        foreach (var m in Band.Members)
            m.Expect.Learn(m, Expectations.Norm("peace"), 1, 0.6, 0.2 + 0.4 * m.GetAffinity(loser));
    }
    else Chronicle.Write(Clock, Importance.Notable, $"{a.Name} and {b.Name} came to blows over {over}; {loser.Name} was hurt.");
}

/// <summary>
/// When one household sits on plenty while others go hungry in hard times, resentment can
/// boil over. An angry, desperate person may rally others to take the food. Each person weighs
/// joining by their own hunger, how much they resent the hoarders, how fond of them they are,
/// their temper, and how much their culture holds back from violence. The hoarders' kin and
/// friends may stand with them. The stronger side carries it; in a desperate, violent culture
/// people can die.
/// </summary>
void ConsiderRaid()
{
    if (_hardship < 0.3 || Band.Households.Count < 3) return;
    var hoard = Band.Households.OrderByDescending(h => h.DaysOfFood).First();
    var others = Band.Households.Where(h => h != hoard).ToList();
    // What provokes it is inequality people can see: one family clearly better off while most go hungry.
    var sorted = others.Select(h => h.DaysOfFood).OrderBy(d => d).ToList();
    double median = sorted[sorted.Count / 2];
    if (hoard.DaysOfFood < Math.Max(1.5, median * 3) || others.Average(HungerOf) < 0.4) return;

    double Resent(Person p) => Math.Max(0, 0.5 - TrustOf(p, hoard)) * 2 + Math.Max(0, 0.3 - FondOf(p, hoard));
    var instigator = Band.Members
        .Where(p => p.Home != hoard && p.AgeYears(Clock) >= 16 && p.Satiety < 0.6 && AtCamp(p))
        .OrderByDescending(p => (p.M(MindTrait.Temper) + p.M(MindTrait.Boldness)) / 2 * (Resent(p) + (1 - p.Satiety) * 0.5) * (1.3 - Norm(p, "peace", 0.6)))
        .FirstOrDefault();
    if (instigator == null) return;
    double anger = (instigator.M(MindTrait.Temper) + instigator.M(MindTrait.Boldness)) / 2 * (Resent(instigator) + (1 - instigator.Satiety) * 0.5)
                   * (1.3 - Norm(instigator, "peace", 0.6));
    if (!Rng.Chance(anger * 0.1)) return;

    var raiders = Band.Members.Where(p => p.Home != hoard && p.AgeYears(Clock) >= 16 && p.Health > 0.4 && AtCamp(p)
        && (1 - p.Satiety) * (1 - p.M(MindTrait.Warmth) * 0.5) + Resent(p) + p.M(MindTrait.Temper) * 0.3
           + p.GetAffinity(instigator) * 0.3 - FondOf(p, hoard) * 0.8 - Norm(p, "peace", 0.6) * 0.5 > 0.6).ToList();
    if (!raiders.Contains(instigator)) raiders.Add(instigator);
    if (raiders.Count < 2) return;
    var defenders = Band.Members.Where(p => !raiders.Contains(p) && p.AgeYears(Clock) >= 16 && AtCamp(p)
        && (p.Home == hoard || FondOf(p, hoard) + TrustOf(p, hoard) - (1 - p.Satiety) > 0.8)).ToList();

    double Might(IEnumerable<Person> side) => side.Sum(p => p.B(BodyTrait.Strength) * p.Health * (0.6 + 0.4 * p.M(MindTrait.Temper)));
    double attack = Might(raiders) * Rng.Range(0.8, 1.2), defend = Might(defenders) * 1.3;
    double fury = 0.8 + (1 - raiders.Average(r => Norm(r, "peace", 0.6))) + raiders.Average(r => 1 - r.Satiety) * 0.5;
    ThisYear.Raids++;

    // Blows are traded on both sides.
    int clashes = Math.Min(raiders.Count, Math.Max(1, defenders.Count));
    for (int i = 0; i < clashes && defenders.Count > 0; i++)
    {
        var r = raiders[Rng.Range(0, raiders.Count)];
        var d = defenders[Rng.Range(0, defenders.Count)];
        if (r.Alive && d.Alive) Fight(r, d, "the hoarded food", fury);
    }
    foreach (var r in raiders) foreach (var h in hoard.Adults(Clock)) { r.AddAffinity(h, -0.2); h.AddAffinity(r, -0.4); h.AddTrust(r, -0.4); }

    if (attack > defend)
    {
        double seized = hoard.Food.Total * 0.7;
        var homes = raiders.Where(r => r.Alive && r.Home != null).Select(r => r.Home!).Distinct().ToList();
        foreach (var h in homes) MoveFood(hoard, h, seized / homes.Count, out _);
        // Taking by force that worked teaches the raiders that it pays.
        foreach (var r in raiders.Where(r => r.Alive)) r.Expect.Learn(r, Expectations.Norm("peace"), 0, 0.6, 0.3);
        Chronicle.Write(Clock, Importance.Major,
