                                                    && o.AgeYears(Clock) >= 16 && o.GetAffinity(p) > 0.4)
                    .OrderByDescending(o => p.GetAffinity(o)).FirstOrDefault();
                double alternative = rival == null ? 0 : p.GetAffinity(rival) + Attraction(rival) * 0.3;
                int young = p.Children.Count(c => c.Alive && c.AgeYears(Clock) < 10);
