            if (maturity > 0.8 && p.BandGrievance.Count > 0 && p.Health > 0.6)
            {
                Simulation? foe = null;
                double anger = 0;
                foreach (var b in sim.Region.Bands)
                {
                    if (b == sim || b.Extinct) continue;
                    double g = p.GetBandGrievance(b.Id);
                    if (g > anger && WorldMap.Distance(b.Band.CampX, b.Band.CampY, band.CampX, band.CampY) < Region.KnownRange) { anger = g; foe = b; }
                }
                if (foe != null && anger > 1)
                {
                    int youngKids = p.Children.Count(c => c.Alive && c.AgeYears(clock) < 10);
                    double odds = (double)foe.Band.Members.Count / Math.Max(1, band.Members.Count);
                    double v = anger / (anger + 4) * (0.3 + p.M(MindTrait.Temper)) * (1 + Simulation.Expects(p, Act.Attack, Relation.Outsider) / 5)
                               - Math.Min(1.5, odds) * 0.3 * (1.2 - p.M(MindTrait.Boldness) * 0.6)
                               - youngKids * 0.05 * p.W(Drive.Family);
                    var f = foe;
                    if (v > 0) options.Add(new Option(Verb.Raid, v, () => new Raid(p, f)));
                }
            }
            // Calling others to take a hearth's food by force: when angry at a household, or hungry
            // while it sits on plenty, and enough people are about to come along.
            if (maturity > 0.8 && (MaxGrievance(p) > 1.5 || hunger > 0.6))
            {
                int about = sim.AwakeInCampCount;
                if (about >= 2)
                {
                    Household? target = null;
                    double best = 0;
                    foreach (var h in band.Households)
                    {
                        if (h == home || Simulation.Spare(h) < 1) continue;
                        double anger = h.Adults(clock).Select(a => p.GetGrievance(a)).DefaultIfEmpty(0).Max();
                        double plenty = Math.Min(1, Simulation.Spare(h) / Math.Max(1, home.Members.Count * 2));
                        var rel = sim.RelationTo(p, h);
                        var owner = h.Adults(clock).OrderByDescending(a => p.GetAffinity(a)).FirstOrDefault();
                        double v = (anger / (anger + 3) + hunger * plenty) * p.M(MindTrait.Temper) * (1 + Simulation.Expects(p, Act.Take, rel, true) / 5)
                                   - (owner == null ? 0 : Simulation.Guilt(p, owner)) / 10;
                        if (v > best) { best = v; target = h; }
                    }
                    if (target != null) { var t = target; options.Add(new Option(Verb.Rally, best, () => new Rally(p, t))); }
                }
            }
