def patch(p, pairs):
    s = open(p, encoding='utf-8').read()
    for a, b in pairs:
        assert a in s, (p, a[:90])
        s = s.replace(a, b, 1)
    open(p, 'w', encoding='utf-8').write(s)

# ---- Decider: raid and rally values come from the sim, so joiners weigh the same thing.
patch('Activities/Decider.cs', [
    ('''                if (foe != null && anger > 1)
                {
                    int youngKids = p.Children.Count(c => c.Alive && c.AgeYears(clock) < 10);
                    double odds = (double)foe.Band.Members.Count / Math.Max(1, band.Members.Count);
