# ---- JointActs: values, and joining against the best alternative.
patch('JointActs.cs', [
    ('''        /// <summary>
        /// Should this person join a group going to take a household's food by force?
        /// </summary>
        double WantsToJoinRaid(Person p, Person leader, Household hearth)
        {
            if (p.Home == hearth || p.AgeYears(Clock) < 16 || p.Health < 0.4 || !AwakeInCamp(p)) return -1;
            var rel = RelationTo(p, hearth);
            var owner = hearth.Adults(Clock).OrderByDescending(a => p.GetAffinity(a)).FirstOrDefault();
            double hunger = 1 - (p.Home?.Members.Select(m => m.Satiety).DefaultIfEmpty(1).Min() ?? p.Satiety);
            double plenty = Math.Min(1, Spare(hearth) / Math.Max(1, (p.Home?.Members.Count ?? 1) * 2));
            double anger = AngerAt(p, hearth);
            return hunger * plenty * 1.5 + anger / (anger + 3)
                   + p.GetAffinity(leader) * 0.5 + (p.GetTrust(leader) - 0.5)
                   + Expects(p, Act.Take, rel, true) / 5
                   - (owner == null ? 0 : Guilt(p, owner)) / 5
                   - p.W(Drive.Safety) * 0.3
                   + p.M(MindTrait.Temper) * 0.3
                   + Rng.Normal(0, 0.1);
        }''',
     '''        /// <summary>
        /// What going with others to take a household's food by force is worth to this person:
        /// their family's hunger against that hearth's plenty, their anger at it, and what seen
        /// takes have brought them, against guilt and fear. Same scale as their other options.
        /// </summary>
        public double RallyValue(Person p, Household hearth)
        {
            if (p.Home == hearth) return double.NegativeInfinity;
            var rel = RelationTo(p, hearth);
            var owner = hearth.Adults(Clock).OrderByDescending(a => p.GetAffinity(a)).FirstOrDefault();
            double hunger = 1 - (p.Home?.Members.Select(m => m.Satiety).DefaultIfEmpty(1).Min() ?? p.Satiety);
            double plenty = Math.Min(1, Spare(hearth) / Math.Max(1, (p.Home?.Members.Count ?? 1) * 2));
            double anger = AngerAt(p, hearth);
            double defenders = hearth.Adults(Clock).Sum(Might);
            return (anger / (anger + 3) + hunger * plenty) * (0.3 + p.M(MindTrait.Temper)) * (1 + Expects(p, Act.Take, rel, true) / 5)
                   - (owner == null ? 0 : Guilt(p, owner)) / 10 - defenders * 0.1 * p.W(Drive.Safety);
        }

        /// <summary>How much being asked by this person pulls someone along: fondness, trust, and following them before.</summary>
        static double Pull(Person p, Person leader) =>
            p.GetAffinity(leader) * 0.5 + (p.GetTrust(leader) - 0.5) + Following(p, leader) * 0.3;

        /// <summary>Joins a group act if it, plus being asked, beats the best other thing they'd do now.</summary>
        bool Joins(Person p, Person leader, double value, Verb verb)
        {
            if (p.AgeYears(Clock) < 16 || p.Health < 0.4 || !AwakeInCamp(p) || double.IsNegativeInfinity(value)) return false;
            return value + Pull(p, leader) + Rng.Normal(0, 0.1) > Decider.BestAlternative(this, p, verb);
        }'''),
    ('''        /// <summary>Should this person stand with a household that's being raided?</summary>
        double WantsToDefend(Person p, Household hearth, List<Person> raiders)
        {
            if (raiders.Contains(p) || p.AgeYears(Clock) < 16 || p.Health < 0.4 || !AwakeInCamp(p)) return -1;
            if (p.Home == hearth) return 2;
            double bond = hearth.Adults(Clock).Select(a => (p.IsKin(a) ? 0.8 : 0) + p.GetAffinity(a)).DefaultIfEmpty(0).Max();
            double angerAtRaiders = raiders.Select(r => p.GetGrievance(r)).DefaultIfEmpty(0).Max();
            double fondOfRaiders = raiders.Select(r => p.GetAffinity(r) + (p.IsKin(r) ? 0.8 : 0)).DefaultIfEmpty(0).Max();
            return bond + angerAtRaiders / (angerAtRaiders + 3) - fondOfRaiders * 0.7 + p.M(MindTrait.Boldness) * 0.3 + Rng.Normal(0, 0.1);
        }''',
     '''        /// <summary>
        /// Does this person stand with a household that's being raided, or stay out of it? Their bond
        /// with the household (their own hearth most of all) and anger at the raiders, against fondness
        /// for the raiders and fear of them.
        /// </summary>
        bool Defends(Person p, Household hearth, List<Person> raiders)
        {
            if (raiders.Contains(p) || p.AgeYears(Clock) < 16 || p.Health < 0.4 || !AwakeInCamp(p)) return false;
            double bond = p.Home == hearth ? 1.5 * p.W(Drive.Family)
                : hearth.Adults(Clock).Select(a => (p.IsKin(a) ? 0.8 : 0) + p.GetAffinity(a)).DefaultIfEmpty(0).Max();
            double angerAtRaiders = raiders.Select(r => p.GetGrievance(r)).DefaultIfEmpty(0).Max();
            double fondOfRaiders = raiders.Select(r => p.GetAffinity(r) + (p.IsKin(r) ? 0.8 : 0)).DefaultIfEmpty(0).Max();
            double fear = raiders.Sum(Might) / Math.Max(0.1, Might(p) * 3) * 0.3 * p.W(Drive.Safety);
            return bond + angerAtRaiders / (angerAtRaiders + 3) - fondOfRaiders * 0.7 + p.M(MindTrait.Boldness) * 0.3 - fear + Rng.Normal(0, 0.1) > 0;
        }'''),
    ('''                if (p != leader && WantsToJoinRaid(p, leader, hearth) > 0.6) raiders.Add(p);''',
     '''                if (p != leader && Joins(p, leader, RallyValue(p, hearth), Verb.Rally)) raiders.Add(p);'''),
    ('''            var defenders = Band.Members.Where(p => WantsToDefend(p, hearth, raiders) > 0.6).ToList();''',
     '''            var defenders = Band.Members.Where(p => Defends(p, hearth, raiders)).ToList();'''),
    # War raids
    ('''            // How strong the other band looks against how many of us would likely go.
            double theirMight = target.Band.Members.Where(d => d.AgeYears(Clock) >= 16).Sum(Might);
            double ourMight = Band.Members.Where(d => d.AgeYears(Clock) >= 16).Sum(Might) * 0.4;
            double odds = theirMight / Math.Max(0.1, ourMight);
            double Wants(Person p)
            {
                if (p == leader) return 9;
                if (p.AgeYears(Clock) < 16 || p.Health < 0.5 || !AwakeInCamp(p)) return -1;
                double g = p.GetBandGrievance(target.Id);
                int kids = p.Children.Count(c => c.Alive && c.AgeYears(Clock) < 10);
                return g / (g + 4) + p.GetAffinity(leader) * 0.5 + (p.GetTrust(leader) - 0.5) + Expects(p, Act.Attack, Relation.Outsider) / 5
                       + p.Drives[(int)Drive.Standing] * 0.3 + p.M(MindTrait.Boldness) * 0.2
                       - kids * 0.05 * p.W(Drive.Family)
                       // Fear: the stronger they look, the less anyone wants to go, the more so with children to lose.
                       - Math.Min(1.5, odds) * (0.4 + kids * 0.1) * (1.2 - p.M(MindTrait.Boldness) * 0.6)
                       + Rng.Normal(0, 0.1);
            }
            var party = Band.Members.Where(p => Wants(p) > 0.6).ToList();''',
     '''            var party = Band.Members.Where(p => p == leader || p.Health >= 0.5 && Joins(p, leader, RaidValue(p, target), Verb.Raid)).ToList();'''),
    ('''        /// <summary>
        /// Someone calls for a raid on another band.''',
     '''        /// <summary>
        /// What raiding another band is worth to this person: their anger at it and what fighting
        /// outsiders has brought, how much they care about standing; against how strong that band
        /// looks next to their own, and children at home. Same scale as their other options.
        /// </summary>
        public double RaidValue(Person p, Simulation foe)
        {
            double anger = p.GetBandGrievance(foe.Id);
            int kids = p.Children.Count(c => c.Alive && c.AgeYears(Clock) < 10);
            double odds = foe.Band.Members.Count(m => m.AgeYears(Clock) >= 16) / (double)Math.Max(1, Band.Members.Count(m => m.AgeYears(Clock) >= 16));
            return anger / (anger + 4) * (0.3 + p.M(MindTrait.Temper)) * (1 + Expects(p, Act.Attack, Relation.Outsider) / 5)
                   + p.Drives[(int)Drive.Standing] * 0.2
                   - Math.Min(1.5, odds) * (0.3 + kids * 0.1) * (1.2 - p.M(MindTrait.Boldness) * 0.6) * p.W(Drive.Safety);
        }

        /// <summary>
        /// Someone calls for a raid on another band.'''),
    # Waking: dogs and the noise of a big party.
    ('''            var defenders = target.Band.Members.Where(d => d.AgeYears(Clock) >= 16 && d.Health > 0.3 && !(d.Current is Visit || d.Current is Hunt) && Rng.Chance(0.6)).ToList();''',
     '''            // Who wakes in time: anyone already up, and the rest by chance, likelier with dogs in camp
            // and a bigger, noisier party.
            double wake = 0.35 + (target.Band.AnyoneKnows("dog.camp") ? 0.4 : 0) + Math.Min(0.25, party.Count * 0.03);
            var defenders = target.Band.Members.Where(d => d.AgeYears(Clock) >= 16 && d.Health > 0.3 && !(d.Current is Visit || d.Current is Hunt)
