            int bx = (int)(x / Bucket), by = (int)(y / Bucket);
            for (int i = bx - 1; i <= bx + 1; i++)
                for (int j = by - 1; j <= by + 1; j++)
                    if (_buckets.TryGetValue(i * 1000 + j, out var list))
