anchor = '''        void Leave(Simulation sim, Person m)'''
assert anchor in s
s = s.replace(anchor, TACTICS.lstrip('\n') + '\n' + anchor, 1)
s = s.replace('''    public sealed class HuntParty''', '''    /// <summary>Ways a party closes in on its quarry.</summary>
    public enum Tactic { Stalk, Ambush, Drive, Surround, Persistence, FireDrive }

    public sealed class HuntParty''', 1)
open(H, 'w', encoding='utf-8').write(s)

# Bands start with their own hunting habits: a preference per tactic, with personal variation.
patch('Society.cs', [('''            foreach (var p in group)
            {
                double Vary(double v) => v + Rng.Normal(0, 0.3);''', '''            // Hunting habits: how well each way of closing in is expected to go, per animal.
            var habit = new Dictionary<Tactic, double>();
            foreach (Tactic t in Enum.GetValues(typeof(Tactic))) habit[t] = HuntParty.FallbackPerHour * Math.Max(0.3, Rng.Normal(1, 0.25));
            foreach (var p in group)
                foreach (var sp in Anthro.Sim.Ecology.Species.All)
                    if (sp.Huntable)
                        foreach (var kv in habit) p.Expect.Absorb(HuntParty.TacticTopic(kv.Key, sp), kv.Value * Math.Max(0.3, Rng.Normal(1, 0.1)), 1, kv.Value);
            foreach (var p in group)
            {
                double Vary(double v) => v + Rng.Normal(0, 0.3);''')])
print('ok')

