import os, re
os.chdir(r'C:/Users/nars7/Downloads/Ideas and Thoughts/Anthro/Anthro.Sim')

def patch(p, pairs):
    s = open(p, encoding='utf-8').read()
    for a, b in pairs:
        assert a in s, (p, a[:90])
        s = s.replace(a, b, 1)
    open(p, 'w', encoding='utf-8').write(s)

patch('People/Band.cs', [('''        public double ChildrenFollowMother = 0.3;''', '''        public double ChildrenFollowMother = 0.3;

        /// <summary>
        /// When this band counts someone as grown: able to pair, to join a raid, to stand for a
        /// hearth. A custom, not a rule of the body; bands differ, and rites could move it.
        /// </summary>
        public double ComingOfAge = 15;''')])

# The custom is set at founding (varied by band) and carried by splits.
patch('Simulation.cs', [
    ('''            Band.CampX = campX; Band.CampY = campY;
''', '''            Band.CampX = campX; Band.CampY = campY;
            Band.ComingOfAge = Math.Max(13, Math.Min(18, Rng.Normal(15, 1.2)));
''', ),
    ('''        bool Between(Person p, double min, double max)''', '''        /// <summary>Grown, as this band reckons it.</summary>
        public bool Grown(Person p) => p.AgeYears(Clock) >= Band.ComingOfAge;

        bool Between(Person p, double min, double max)'''),
    ('''            && Between(a, 16, a.Sex == Sex.Female ? 45 : 60) && Between(b, 16, b.Sex == Sex.Female ? 45 : 60);''',
     '''            && Grown(a) && Grown(b) && a.AgeYears(Clock) <= (a.Sex == Sex.Female ? 45 : 60) && b.AgeYears(Clock) <= (b.Sex == Sex.Female ? 45 : 60);'''),
])
patch('Social.cs', [('''            Band.ResidenceNorm = parent.Band.ResidenceNorm;''', '''            Band.ResidenceNorm = parent.Band.ResidenceNorm;
            Band.ComingOfAge = parent.Band.ComingOfAge;
            Band.ChildrenFollowMother = parent.Band.ChildrenFollowMother;''')])

# Social gates use the band's custom.
for f in ['Society.cs', 'JointActs.cs', 'Family.cs', 'Social.cs']:
    s = open(f, encoding='utf-8').read()
    s = re.sub(r'(\w+)\.AgeYears\(Clock\) < 16', r'!Grown(\1)', s)
    s = re.sub(r'(\w+)\.AgeYears\(Clock\) >= 16', r'Grown(\1)', s)
    open(f, 'w', encoding='utf-8').write(s)
s = open('Simulation.cs', encoding='utf-8').read()
s = s.replace('foreach (var a in Band.Members.Where(m => m.AgeYears(Clock) >= 16))', 'foreach (var a in Band.Members.Where(Grown))')
s = s.replace('Band.Members.Where(o => o != a && o.AgeYears(Clock) >= 16)', 'Band.Members.Where(o => o != a && Grown(o))')
s = s.replace('foreach (var m in Band.Members.Where(m => m.AgeYears(Clock) >= 16 && m != proposer))', 'foreach (var m in Band.Members.Where(m => Grown(m) && m != proposer))')
open('Simulation.cs', 'w', encoding='utf-8').write(s)
# Cross-band uses: the other band's own custom.
s = open('JointActs.cs', encoding='utf-8').read()
s = s.replace('foe.Band.Members.Count(m => Grown(m))', 'foe.Band.Members.Count(foe.Grown)')
s = s.replace('target.Band.Members.Where(d => Grown(d) &&', 'target.Band.Members.Where(d => target.Grown(d) &&')
open('JointActs.cs', 'w', encoding='utf-8').write(s)
print('ok')

