import os
os.chdir(r'C:/Users/nars7/Downloads/Ideas and Thoughts/Anthro/Anthro.Sim')

def patch(p, pairs):
    s = open(p, encoding='utf-8').read()
    for a, b in pairs:
        assert a in s, (p, a[:90])
        s = s.replace(a, b, 1)
    open(p, 'w', encoding='utf-8').write(s)

# ---- Shelter and clothing.
patch('People/Shelter.cs', [('''            if (band.AnyoneKnows("hide.needle")) p += 0.2;''', '''            if (band.AnyoneKnows("hide.needle")) p += 0.2;
            if (band.AnyoneKnows("hide.scrape")) p += 0.05;      // softened hides make better wraps
            if (band.AnyoneKnows("hide.awl")) p += 0.05;         // and sewn ones better still
            if (band.AnyoneKnows("shelter.lean")) p += 0.1;
            if (band.AnyoneKnows("shelter.hut")) p += 0.15;
            if (band.AnyoneKnows("shelter.pit")) p += 0.2;
            if (band.AnyoneKnows("fire.hearth")) p += 0.05;      // a built hearth holds its heat''')])

# ---- Travel: shoes on rough or cold ground.
patch('Simulation.cs', [('''            return snow && !p.Knows.Contains("hide.snowshoe") ? (int)Math.Ceiling(hours * 1.5) : hours;''',
                         '''            if (snow && !p.Knows.Contains("hide.snowshoe")) hours = (int)Math.Ceiling(hours * 1.5);
            // Shoes spare the feet on long walks over rough or frozen ground.
            if (p.Knows.Contains("hide.shoe")) hours = Math.Max(0, (int)Math.Round(hours * 0.9));
            return hours;''')])

# ---- Fire: a built hearth burns less wood for the same heat.
patch('Activities/HearthActivities.cs', [
    ('''                h.Food.DailySpoil''', '''                h.Food.DailySpoil'''),
])
patch('Simulation.cs', [('''                h.Fuel = Math.Max(0, h.Fuel - Cuisine.DailyBurn(season));''',
                         '''                h.Fuel = Math.Max(0, h.Fuel - Cuisine.DailyBurn(season) * (h.Knows("fire.hearth", Clock) ? 0.8 : 1));''')])
# ---- Axes: bigger loads of firewood.
patch('Activities/HearthActivities.cs', [('''                double load = Math.Min(_source.Wood, _work * 1.5 * (0.6 + P.B(BodyTrait.Strength) * 0.6) * Physiology.Maturity(P.AgeYears(sim.Clock)));''',
                                          '''                double axe = P.Knows.Contains("wood.axe") ? 1.5 : 1;
                double load = Math.Min(_source.Wood, _work * 1.5 * axe * (0.6 + P.B(BodyTrait.Strength) * 0.6) * Physiology.Maturity(P.AgeYears(sim.Clock)));''')])

# ---- Knapping: heat-treated flint flakes better; hafted tools last.
patch('Activities/CampActivities.cs', [('''            double made = 1.0 + 1.5 * P.S(Skill.Knapping) + 0.5 * P.B(BodyTrait.Dexterity);''',
                                        '''            double made = (1.0 + 1.5 * P.S(Skill.Knapping) + 0.5 * P.B(BodyTrait.Dexterity)) * (P.Knows.Contains("knap.heat") ? 1.3 : 1);''')])
patch('Simulation.cs', [('''            Band.Materials.Tools *= 0.997;''', '''            Band.Materials.Tools *= Band.AnyoneKnows("knap.haft") ? 0.998 : 0.997;   // hafted tools last longer''')])

# ---- Foraging know-how: plant lore, processing nuts, grinding, harvesting grain.
patch('Activities/FieldActivities.cs', [('''            double handling = 1.1 * (0.5 + P.S(Skill.Foraging)) * (1 + 0.3 * P.I(Interest.Plants)) * ageFactor;''',
'''            double handling = 1.1 * (0.5 + P.S(Skill.Foraging)) * (1 + 0.3 * P.I(Interest.Plants)) * ageFactor;
            var k = P.Knows;
            // Knowing plants well, and ways of getting more out of hard foods.
            if (k.Contains("forage.lore")) handling *= 1.15;
            if (patch.Plant == PlantFood.Nuts)
                handling *= (k.Contains("forage.nuts") ? 1.25 : 1) * (k.Contains("grind.pound") ? 1.1 : 1) * (k.Contains("grind.mortar") ? 1.1 : 1);
            if (patch.Plant == PlantFood.WildGrain)
                handling *= (k.Contains("grain.harvest") ? 1.4 : 1) * (k.Contains("grind.slab") ? 1.15 : 1);''')])

# ---- Fishing: harpoons in deep water; canoes reach farther along the river.
patch('Activities/Fishing.cs', [
    ('''            if (k.Contains("fish.net")) e = Math.Max(e, run ? 3.0 : 1.4);''', '''            if (k.Contains("fish.net")) e = Math.Max(e, run ? 3.0 : 1.4);
            if (k.Contains("bone.harpoon")) e = Math.Max(e, 1.1);'''),
    ('''                if (d > WorldMap.FromMeters(6000)) continue;
                known.Add''', '''                if (d > WorldMap.FromMeters(P.Knows.Contains("wood.canoe") ? 12000 : 6000)) continue;
                known.Add'''),
])

# ---- Weapons: spear-thrower darts, fletched and backed bows.
patch('Activities/Weapons.cs', [('''            new Weapon("spear-throwers", "atl.hook", 35, 1.3),''', '''            new Weapon("spear-throwers", "atl.hook", 35, 1.3),
            new Weapon("spear-thrower darts", "atl.dart", 40, 1.4),'''),
                                ('''            new Weapon("stone-tipped arrows", "bow.stone", 45, 1.6),''', '''            new Weapon("stone-tipped arrows", "bow.stone", 45, 1.6),
            new Weapon("fletched arrows", "bow.fletch", 55, 1.3),
            new Weapon("backed bows", "bow.backed", 60, 1.8),''')])

# ---- Wolves: torches and dogs keep them off.
patch('Simulation.cs', [('''            double strength = Band.Strength(Clock);''', '''            // Torches by night and dogs about camp keep wolves off.
            double strength = Band.Strength(Clock) * (Band.AnyoneKnows("fire.torch") ? 1.3 : 1) * (Band.AnyoneKnows("dog.lurk") ? 1.3 : 1) * (Band.AnyoneKnows("dog.camp") ? 1.5 : 1);''')])

# ---- Words and rites: stories carry know-how; shared rites and burial ease discontent and grief.
patch('Inventing.cs', [('''            double chance = 0.08 * strength * (0.3 + teacher.S(Skill.Teaching)) * Lean(learner.M(MindTrait.Aptitude));''',
                        '''            double chance = 0.08 * strength * (0.3 + teacher.S(Skill.Teaching)) * Lean(learner.M(MindTrait.Aptitude))
                            * (teacher.Knows.Contains("lang.story") ? 1.3 : 1) * (teacher.Knows.Contains("lang.count") ? 1.1 : 1);''')])
patch('Social.cs', [('''                    p.Discontent += (_hardship + Crowding(p) + Strife(p) - p.Discontent) * 0.012;''',
                     '''                {
                    // Shared rites hold a band together.
                    double cohesion = (Band.AnyoneKnows("lang.ritual") ? 0.8 : 1) * (Band.AnyoneKnows("burial.rites") ? 0.9 : 1);
                    p.Discontent += ((_hardship + Crowding(p) + Strife(p)) * cohesion - p.Discontent) * 0.012;
                }''')])
patch('Simulation.cs', [('''            foreach (var kin in Band.Members) if (kin.IsKin(p)) kin.Shift(Drive.Family, 0.01);''',
                         '''            foreach (var kin in Band.Members) if (kin.IsKin(p)) kin.Shift(Drive.Family, 0.01);
            // Laying the dead to rest eases the grief of those left (less of it turns to discontent).
            if (Band.AnyoneKnows("burial.cover"))
                foreach (var m in Band.Members) m.Discontent *= Band.AnyoneKnows("burial.goods") ? 0.9 : 0.95;''')])

# ---- Keeping food: counting and pots slow spoilage.
patch('People/Band.cs', [('''        public void DailySpoil(double temperatureC, int storageLevel, bool coldCaches)
        {''', '''        public void DailySpoil(double temperatureC, int storageLevel, bool coldCaches, double care = 1)
        {'''),
                         ('''            Stored *= 0.996 + storageLevel * 0.001;
            Dried *= 0.997 + storageLevel * 0.0007;''', '''            Stored *= 1 - (0.004 - storageLevel * 0.001) * care;
            Dried *= 1 - (0.003 - storageLevel * 0.0007) * care;''')])
patch('Simulation.cs', [('''                h.Food.DailySpoil(temp, Cuisine.StorageLevel(h, Clock), h.Knows("store.cold", Clock));''',
                         '''                // Keeping count of stores and sealing them in pots: less goes bad.
                double care = (h.Knows("lang.count", Clock) ? 0.9 : 1) * (h.Knows("pot.coil", Clock) ? 0.85 : 1);
                h.Food.DailySpoil(temp, Cuisine.StorageLevel(h, Clock), h.Knows("store.cold", Clock), care);''')])

# ---- Staying put: ways of life that make a camp worth keeping.
patch('Simulation.cs', [('''                double attachment = Math.Min(1, days / 180.0) * 0.25;''',
                         '''                double attachment = Math.Min(1, days / 180.0) * 0.25;
                // Returning to known seasonal camps, staying long, staying all year: each makes moving cost more.
                if (Band.AnyoneKnows("camp.return")) attachment *= 1.3;
                if (Band.AnyoneKnows("camp.long")) attachment *= 1.5;
                if (Band.AnyoneKnows("camp.year")) attachment *= 2;''')])

# ---- Adornment: ochre on the body makes a person more striking.
patch('Family.cs', [('''            p.GetAffinity(o) + judgesBy.Attraction(o) * 0.2 + Math.Max(0, Following(p, o)) * 0.2 - p.GetGrievance(o) * 0.15;''',
                     '''            p.GetAffinity(o) + judgesBy.Attraction(o) * 0.2 + Math.Max(0, Following(p, o)) * 0.2 - p.GetGrievance(o) * 0.15
            + (o.Knows.Contains("ochre.body") ? 0.05 : 0);''')])

# ---- Wild grain toward farming: clearing, scattering seed and choosing the best seed make the
#      grain stands near long-used camps richer; left alone, they slowly go back to wild.
patch('World/Cell.cs', [('''        public double PlantCapacity;''', '''        public double PlantCapacity;
        /// <summary>What the cell holds left wild; tending near camps raises <see cref="PlantCapacity"/> above it.</summary>
        public double WildCapacity;''')])
